INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-001-EXPANDED', '214', 'Article 214 Legal rules relating to conditions governing general meetings deliberations are subject to nullity of the irregular decision, at least whenever it is established that such irregularity has actually distorted the results obtained. This nullity may be invoked by all interested parties. It is covered when the deliberation is righted into order or by a one-year time limitation dating from the day of the meeting.', 'en', 'Commercial Code (Expanded), Article 214', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '215', 'Article 215 Shall be under the penalties provided for swindling, without prejudice to damaged, all those who, in a general meeting of share- or debenture-holders, shall have fraudulently created or attempted to create a fictitious majority, notably by declaring themselves the holders of shares belonging to rightful claimants who cannot vote, or by securing pledges of special advantages in the event of their voting in one sense or their abstaining from voting, or by using such powers as may be acquired for a consideration or by any other illegal means. Accomplices in these dealings shall be under the same penalties. CHAPTER 4 - Dissolution of joint-stock companies', 'en', 'Commercial Code (Expanded), Article 215', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '216', 'Article 216 (as modified by the Law of 23 November 1948) Joint-stock companies are dissolved by the termination of the period set or of the enterprise for which they have been contracted, or through impossibility of continuing the enterprise. They are equally dissolved by the will of the partners expressed in a general meeting within the terms provided under articles 202 & 204, as well as in ail the specific cases referred to in the Articles. In the event of the loss of three-quarters of the company''s capital, the Directors are required to convene a general meeting, for the purpose of deciding if the situation calls for the untimely dissolution of the company, the reduction of capital or any other appropriate measure.', 'en', 'Commercial Code (Expanded), Article 216', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '217', 'Article 217 At all events, whether the Directors have neglected the convening of a meeting, that this may not have been held due to short quorum, or that the meeting may have discarded dissolution, any shareholder retains the right to put the matter before the Court.', 'en', 'Commercial Code (Expanded), Article 217', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '218', 'Article 218 Once the decision is taken, this must be published whatever it may be.', 'en', 'Commercial Code (Expanded), Article 218', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '219', 'Article 219 In principle, liquidation is effected in accordance with the rules governing partnerships.', 'en', 'Commercial Code (Expanded), Article 219', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '220', 'Article 220 If they are not so designated by the Articles, the Liquidators shall be appointed by a vote of the ordinary general meeting, unless the case calls for advance dissolution in which event the extraordinary meeting appoints at the same time the Liquidators. If the general meeting fails to reach a decision, appointment shall lie with the Court.', 'en', 'Commercial Code (Expanded), Article 220', 'Electoral', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '221', 'Article 221 The supervisory commissioners, to whom is seconded .an expert appointed by the Court, remain in office and shall control the liquidation.', 'en', 'Commercial Code (Expanded), Article 221', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '222', 'Article 222 The Liquidators shall receive the Directors'' management accounts from the last balance sheet approved by the general meeting until the opening of liquidation. They shall approve them or submit to the Court such difficulties as might arise.', 'en', 'Commercial Code (Expanded), Article 222', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '223', 'Article 223 If the liquidation lasts for more than one year, the Liquidators are required to strike the annual balance sheet and publish it.', 'en', 'Commercial Code (Expanded), Article 223', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '224', 'Article 224 At the end of their operation, the Liquidators shall strike the final balance sheet, which shall apportion to each shareholder his share in the distribution of the company''s assets.', 'en', 'Commercial Code (Expanded), Article 224', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '225', 'Article 225 The supervisory commissioners shall draft a report on the accounts submitted by the liquidators. The ordinary general meeting shall approve these accounts and give final discharge to the Liquidators; otherwise it shall contest the accounts and the issue shall be brought before the Court. TITLE IV - LIMITED PARTNERSHIP COMPANIES', 'en', 'Commercial Code (Expanded), Article 225', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '226', 'Article 226 The partnership company which operates under a style comprises two categories of partners : the financed partners, who alone may be in charge of management and who are individually and jointly held for the payment of the company''s debts; the sleeping partners, leasers of funds who are held only up to the amount of their contribution.', 'en', 'Commercial Code (Expanded), Article 226', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '227', 'Article 227 There are two sorts of partnership companies : the simple partnership company and the partnership limited by shares.', 'en', 'Commercial Code (Expanded), Article 227', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '228', 'Article 228 The partnership company manifests itself to the public under a style comprising exclusively the names of the financed partners. When one financed partner exists, his name may be followed by the words "& Co." The sleeping partner who should allow the insertion of his name in the company style, would be held towards bona fide Third Parties as financed partner.', 'en', 'Commercial Code (Expanded), Article 228', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '229', 'Article 229 The financed partners, whether all manage together, or one or several manage for all, are under the same juridical statute as the member of a joint liability partnership.', 'en', 'Commercial Code (Expanded), Article 229', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '230', 'Article 230 The sleeping partner may not intervene in the management of the company in relation to Third Parties, even by virtue of a power of proxy. In the event of infringement to this prohibition, he would be held, indefinitely and jointly with the financed partners, for commitments resulting from his management; his liability, according to the number or seriousness of his interference, may be either limited to the consequence of the operations concluded, or extended to the whole of the company''s liabilities. However, the supervision exercised over the Manager''s operations, the advice and counsels which are given them, the authorization which is conferred on them to transact business in excess of their powers, do not constitute acts of interference.', 'en', 'Commercial Code (Expanded), Article 230', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '231', 'Article 231 The partnership company is governed by the rules of formation and dissolution applicable to private companies, even in what concerns sleeping partners.', 'en', 'Commercial Code (Expanded), Article 231', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '232', 'Article 232 In partnerships limited by shares, the company''s capital is divided into shares, and the sleeping partner is under the same legal statutes as the shareholder in joint-stock companies.', 'en', 'Commercial Code (Expanded), Article 232', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '233', 'Article 233 Partnership companies limited by shares are, whatever their object, submitted to the laws and usages of trade.', 'en', 'Commercial Code (Expanded), Article 233', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '234', 'Article 234 (as modified by the Law of 23 November 1948 and by Decree-Law ---------- (No 54 of 16 June 197? The legal regulations relating to joint-stock companies shall apply to the formation and operation of partnerships limited by shares.', 'en', 'Commercial Code (Expanded), Article 234', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '235', 'Article 235 All the obligations imposed by law on Directors of joint-stock companies apply to Managers of partnership companies limited by shares.', 'en', 'Commercial Code (Expanded), Article 235', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '236', 'Article 236 Supervisory commissioners must be at least three in number, including the chartered accountant designated by Court Ordinance. They may not be selected out of the financed partners. They deliberate in meetings and convene whenever control verification must be exercised. The Articles set the duration of the term of office of supervisory board. However, the first Board is appointed only for one year.', 'en', 'Commercial Code (Expanded), Article 236', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '237', 'Article 237 All the resolutions of general meetings; except those relating to the approval of management, are presumed to be approved by the financed partners, such approval to be expressed according to the rules laid down in the Articles. TITLE V - COMPANIES WITH SLIDING CAPITAL (COOPERATIVES)', 'en', 'Commercial Code (Expanded), Article 237', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '238', 'Article 238 Any company may set down in its Articles that its capital is variable; it shall then be submitted, alongside its general rules which are proper according to its special form, to the provisions of the following articles. This clause of the Articles must be published.', 'en', 'Commercial Code (Expanded), Article 238', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '239', 'Article 239 The capital of a company with sliding capital may, at any time, be increased following the adherence of new members or new payments effected by the partners, or reduced as a result of the total or partial withdrawal of contributions by partners. Except for contrary provisions in the Articles, such capital increases or reductions are effected freely, and are exempted from publicity.', 'en', 'Commercial Code (Expanded), Article 239', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '240', 'Article 240 (abrogated by Decree-Law N° 54 of 16 June 1977)', 'en', 'Commercial Code (Expanded), Article 240', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '241', 'Article 241 Articles shall determine a sum below which capital may not be reduced by the refund of contributions or withdrawals by partners. This sum may not be less than one-fifth of the company''s capital. This provision of the Articles is subject to publicity.', 'en', 'Commercial Code (Expanded), Article 241', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '242', 'Article 242 One clause of the Articles may confer on the general meeting the right to decide, by the majority vote required for the modification of the company''s Articles, that one or several of the partners shall no longer be partners in the company, without however being deprived of their acquired rights on the company''s reserves.', 'en', 'Commercial Code (Expanded), Article 242', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '243', 'Article 243 The partner who shall no longer be part of the company, either by his own volition, or as a result of a resolution of the general meeting, shall-be held for three years towards the partners and Third Parties in all commitments existing at the time of his withdrawal.', 'en', 'Commercial Code (Expanded), Article 243', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '244', 'Article 244 If the company has been vested with shareholding form, these shares are to remain registered even after they have been paid up. The Articles may empower the general meeting or the Board to oppose the conveyance of these securities, on condition however that such veto is not abusive in character.', 'en', 'Commercial Code (Expanded), Article 244', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '245', 'Article 245 The provisions of the present code do not apply to agricultural cooperative societies, except in so far as they do not derogate the special legislations governing these societies. TITLE VI - PARTICIPATING COMPANIES', 'en', 'Commercial Code (Expanded), Article 245', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '247', 'Article 247 A participating company distinguishes itself from other trading companies in that it has existence only among the parties concerned and is not intended to be known by third parties.', 'en', 'Commercial Code (Expanded), Article 247', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '248', 'Article 248 The parties'' agreements freely set down the partners'' reciprocal rights and obligations, their participation to profit and loss, provided that the general principles of the company''s contract are applied.', 'en', 'Commercial Code (Expanded), Article 248', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '249', 'Article 249 The existence of these agreements may be established according to the modes of proof accepted in commercial matters.', 'en', 'Commercial Code (Expanded), Article 249', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '250', 'Article 250 Participating companies are not submitted to the publicity formalities prescribed for all other trading companies.', 'en', 'Commercial Code (Expanded), Article 250', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '251', 'Article 251 The participating company does not constitute a juridical person.', 'en', 'Commercial Code (Expanded), Article 251', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '252', 'Article 252 Third Parties have no judicial links except with the one partner with whom they have contracted. Hut the contracting company which should reveal itself to Third Parties may be treated as a de facto company in relation to them.', 'en', 'Commercial Code (Expanded), Article 252', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '253', 'Article 253 No transferable and negotiable securities may be issued on the partners'' behalf. TITLE VII - LIMITED LIABILITY COMPANIES (See Decree-Law NO 35 of 5 August 1957) HOOK III GENERAL COMMERCIAL CONTRACTS AND CERTAIN COMMERCIAL CONTRACTS TITLE I - GENERAL PROVISIONS', 'en', 'Commercial Code (Expanded), Article 253', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '254', 'Article 254 The proof of commercial contract is not, in principle, submitted to the restrictive rules governing civil contracts. Subject to the exceptions resulting from specific legal provisions, they may be established by all modes of proof which owing to practices or circumstances the judge believes must be admitted.', 'en', 'Commercial Code (Expanded), Article 254', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '255', 'Article 255 In commercial matters, the date of private written (papers) may be established in respect of third parties by all modes of proof. The date of negotiable securities and their endorsement is held true until proof to the contrary.', 'en', 'Commercial Code (Expanded), Article 255', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '256', 'Article 256 The co-debtors of a commercial obligation are presumed to be jointly committed. The same presumption is valid for the sureties of a commercial debt.', 'en', 'Commercial Code (Expanded), Article 256', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '257', 'Article 257 In commercial matters, the legal rate of interest is set at 9 per cent.', 'en', 'Commercial Code (Expanded), Article 257', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '258', 'Article 258 Quotations at the Exchange and the average market prices are evidence of the fair price and the current price, except for a contrary agreement.', 'en', 'Commercial Code (Expanded), Article 258', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '259', 'Article 259 No commercial provision of work or service is presumed given free of charge. When no wage, brokerage or commission has been fixed by the parties concerned, the usual professional remuneration is in order.', 'en', 'Commercial Code (Expanded), Article 259', 'Employment and labor', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '260', 'Article 260 In commercial matters, the judge may not grant grace periods except under very exceptional circumstances. The party which has judicially applied for canceling may no longer exact execution; but the party which has formulated a request for execution may apply for canceling in lieu thereof. Performances after proceedings for canceling have been taken are no longer valid.', 'en', 'Commercial Code (Expanded), Article 260', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '261', 'Article 261 In contracts for successive performances, default in the execution of a performance entitles the party which has honored its obligations to apply for the canceling of all the non executed performances, without prejudice to its title for damages.', 'en', 'Commercial Code (Expanded), Article 261', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '262', 'Article 262 In trading matters, action is lost by time limitation after the lapse of ten years, whenever no shorter term has been set. If in the meantime a sentence of conviction has been pronounced, the time limitation of the action resulting from the adjudicated subject-matter is in all cases of ten years.', 'en', 'Commercial Code (Expanded), Article 262', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '263', 'Article 263 The sale, the loan, the transport contract, the insurance contract and other contracts unregulated by the present code are governed by the code of obligations and by usage. To the transport contract shall additionally apply the special laws relating to public transport enterprises. Exchange dealings, involving either securities or goods, are regulated by those provisions concerning diverse types of contracts from which they borrow the forms or in which they are cancelled, as well as by those special rules of trade exchanges. Contracts relating specifically to sea-borne trade are the subject of special provisions in the merchant shipping law. TITLE II - TRADE PLEDGE', 'en', 'Commercial Code (Expanded), Article 263', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '264', 'Article 264 The trade pledge, subject to the following provisions, is that which stands security for a trade debt.', 'en', 'Commercial Code (Expanded), Article 264', NULL, 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-001-EXPANDED', '265', 'Article 265 The pledge may, subject to the following reserves, be established by every means of proof that the judge shall deem himself bound to accept. The pledge of a registered security is ascertained by conveyance by way of guarantee stated equally on the registers of the issuing establishment and on the security itself. That of the security "To Order" is established by endorsement expressed "as set in pledge" or by equivalent wording. As regards ordinary claims to a named person, their pledge requires in all cases a written deed with certified date and notified to the debtor of the claim under pledge.', 'en', 'Commercial Code (Expanded), Article 265', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '266', 'Article 266 The pledge contract produces no effect, as such, if the object of the pledge remains within the debtor''s possession so that it would appear to Third Parties'' eyes as being part of his free patrimony and as likely to procure fresh credit. It must be remitted to and remain in the creditor''s possession of a Third Party which shall hold it on his behalf. Such conveyance of possession is reputed sufficiently realized by the handing over of the keys of the locked premises which contain the goods or objects under pledge, provided that the premises do not carry the debtor''s signboard, or by the handing over of a representative title as may be required by trading practices.', 'en', 'Commercial Code (Expanded), Article 266', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '267', 'Article 267 The pledge is bound to remit to the debtor who requests it a receipt specifying the nature, the quality, the quantity, the weight, as well as all distinguishing signs of the goods received in pledge.', 'en', 'Commercial Code (Expanded), Article 267', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '268', 'Article 268 If the pledge consists of fungible things or titles, the contract remains, even though such things or titles have been replaced by things or titles of the same kind. If the things or titles are non fungible, the debtor may also, with the creditor''s consent, withdraw and replace them by others, at least if the initial deed of pledge has provided for such right.', 'en', 'Commercial Code (Expanded), Article 268', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '269', 'Article 269 The creditor is bound to exercise on the debtor''s behalf all the rights inherent to the goods or titles received in pledge. If the case concerns a credit title with option rights, the debtor who wishes to avail himself of the option must provide the creditor with the necessary funds, at least two days before the time-limit set by the option.', 'en', 'Commercial Code (Expanded), Article 269', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '270', 'Article 270 When unpaid up titles have been tendered in pledge, the debtor must, if a call for further payments .is made, provide the creditor with funds at least two days before payment is due, failing which the pledgee may proceed with the sale of the titles.', 'en', 'Commercial Code (Expanded), Article 270', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '271', 'Article 271 In the event of default of payment on maturity, the creditor may, eight days after serving summons to the debtor and the Third Party pledge leaser if any, lodge a petition with the Head of the executive office, who shall proceed with the public sale of the objects under pledge. The creditor shall be paid by preferential right out of the proceeds. Any clause of the pledge contract which should authorize the creditor to appropriate the pledge to himself or to dispose of it without the aforementioned formalities, is null. TITLE III - POWER OF PROXY, COMMISSION AND BROKERAGE CHAPTER 1 - Commercial proxy', 'en', 'Commercial Code (Expanded), Article 271', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '272', 'Article 272 Proxy is commercial when it relates to trading operations. It assumes the more specific name of commission and is regulated by the provisions of the next chapter when the authorized agent is to act in his own name or under a company name on behalf of his employer. When the authorized agent is to act in the name of his employer, his rights and obligations are determined in Book VIII of Part II of the Code of Obligations.', 'en', 'Commercial Code (Expanded), Article 272', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '273', 'Article 273 In trade matters, the authorized agent is always entitled, barring contrary stipulations, to a remuneration which in the absence of a conventional arrangement is determined by professional rates, usages or circumstances.', 'en', 'Commercial Code (Expanded), Article 273', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '274', 'Article 274 Proxy for trade, unless it involves general powers, does not authorize non-trading acts except by virtue of an express declaration.', 'en', 'Commercial Code (Expanded), Article 274', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '275', 'Article 275 The authorized agent who has received instructions only for part of the operation is presumed to have elbow room for the surplus.', 'en', 'Commercial Code (Expanded), Article 275', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '276', 'Article 276 The authorized agent is bound to pay the interests on the sums belonging to his employer, as from the day when in compliance with his orders, he should have remitted or consigned such sums.', 'en', 'Commercial Code (Expanded), Article 276', 'Employment and labor', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '277', 'Article 277 When, additionally to the character of a power of proxy, the contract presents the constituent elements of a work contract, as is generally the case for covenants between a merchant and his various agents, canvassing-clerks, travelling agents, Managing Directors, branch or agency Managers, the rules of the work contract on the relations between the merchant and his authorized agent and the rules of the power of proxy in respect of Third Parties, shall apply.', 'en', 'Commercial Code (Expanded), Article 277', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '278', 'Article 278 Depending on the state of subordination or independence resulting from the agreements concluded, trade representatives are to be considered, now as officials in charge, now as more authorized agents. However, they are always entitled, in the event even of a non-abusive termination of the contract, to the observance of the usual term of previous notice, at least if trade representation is their only profession. When a trade representative, authorized agent of several business houses, has premises, a personnel, an organization and overheads which admit of his being considered as a true operator of trade representations, he personally becomes a merchant. CHAPTER 2 - The commission', 'en', 'Commercial Code (Expanded), Article 278', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '279', 'Article 279 A commissioner is he who takes it upon himself to conclude in his own name, but for the account of an employer, sales, purchases, or other trading operations, in return for a title to commission or financial provision. The rules of proxy are applicable on the commission contract, without prejudice to the provisions of the present chapter.', 'en', 'Commercial Code (Expanded), Article 279', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '280', 'Article 280 The commission agent, dealing in his own name,.-.acquires the rights resulting from the contract and is directly committed towards the persons with whom he deals, as if the subject-matter concerned him personally. Third Parties may set against him all the exceptions proceeding from their personal relations with him, as no direct action lies against the employer. Hut in the relations between the employer and the commissioner or the letter''s creditors the rules of proxy shall apply.', 'en', 'Commercial Code (Expanded), Article 280', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '281', 'Article 281 The commissioner is bound to execute the orders received personally, unless usage or agreement authorizes him to use a third party as substitute or that such substitution has been imposed by circumstances. In such cases, the employer may act directly against the person whom the commissioner has taken for substitute.', 'en', 'Commercial Code (Expanded), Article 281', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '282', 'Article 282 The commissioner may not constitute himself counterparty to his employer except with the letter''s consent.', 'en', 'Commercial Code (Expanded), Article 282', 'Employment and labor', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '283', 'Article 283 The commissioner acts at his own risks and perils if, without the employer''s consent, he grants a Third Party credit or a loan of funds.', 'en', 'Commercial Code (Expanded), Article 283', 'Employment and labor', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '284', 'Article 284 Excepting the case when he grants credit without being empowered to, the commissioner is answerable for payment or the execution of other commitments incumbent on those with whom he has dealt, only if he has stood security therefor or if such is the trading practice in the district where he is established. The commissioner who stands security for the person with whom he deals is entitled to a special commission known as del credere, which in the absence of an agreement, is fixed by the practices of the district where the commissioner operates.', 'en', 'Commercial Code (Expanded), Article 284', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '285', 'Article 285 Without prejudice to the provisions of the preceding article, the commission is due by the fact that operation has been concluded, even though the Third Party does not meet the commitments he has assumed, unless non execution is the outcome of a mistake by the commissioner. Commission is equally due if the conclusion of the deal has been prevented by a cause ascribable to the employer. As for those operations which have not been completed for other causes, the commissioner may only claim, for the steps he has taken, such indemnity as would be due according to market practice.', 'en', 'Commercial Code (Expanded), Article 285', 'Employment and labor', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '286', 'Article 286 Barring an agreement to the contrary, the commission is assessed on the gross amount of the operation, including accessory charges.', 'en', 'Commercial Code (Expanded), Article 286', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '287', 'Article 287 The commissioner is entitled to the refund with interest, of all charges, advances and disbursements effected in the interest of the employer. He may also enter into account an indemnity for-warehousing and transport charges, but not for the wages and salaries of his personnel.', 'en', 'Commercial Code (Expanded), Article 287', 'Employment and labor', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '288', 'Article 288 Every commissioner has preferential claim on the value of the goods sent to him, deposited or consigned, by the mere fact of dispatch, deposit or consignation, for ells loans, advances or payments he provides, either before receipt of the goods, or while they are in his possession. Such preferential claim continues to exist only within the framework of the condition laid down by article 266 of the present code. The commissioner''s preferential claim includes, in addition to the principal, the interests, commissions and charges. If the goods have been sold and delivered for the employer''s account, the commissioner gets, out of the proceeds of the sale, the refund of his claim, before the employer''s creditors.', 'en', 'Commercial Code (Expanded), Article 288', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '289', 'Article 289 The employer who revokes the commission or the commissioner who relinquishes it without just motive, incurs damages.', 'en', 'Commercial Code (Expanded), Article 289', 'Employment and labor', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '290', 'Article 290 The forwarding-commissioner who, in consideration of a salary and in his own name, takes charge of the dispatch or re-dispatch of goods for his employer''s account, is likened to a commissioner, but is none the less for it submitted, in as far as the transport of goods is concerned, to the provisions governing the carrier. CHAPTER 3 - Brokerage', 'en', 'Commercial Code (Expanded), Article 290', 'Employment and labor', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '291', 'Article 291 Brokerage is a contract under which one party called broker, is charged in return for a remuneration, either to indicate to the other party the opportunity of concluding an agreement, or to serve him as middleman for the negotiation of a contract. The rules of proxy are, broadly speaking, applicable to brokerage.', 'en', 'Commercial Code (Expanded), Article 291', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '292', 'Article 292 In the absence of official or agreed rates, the broker''s remuneration is determined by usage or adjudicated by the judge according to circumstances. When the agreed salary appears out of proportion-,with the nature of the business and the attendance it entails, it may be reduced by the judge to the fair remuneration of the service rendered.', 'en', 'Commercial Code (Expanded), Article 292', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '293', 'Article 293 The broker is entitled to his remuneration as soon as the indication he has given or the negotiations he has conducted lead to the conclusion of a contract. When the contract has been concluded under suspensive condition, brokerage is due only after the fulfillment of the condition. If it has been agreed that the broker''s expenses would be refused to him, these are due to him even though the business has not materialized.', 'en', 'Commercial Code (Expanded), Article 293', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '294', 'Article 294 The broker forfeits all claims to a remuneration or the refund of his expenses if he acts in the interests of the contracting Third Party, in disregard of his obligations, or if he gets from him promise of a. remuneration in circumstances conflicting with the rules. of good faith.', 'en', 'Commercial Code (Expanded), Article 294', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '295', 'Article 295 The broker may not act as middleman for persons notoriously insolvent or of whose incapacity he is aware.', 'en', 'Commercial Code (Expanded), Article 295', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '296', 'Article 296 He is required to register, with their clauses and specific terms, all the operations concluded through his intermediary, to keep all the documents relating thereto and to deliver a copy certified true to each of the parties who might require it. In sales according to sample, he must keep the sample until the operation has been brought to good termination.', 'en', 'Commercial Code (Expanded), Article 296', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '297', 'Article 297 Brokerage or mediation operations at Stock Exchanges or Commodity Exchanges are submitted, in so far as is needful, to a special legislation. TITLE IV - CURRENT ACCOUNT', 'en', 'Commercial Code (Expanded), Article 297', 'Press and media', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '298', 'Article 298 Current account exists whenever two persons, due to effect mutual remittances of valuables, agree to transform their claims into mere items of debit and credit, forming the elements of a single account so that the final balance of this account, when it is closed, constitutes a single claim due and available for payment.', 'en', 'Commercial Code (Expanded), Article 298', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '299', 'Article 299 The scope of the current account depends on the will of the parties, who may include in it either all their operations, or only those of a determined sort. The current account may be "mutually open" or "unilaterally open". In the latter case, one of the parties is not bound to effect remittances to the other so long as he is provided with sufficient funds, as the account must in no case show a creditor balance in his favor.', 'en', 'Commercial Code (Expanded), Article 299', 'Inheritance and succession', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '300', 'Article 300 The existence of a current account does not exclude the right to a commission or to the refund of charges relating to operations referring thereto. Entry is made in the account, except for a clause to the contrary.', 'en', 'Commercial Code (Expanded), Article 300', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '301', 'Article 301 When a remittance is effected through a trade bill, it is presumed, except for a clause to the contrary, to be actually effected subject to collection. If the bill is not paid on maturity, the recipient is entitled, while retaining it as guarantee and exercising the rights attaching thereto, to debit its amount as liability on the remitter. In the event of the remitter''s insolvency, the recipient may not return the bills received by him except on maturity and when default in payment has been established. When bills have thus been returned, the recipient must diminish his exhibition (of documents) in the remitter''s insolvency as and when payments are effected by the signatories of the bills.', 'en', 'Commercial Code (Expanded), Article 301', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '302', 'Article 302 Remittances are fully entitled to produce interests on behalf of the remitter and chargeable to the recipient, at the rate set by agreement or usage, or failing which, at the legal rate.', 'en', 'Commercial Code (Expanded), Article 302', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '303', 'Article 303 Debts entered in a current account lose their specific character and their individuality proper. They can no longer be the object, as a distinct item, of a payment, a compensation, recourse to proceedings or distraint, nor can they be forfeited by time limitation separately. Personal or real sureties, attaching to debts passed into account, disappear, except for different clauses by the parties.', 'en', 'Commercial Code (Expanded), Article 303', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '304', 'Article 304 Before the closing of a current account neither party shall be considered the other''s debtor or creditor. Only the closure of the account fixes the state of their legal relations, produces as a matter of unstinted right the global compensation of the debit and credit items and determines the creditor and the debtor.', 'en', 'Commercial Code (Expanded), Article 304', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '305', 'Article 305 The account is closed and wound-up on maturities set down by the contract or by local usages and, failing which, at the end of each semester. Claim of the balance constitutes a liquid claim subject to exacting and which, from the day of winding-up, produces interests at the rate fixed by the current account, when the balance is brought forward, or at the legal rate in the contrary case. Actions in redress of an account for error, omissions, duplication or other rectifications must be initiated within six months.', 'en', 'Commercial Code (Expanded), Article 305', 'Assault and battery', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '306', 'Article 306 The contract is terminated at the end of the period set in the agreement and, failing an agreed time-limit, at the will of one of the parties. It equally comes to an end through the death, incapacity or the insolvency of one of them. TITLE V - BANK OPERATIONS', 'en', 'Commercial Code (Expanded), Article 306', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '307', 'Article 307 The bank which receives a sum of money as deposit acquires ownership thereof. It must refund it in one or several installments of equivalent value on the depositor''s first request or within the terms of time-limit or prior notice laid down in the contract. All deposit or refund operations must-be stated in writing. In the absence of agreement to the contrary, interests, if any, are due as from the working day following each deposit and up to the eve of the day of each refund.', 'en', 'Commercial Code (Expanded), Article 307', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '308', 'Article 308 When the bank deposit has for object credit titles, ownership of such titles remains with the depositor, except for proof of intent to the contrary. Such intent is presumed if the depositor has, in writing, unreservedly ceded to the bank the right to dispose of these titles, or recognized to the bank the faculty to hand back titles of the same kind. The rules of proxy apply to those bank deposits in which the bank takes charge of the management of the titles in return for a commission.', 'en', 'Commercial Code (Expanded), Article 308', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '309', 'Article 309 Deposits made in safes or in compartments of safes are governed by the rules of hiring out. The bank answers for the inviolability of the safes let.', 'en', 'Commercial Code (Expanded), Article 309', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '310', 'Article 310 By the contract for the opening of credit, the creditor undertakes to keep at the disposal of the credited party certain sums which the letter may be able to use as a whole or by successive portions, according to his needs, in the course of a set time-limit. Except for a clause to the contrary, the refunds or remittances by the credited during the period of the contract increase by as much (the sums) available for his benefit.', 'en', 'Commercial Code (Expanded), Article 310', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '311', 'Article 311 The contract for the opening of credit may be denounced by the creditor, if the credited becomes ''insolvent or if he was already so unknowingly to the creditor at the time of the contract. In case of a notable reduction of guarantees, real or personal, provided by the credited, the creditor is entitled to obtain supplementary guarantee or, depending on the case, the reduction or closure of the credit.', 'en', 'Commercial Code (Expanded), Article 311', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '312', 'Article 312 When mortgage has been provided by way of surety, the registration taken at the time of the contract guarantees as from its date all advances made subsequently by virtue of the opening of credit.', 'en', 'Commercial Code (Expanded), Article 312', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '313', 'Article 313 When a bank credit has been allocated for payments in favor of Third Parties and that such credit has been confirmed by the bank to the beneficiary, it can no longer be revoked nor modified without his consent. The bank is directly and definitively committed towards him for the acceptance of bills and payments therefor. The bank is entitled to the return of the sums paid and the expenses made in execution of its proxy, to the interests laid down in the agreement or, failing such agreement, to the legal interest dating from the day of payments, as well as to a commission.', 'en', 'Commercial Code (Expanded), Article 313', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '314', 'Article 314 The bank operations which are not referred to in the present title are governed by the provisions of the code of obligations concerning the different contracts to which they give rise or in which they are terminated. BOOK IV TRADE BILLS AND OTHER NEGOTIABLE DOCUMENTS TITLE I - THE BILL OF EXCHANGE CHAPTER 1 - Creation and form of the bill of exchange', 'en', 'Commercial Code (Expanded), Article 314', 'Contracts and obligations', 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-001-EXPANDED', '315', 'Article 315 The Bill of Exchange contains 1 - The denomination ''Bill of Exchange'' inserted in the text of the document and expressed in the language used in the wording of this document; 2 - The order pure and simple to pay a determined sum; 3 - The name of he who must pay (drawee); 4 - Specification of maturity; 5 - Specification of the place where payment is to be effected; 6 - The name of he to whom or to. whose order payment is to be made; 7 - Indication of the date and place where the Bill was created; 8 - The signature of he who issues the Bill (drawee).', 'en', 'Commercial Code (Expanded), Article 315', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '316', 'Article 316 The document in which one of the enunciations indicated in the preceding article is missing is not valid as Bill of Exchange, except in the cases described in the following sub-paragraphs The Bill of Exchange the maturity of which is not indicated is considered as payable at sight. Except for a special indication, the place stated beside the name of the drawee is reputed to be the place of payment and, at the same time, the drawee''s place of domicile. The Bill of Exchange wherein the place of its creation is not mentioned is considered as subscribed in the place designated beside the name of the drawer.', 'en', 'Commercial Code (Expanded), Article 316', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '317', 'Article 317 The Bill of Exchange may be to the order of the drawer himself. It may be drawn on the drawer himself. It may be drawn for the account of a third party. It may be payable at the domicile of a third party, either in the locality where the drawee has his domicile, or in another locality.', 'en', 'Commercial Code (Expanded), Article 317', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '318', 'Article 318 In a Bill of Exchange payable at sight or within a certain time after sight, the drawer may stipulate that the sum shall produce interests. In all other Bills of Exchange such stipulation is reputed unwritten The rate of interest must be stipulated in the Bill, failing such indication the clause is reputed unwritten. Interests are computed from the date of the Bill of Exchange if no other date is indicated.', 'en', 'Commercial Code (Expanded), Article 318', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '319', 'Article 319 The Bill of Exchange the amount of which is set dawn both in full letters and figures is worth, in the event of discrepancy, the sum set down in full letters. The Bill of Exchange the amount of which is written several times, either in full letters, or in figures, is worth, in case of discrepancy, only the smaller sum.', 'en', 'Commercial Code (Expanded), Article 319', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '320', 'Article 320 If the Bill of Exchange bears signature of persons unqualified to commit themselves by Bill of Exchange, forged signatures, or signatures of fictitious persons, or signatures which, for any other reason, could not bind the persons who have signed the Hill of Exchange, or in whose names it was signed, the other signatories'' obligations are none the less valid.', 'en', 'Commercial Code (Expanded), Article 320', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '321', 'Article 321 Whoever affixes his signature to a Bill of Exchange as representative of a person on whose behalf he was not entitled to act is himself held by virtue of the Bill and, if he has paid, has the same rights as the alleged represented party. The same applies in the event of a representative who has overstepped his powers.', 'en', 'Commercial Code (Expanded), Article 321', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '322', 'Article 322 The drawer is guarantor of acceptance and payment. He may exonerate himself of the guarantee of acceptance; any clause by which he exonerates himself of the guarantee of payment is reputed unwritten. CHAPTER 2 - Provision of funds', 'en', 'Commercial Code (Expanded), Article 322', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '323', 'Article 323 Provision must be made by the drawer or by him for whose account the Bill of Exchange shall be drawn; the drawer for a third party''s account does not cease to be personally held towards endorsers and the bearer only. Provision exists if, on maturity of the 8i11 of Exchange, he on whom it is furnished is indebted to the drawer, or to whom for whose account it is drawn, for a sum at least equal to the amount of the Bill of Exchange. Ownership of the provision is transferable as a matter of right to the successive bearers of the Bill of Exchange.', 'en', 'Commercial Code (Expanded), Article 323', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '324', 'Article 324 Acceptance supposes provision. It establishes proof thereof towards the endorsers. Whether there is acceptance or not, only the drawer is bound to prove, in case of denial, that those on whom the letter was drawn had provision on maturity, if not he is held for the guarantee although protest has been made after the set time-limits. CHAPTER 3 - Endorsement', 'en', 'Commercial Code (Expanded), Article 324', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '325', 'Article 325 Every Bill of Exchange, even non expressly drawn to order, is transferable by means of endorsement. When the drawer has inserted in the Bill of Exchange the words "not to order" or an equivalent phrase, the title is transferable only in the form and with the effects of an ordinary assignment. Endorsement may be effected even for the benefit of the drawee, whether acceptor or not, of the drawer or any other obligee. These persons may endorse the Hill afresh.', 'en', 'Commercial Code (Expanded), Article 325', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '326', 'Article 326 Endorsement must be pure and simple. Any condition to which it is subordinated is reputed unwritten. Partial endorsement is null. Endorsement to bearer tantamounts to blank endorsement.', 'en', 'Commercial Code (Expanded), Article 326', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '327', 'Article 327 Endorsement must be written down on the Bill of Exchange or an attached sheet (allonge). It must be signed by the endorser. Endorsement may designate no beneficiary or consist merely of the signature of the endorser (blank endorsement). In the latter case, endorsement, to be valid, must be written on the back of the Bill of Exchange or on the allonge.', 'en', 'Commercial Code (Expanded), Article 327', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '328', 'Article 328 Endorsement conveys all rights resulting from the Hill of Exchange. If endorsement is blank, the bearer may 1 - Fill the blank, either with his name, or with the name of a third person; 2 - Endorse the Hill afresh in blank or to another person; 3 - Remit the Bill to a third party, without filling the blank and without endorsing.', 'en', 'Commercial Code (Expanded), Article 328', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '329', 'Article 329 Barring a clause to the contrary, the endorser is guarantor of acceptance and payment. He may forbid a new endorsement; in which event he is not held for guarantee towards those persons for whom the Hill is subsequently endorsed.', 'en', 'Commercial Code (Expanded), Article 329', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '330', 'Article 330 Bills of Exchange drawn at deferred sight are to be presented for acceptance within a year from their date. The drawer may shorten this time or stipulate a longer one. These time-limits may be shortened by the endorsers.', 'en', 'Commercial Code (Expanded), Article 330', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '331', 'Article 331 Persons sued by virtue of the Bill of Exchange may not set as bar to the bearer the exceptions founded on their personal relations with the drawer or with the previous bearers, unless the bearer, by acquiring the Bill, has knowingly acted to the debtor''s prejudice.', 'en', 'Commercial Code (Expanded), Article 331', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '332', 'Article 332 When the endorsement bears the words "value for recovery", "for collection", "by proxy", or any other mention implying a proxy, the bearer may exercise all the rights deriving from the Bill of Exchange but he may not endorse the latter except by way of power of proxy. Obligees may, in this case, put forward as a bar against the bearer only those exceptions which would be opposable to the endorser. The order implied by an endorsement for proxy is not terminated by the death of the Principal or the occurrence of his incapacity.', 'en', 'Commercial Code (Expanded), Article 332', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '333', 'Article 333 When the endorsement contains the words "value in guarantee", "value in pledge", or any other phrase implying collateral security, the bearer may exercise all his rights deriving from the Bill of Exchange, but an endorsement made by him is valid only as endorsement by way of procuration. Obligees may not put forward against the bearer exceptions founded on their personal relations with the endorser, unless the endorser has knowingly acted to the debtor''s prejudice, on receiving the Bill.', 'en', 'Commercial Code (Expanded), Article 333', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '334', 'Article 334 Endorsement subsequent to maturity produces the same effects as a prior endorsement. However, endorsement subsequent to protest for default in payment, or lodged after the time-limit set for protest produces no effects beyond those of ordinary conveyance. Except for proof to the contrary, undated endorsement is supposed to have been made before the expiry of the time-limit for making a protest.', 'en', 'Commercial Code (Expanded), Article 334', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '335', 'Article 335 It is forbidden to antedate orders under penalty of forgery. CHAPTER 4 - Accept ance', 'en', 'Commercial Code (Expanded), Article 335', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '336', 'Article 336 Until maturity, the Bill of Exchange may be-presented for the acceptance of the drawee, in the place of his domicile, by the bearer or even by a mere holder.', 'en', 'Commercial Code (Expanded), Article 336', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '337', 'Article 337 In any Bill of Exchange, the drawer may stipulate that it shall have to be presented for acceptance, with or without setting a time-limit. In the Bill he may forbid presentation for acceptance unless it is payable at a third party''s or payable in a locality other than that of the drawee''s domicile, or drawn at deferred sight. He may also state that presentation or acceptance may not take place before a set time. Any endorser may stipulate that the Bill shall have to be presented far acceptance, either stating a time-limit or not unless it is declared unaccepted by the drawer.', 'en', 'Commercial Code (Expanded), Article 337', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '339', 'Article 339 The drawee may request that a second presentation be made to him .the day following the first. Interested parties are not allowed to claim that their request has not been acceded to except if it is mentioned in the protest. The bearer is not obliged to leave into the hands of the drawee the Hill presented for acceptance.', 'en', 'Commercial Code (Expanded), Article 339', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '340', 'Article 340 Acceptance is written on the Bill of Exchange. It is expressed by the word "accepted" or by any other equivalent word; it is signed by the drawee. The drawee''s simple signature affixed on the back of the Bill tantamounts to acceptance. When the Bill is payable at deferred sight or when it must be presented for acceptance within a determined time-limit by virtue of a special stipulation, acceptance must be dated at the day of presentation. In the absence of date, the bearer, in order to safeguard his claim against endorsers and the drawer, has this omission established by a protest made in good time.', 'en', 'Commercial Code (Expanded), Article 340', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '341', 'Article 341 Acceptance is pure and simple, but the drawee may restrict it to part of the sum. Any other modification brought about by acceptance to the terms of the Bill of Exchange tantamounts to a refusal of acceptance. However, the acceptor is held within the terms of his acceptance.', 'en', 'Commercial Code (Expanded), Article 341', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '342', 'Article 342 When the drawer has indicated in the Bill of Exchange a place of payment other than that of the drawee''s domicile, without designating a Third Party at whose place payment is to be effected, the drawee may indicate it at the time of acceptance. Failing this indication, the acceptor is reputed to be self-bound to pay himself at the place of payment. If the Bill is payable at the drawee''s domicile, the latter may indicate in the acceptance an address of the same place where payment is to be effected.', 'en', 'Commercial Code (Expanded), Article 342', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '343', 'Article 343 By acceptance the drawee binds himself to pay the Bill of Exchange on maturity, . In default of payment, the bearer, even though he is the drawer, has against the acceptor direct action resulting from the Hill of Exchange involving all - that can be claimed by virtue of articles 370 and 371.', 'en', 'Commercial Code (Expanded), Article 343', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '344', 'Article 344 If the drawee who has vested the Bill of Exchange with his acceptance had struck off acceptance before returning the Bill, acceptance is presumed denied: Hut for proof to the contrary, striking off is reputed having been made before the return of the title. However, if the drawee has made his acceptance known by writing to the bearer or any signatory, he is held towards the latter within the terms of his acceptance. CHAPTER 5 - Guarantee', 'en', 'Commercial Code (Expanded), Article 344', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '345', 'Article 345 The payment of a Bill of Exchange may be covered for the whole amount or part of it by backing. Such cover is furnished by a Third Party or even by the signatory of the Bill.', 'en', 'Commercial Code (Expanded), Article 345', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '346', 'Article 346 Backing is given either on the Bill of Exchange or on an allonge, or by a separate deed indicating the place where it occurred. It is expressed by the words "Good for Backing" or any other equivalent formula; it is signed by the Backer. It is considered as resulting from the simple signature of the Hacker affixed on the back of the Bill of Exchange, except in the case of the drawee''s or drawer''s signature. Backing must indicate for whose account it is given. Failing this indication, it is reputed given for the drawer.', 'en', 'Commercial Code (Expanded), Article 346', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '347', 'Article 347 The Backer is held in like manner as he whom he guarantees. His commitment is valid, even though the obligation he has guaranteed should be null for any cause other than legal flaw. When he pays the Dill of Exchange, the guarantor acquires the claims resulting from the Bill of Exchange against the person he guarantees and against those who are held towards the latter by virtue of the Hill of Exchange. CHAPTER 6 - Maturity', 'en', 'Commercial Code (Expanded), Article 347', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '348', 'Article 348 A Bill of Exchange may be drawn - at sight - at deferred sight - at deferred date - at a fixed date. At other maturities or at successive maturities, Bills of Exchange are null.', 'en', 'Commercial Code (Expanded), Article 348', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '349', 'Article 349 The Hill of Exchange at sight is payable on presentation. It must be presented for payment within a year from its date. The drawer may shorten this delay or stipulate a longer one. Such delays may be shortened by the endorsers. The drawer may prescribe that a Dill of Exchange payable at sight is not to be presented for payment before an indicated term. In this event, the time of presentation commences from that term.', 'en', 'Commercial Code (Expanded), Article 349', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '350', 'Article 350 The maturity of a Bill of Exchange at deferred sight is determined, either by the date of acceptance, or by that of protest. In the absence of protest, undated acceptance is reputed in respect of the acceptor to have been given the last day of the stated time-limit for the presentation of acceptance.', 'en', 'Commercial Code (Expanded), Article 350', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '351', 'Article 351 The maturity of a Bill of Exchange drawn at one or several months from the date or sight falls due on the date of the corresponding month when payment is to be effected. In default of a corresponding date, maturity occurs on the last day of that month. When a Bill of Exchange is drawn at one or several months of date or sight, the entire months are first to be computed. If maturity is set at the beginning, the middle (mid-January, mid-February, etc..) or the end of the month, these terms are taken to mean the first, the fifteenth or the last day of the month. The phrases "eight days" or "fifteen days" are taken to mean not just one or two weeks, but a period of actual eight or fifteen days. The phrase "half a month" indicates a period of fifteen days.', 'en', 'Commercial Code (Expanded), Article 351', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '352', 'Article 352 When the Bill of Exchange is payable on a fixed day in a district where the calendar is different from that of the place of issue, the date of maturity is considered as set in accordance with the calendar of the place of payment. When a Bill of Exchange drawn between two places with different calendars is payable at a certain time from date, the date of issue is brought back to the corresponding day of the calendar of the place of payment and maturity is set in consequence. The terms of presentation of the Bill of Exchange are calculated in conformity with the rules of the preceding sub-paragraph. These rules are not applicable, if one clause of the Bill of Exchange, or even the simple statements of the instrument, indicate that it was intended to adopt different rules. CHAPTER 7 - Payment', 'en', 'Commercial Code (Expanded), Article 352', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '353', 'Article 353 The bearer of a Bill of Exchange payable on a set day or within a certain time-lag from the date or sight must present the Bill of Exchange for payment, on the day of maturity. The presentation of a Hill of Exchange to a Clearing House tantamounts to presentation for payment.', 'en', 'Commercial Code (Expanded), Article 353', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '354', 'Article 354 The drawee may demand, on paying the Bill of Exchange, that it should be remitted to him "duly settled" by the bearer. The bearer may not refuse partial payment. In the event of partial payment, the drawee may demand that mention of that payment be made on the Bill and that he should be given a receipt therefor. Payments made on account against the amount of the Dill of Exchange are a relief to drawers and endorsers. The bearer is bound to protest the Bill of Exchange for the surplus.', 'en', 'Commercial Code (Expanded), Article 354', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '355', 'Article 355 The bearer of a Bill of Exchange may not be constrained to receive payment therefor before maturity. The drawee who pays before maturity does so at his own risks and perils. He who pays on maturity is validly cleared unless a grievous mistake or fraud lies on his side. He is obliged to verify that the successive endorsements are in order but not so the signatures of the endorsers.', 'en', 'Commercial Code (Expanded), Article 355', 'Fraud', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '356', 'Article 356 When a Bill of Exchange is stipulated payable in a money which is not legal tender at the place of payment, the amount may be paid up in the money of the country according to its value on the day of maturity. If the debtor is late, the bearer may, according to his choice, require that the amount of the Bill of Exchange be paid in the money of the country as per rate, either of the day of maturity, or of the day of payment. Usages of the place of payment serve to determine the value of the foreign currency. However, the drawer may stipulate that the sum to be paid shall be calculated according to a rate set down in the Hill. The rules here enunciated do not apply to the case where the drawer has stipulated that payment shall have to be effected in a certain stated currency (clause of actual payment in a foreign currency). If the amount of the Dill of Exchange is indicated in a currency having the same denomination, but a different value in the country of issue and in that of payment, one is presumed to have referred to the currency of the place of payment.', 'en', 'Commercial Code (Expanded), Article 356', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '357', 'Article 357 If the Bill of Exchange has not been presented for payment on the day of maturity, every debtor is entitled to lodge the amount therefor as deposit in the bank authorized to receive State deposits, at the bearer''s charges, risks and perils. The debtor shall be required only to remit the deed of deposit in exchange for the draft.', 'en', 'Commercial Code (Expanded), Article 357', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '358', 'Article 358 No bar may be set against payment except in the event of deposit in exchange for the draft.', 'en', 'Commercial Code (Expanded), Article 358', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '359', 'Article 359 In the case of loss of an unaccepted Bill of Exchange, he to whom it belongs may proceed for payment on a second, third, fourth one, etc..', 'en', 'Commercial Code (Expanded), Article 359', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '360', 'Article 360 If the lost Bill of Exchange is vested with acceptance, payment may not be exacted on a second, third or fourth one etc.. except by order of the judge and following the payment of a security deposit..,', 'en', 'Commercial Code (Expanded), Article 360', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '361', 'Article 361 If he who has lost a Bill of Exchange, whether accepted or not, cannot represent a second, third, fourth one etc.., he may request payment of the lost Bill of Exchange and obtain it through the judge''s order after justifying his ownership on his books and by giving security.', 'en', 'Commercial Code (Expanded), Article 361', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '362', 'Article 362 In the event of refusal to pay following application put forward by virtue of the two preceding paragraphs, the owner of the lost Bill of Exchange retains all his rights by deed of protestation. This deed must be made out the day following the maturity of the lost Bill of Exchange; such notices as are prescribed by article 367 must be served within the time-limits set in this article.', 'en', 'Commercial Code (Expanded), Article 362', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '363', 'Article 363 The owner of a stray Bill of Exchange must, in order to procure himself a second one, apply to his immediate endorser who is bound to lend him his name and his attendance to act against his own endorser, and thus by going back from endorser up to the drawer of the Bill. The owner of the stray Bill of Exchange shall bear the charges.', 'en', 'Commercial Code (Expanded), Article 363', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '364', 'Article 364 The commitment deriving from the security referred to in articles 360 and 361 expires after three years, if in the meantime neither petitions nor legal proceedings have intervened. CHAPTER 8 - Remedies for default in acceptance, default in payment, protests, replacement Section 1 - Remedies for default in acceptance, default in payment', 'en', 'Commercial Code (Expanded), Article 364', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '365', 'Article 365 The bearer may have remedies at law against the endorsers, the drawer arid the obligees. On maturity, if payment does not take place. Even before maturity: 1- In case of refusal, total or partial, of acceptance. 2- In the event of the failure of the drawee, acceptor or not, suspension of his payments, even not established by a Court ruling, or the unfruitful distraint of his goods. 3- In the event of the failure of the drawer of an unacceptable Bill. However the guarantors against whom legal remedy is exercised in the two cases referred to in the preceding last two sub-paragraphs, 2 and 3, may within three days of such resort file with the president of the commerce tribunal of their domicile a petition soliciting extension of the time-limit. If the petition is acknowledged founded, the ordinance shall fix a new period in which the guarantors shall be compelled to pay the trade Bills in question, but the time extensions thus granted should not exceed the date set for maturity. The ordinance shall subject to neither opposition nor appeal.', 'en', 'Commercial Code (Expanded), Article 365', NULL, 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-001-EXPANDED', '366', 'Article 366 Refusal of acceptance or payment must be established by an authentic deed (protest for default in acceptance or default in payment). Protest for default in acceptance must be made within the time-limit set for presentation for acceptance. If, in the case referred to in article 339, 1st sub-paragraph, the first presentation occurred on the last day of the time limit, protest may still be made the next day. Protest for default in payment of a Bill of Exchange payable on a fixed day or within a certain time of date or sight must be made in one of the two working days which follow the day when the Bill of Exchange is payable. If the Hill is payable at sight, protest must be made according to the terms indicated in the preceding sub-paragraph concerning protest for default in acceptance. Protest for default in acceptance exempts from presentation for payment and from protest for default in payment. In the event of the suspension of payment by the drawee, acceptor or not, or in the event of distraint of his goods remaining fruitless, the bearer may not seek remedy at law except after presentation of the drawee''s Bill for payment and after protest has been made. In case of the declared insolvency of the drawee, acceptor or not, as well as in case of the declared failure of the drawer of an unaccepted Bill, production of the judge''s adjudication of insolvency suffices to enable the bearer to seek remedy.', 'en', 'Commercial Code (Expanded), Article 366', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '367', 'Article 367 The bearer must give notice of default in acceptance or payment to his endorser and the drawer within the four working days following the day of protest or that of the presentation, in case there exists a clause of return without charges. Every endorser must, within the two working days following the day of receipt of the notice, acquaint his endorser with the notice he has received, indicating the names and addresses of those who have served the preceding notices, and so on, moving backwards up to the drawer. The time-limit indicated above runs from the receipt of the preceding notice. When in compliance with the preceding sub-paragraph, notice has been served to a signatory of a Bill of Exchange, the same notice must be served within the same time-limit to his guarantor. Should an endorser fail to indicate his address, or should he indicate it in an illegible manner, it suffices that the notice is served to the endorser preceding him. Anyone who has a notice to serve may do so in any form, even by the simple return of the Bill of Exchange. He has to prove that he served notice within the given time-limit. Such time limit shall be considered as observed if a letter including the notice has been posted within the said time-limit. He who fails to serve notice within the time-limit indicated above incurs no forfeiture; he is liable, should the case arise, for the prejudice caused by his negligence, but damages must not exceed the amount of the Bill of Exchange.', 'en', 'Commercial Code (Expanded), Article 367', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '368', 'Article 368 The drawer, an endorser or a Backer may, by the phrase "return uncharged", "without protest" or any equivalent phrase, written on the instrument and signed, exempt the bearer from making, in his search for remedy, a protest for default in acceptance or default in payment. This phrase does not exempt the bearer from the presentation of the Bill of Exchange within the time limit prescribed nor from the notices to serve.. Onus of the proof that the time-limits have not been observed rests with him who avails himself of it against the bearer. If the phrase is written by the drawer, it produces its effects in respect of all the signatories; if it is written by an endorser or a Backer, it produces its effects only in respect of him. If despite the phrase written by the drawer, the bearer has a protest made, expenses are chargeable on him. When the phrase emanates from an endorser or a Backer, charges for the protest, if any is made, may be recovered against all the signatories.', 'en', 'Commercial Code (Expanded), Article 368', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '369', 'Article 369 A11 those who have drawn, accepted, endorsed or backed a Bill of Exchange are held jointly towards the bearer. The bearer is entitled to act against all these persons, individually or collectively, without being constrained to observe the order in which they have obliged themselves. The same right belongs to any signatory of a $i11 of Exchange who has refunded it. Action brought against one of the obligees is no bar to action against the others, even subsequent to the one who has first been prosecuted.', 'en', 'Commercial Code (Expanded), Article 369', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '370', 'Article 370 The bearer may claim from the person against whom he seeks remedy at law 1- The amount of the unaccepted or unpaid Bill of Exchange, together with interests if these are stipulated; 2- Interests at the legal rate as from maturity; 3- Charges for protest, the notices served as well as other expenses. If remedy is sought before maturity, deduction shall be made of a discount on the amount of the Bill. This discount shall be calculated according to the official discount rate (the bank rate agreed for the reception of State deposits) such as it exists at the date of remedy in the district of the bearer''s domicile.', 'en', 'Commercial Code (Expanded), Article 370', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '371', 'Article 371 He who has refunded the Bill of Exchange may claim from its guarantors: 1 - The total sum he has paid; 2 - The interests of the said sum calculated at the legal rate as from the day he refunded it; 3 - The expenses he has incurred.', 'en', 'Commercial Code (Expanded), Article 371', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '372', 'Article 372 Every obligee against whom remedy is sought or who is exposed to such remedy may demand, as counterpart for the refund, the deposit of the Bill of Exchange with the protest in a settled account.. Any endorser who has refunded the Bill of Exchange may strike off his endorsement and those of the subsequent endorsers.', 'en', 'Commercial Code (Expanded), Article 372', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '373', 'Article 373 In case of resort to remedy after partial acceptance, he who refunds the sum for which the Hill has not been accepted, may require that the refund be mentioned on the Bill and that discharge therefor is given him. The bearer must, on the other hand, remit him a copy certified true to the Bill and the protest to allow subsequent recourses to remedy.', 'en', 'Commercial Code (Expanded), Article 373', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '374', 'Article 374 After expiry of the time-limits set: - for the presentation of a Bill of Exchange at sight or at deferred sight, - for the making of protest for default on acceptance or default in payment, - for presentation to payment in case of a clause of return without charges, the bearer is forfeited of his claim against the endorsers, against the drawer and against the other obligees, with the exception of the acceptor. However forfeiture does not occur in relation to the drawer except if he proves that provision was available at maturity. In this case no action lies with the bearer except against him on whom the Bill of Exchange was drawn.', 'en', 'Commercial Code (Expanded), Article 374', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '375', 'Article 375 In the event of non presentation for acceptance within the time-limit set by the drawer, the bearer forfeits, within the limits set by the preceding article, his title to seek remedy, for default in payment as much as for default in acceptance, unless it appears from the terms of the stipulation that the drawer intended to exonerate himself only from the guarantee of acceptance. If the stipulation of a time-limit for presentation is contained in an endorsement, only the endorser may avail himself of it.', 'en', 'Commercial Code (Expanded), Article 375', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '376', 'Article 376 When the presentation of a Bill of Exchange or the making of a protest within the prescribed time-limits is prevented by an insuperable obstacle (legal prescription of some State or any other cause of force majeure), such time-limits are extended. The bearer is bound to give notice, without delay, of the case of force majeure to his endorser and to mention this notice duly dated and signed by him on the Bill of Exchange or on an allonge; for the surplus, the provisions of article 402 are applicable. After the termination of force majeure, the bearer must, without delay, present the Bill for acceptance or for payment and, if the case so requires it, have the protest made. If force majeure persists beyond thirty days from maturity, remedy may be sought, neither presentation nor the making of a protest being necessary. For Hills of Exchange at sight or at deferred sight the time-limit of 30 days is computed from the date at which the bearer has, even before the expiry of the time-limits for presentation, served notice of the force majeure to his endorser; for Bills of Exchange at deferred sight, the time-limit of 30 days is augmented by the sight time-limit indicated on the Bill of Exchange. Are not considered as constituting cases of force majeure facts purely personal to the bearer or to him whom he charged to present the Hill or make the protest. Section 2 - Protests', 'en', 'Commercial Code (Expanded), Article 376', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '377', 'Article 377 Protests for default in acceptance or default in payment are made by the Notary or one of his clerks. Protest must be made At the domicile of he on whom the Bill of Exchange was payable or at his last known domicile; at the domicile of persons designated by the Bill of Exchange for its payment if need be; at the domicile of the Third Party who has accepted through intervention; all by a single and same deed. Notification shall be made in conformity with articles 353 and subsequent ones of the code of civil procedure.', 'en', 'Commercial Code (Expanded), Article 377', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '378', 'Article 378 The deed of protest contains the literal reproduction of the Bill of Exchange, of acceptance, of endorsements and of the recommendations stated therein, and the summons to pay the amount of the Bill of Exchange. The deed also states the presence or absence of he who must pay, the motives of refusal to pay and the inability or refusal to pay.', 'en', 'Commercial Code (Expanded), Article 378', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '379', 'Article 379 No deed on the part of the bearer of the Bill of Exchange can be a substitute to the deed of protest, except for the case referred to in articles 360 and subsequent ones regarding the loss of the Bill of Exchange.', 'en', 'Commercial Code (Expanded), Article 379', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '380', 'Article 380 Notaries are bound, under penalty of damages to the parties, to leave exact copy of protests and to reproduce them in full, day by day and by order of dates, in a special register. Section 3 - Replacement', 'en', 'Commercial Code (Expanded), Article 380', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '381', 'Article 381 Any person entitled to seek remedy at law may, except for a clause to the contrary, get paid by means of a new Bill (replacement) drawn at sight on one of the guarantors and payable at the latter''s domicile. The replacement Bill comprises, in addition to the sums stated in articles 370 and 371, brokerage and a stamp duty. If the replacement Bill is drawn by the bearer, the amount thereof is fixed according to the rate of the Bill of Exchange at sight, drawn from the district where the original Bill was payable on the district of the guarantor''s domicile. If the replacement Bill is drawn by an endorser, its amount is fixed according to the rate of a Bill at sight drawn from the district where the drawer of the second Bill is domiciled on the district of the guarantor''s domicile.', 'en', 'Commercial Code (Expanded), Article 381', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '382', 'Article 382 Replacement Bills may not be cumulated. Each endorser bears but one, as well as the drawer. CHAPTER 9 - Intervention Section 1 - General Provisions', 'en', 'Commercial Code (Expanded), Article 382', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '383', 'Article 383 The drawer, an endorser or a guarantor may designate a person to accept or pay, if need be. The Bill of Exchange may be, subject to the conditions determined hereinafter, accepted or paid by a person intervening for any debtor open to proceedings. The intervener may be a third party, even the drawee, or a person already obliged by virtue of the Bill of Exchange, except the acceptor. The intervener is bound to serve, within two working days, notice of his intervention to him on whose behalf he has intervened. If this time-limit is not observed, he is liable, should the case arise, for the prejudice caused by his negligence but damages are not to exceed the amount of the Bill of Exchange. Section 2 - Acceptance through Intervention', 'en', 'Commercial Code (Expanded), Article 383', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '384', 'Article 384 Acceptance through intervention may take place whenever resorts to remedy are open, before maturity, to the bearer of an acceptable Bill of Exchange. When on the Bill of Exchange a person has been designated to accept or pay, if need be, at the place of payment, the bearer may not set into action before maturity his title to remedy against he who has stated this indication and against subsequent signatories unless he has presented the Bill of Exchange to the designated person and that, the latter having declined acceptance, this denial has been established in the protest. In other cases of intervention the bearer may refuse acceptance by intervention. However, if he admits it, he forfeits the resorts open to him before maturity against the one for whom acceptance has been given and against subsequent signatories.', 'en', 'Commercial Code (Expanded), Article 384', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '385', 'Article 385 Acceptance by intervention is stated in the Bill of Exchange; it is signed by the intervener. It indicates for whose account it has occurred; in the absence of such indication, acceptance is reputed given by the drawer.', 'en', 'Commercial Code (Expanded), Article 385', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '386', 'Article 386 The acceptor through intervention is obliged towards the bearer and towards the endorsers subsequent to the one for whose account he has intervened, in the same manner as the latter. In spite of acceptance through intervention, be for whom it has been made and his guarantors may require the bearer, as counterpart for the payment of the sum indicated in article 370, to remit the Bill of Exchange, the protest and the settled account, if need be. Section 3 - Payment through intervention', 'en', 'Commercial Code (Expanded), Article 386', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '387', 'Article 387 Payment through intervention may be effected in all cases either at maturity, or before maturity; avenues for remedy are open to the bearer. Payment comprises all the sums that would have to settle the person for whom it takes place. It has to be done, at the latest, the day following the last day admitted for the making of protest for default in payment.', 'en', 'Commercial Code (Expanded), Article 387', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '388', 'Article 388 If the Bill of Exchange has been accepted by interveners having their domicile in the place of payment or if persons with their domicile in this same place have been designated to pay if need be, the bearer must present the Hill to all these persons and make, if necessary, a protest for default in payment, at the latest the next day of the last day open for protest making. In the event of failure of protest making within this time-limit, the person who has indicated the need or for whose account the Bill has been accepted and the subsequent endorsers are no longer obliged.', 'en', 'Commercial Code (Expanded), Article 388', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '389', 'Article 389 The bearer who refuses payment through intervention forfeits his recourses against those who might have been released.', 'en', 'Commercial Code (Expanded), Article 389', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '390', 'Article 390 Payment through intervention must be established by a clearance given on the Bill of Exchange, with indication of the person for whom it is effected. In the absence of such indication, payment is considered as made for the drawer. The Bill of Exchange and the protest, if one has been made, must be remitted to the payer through intervention.', 'en', 'Commercial Code (Expanded), Article 390', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '391', 'Article 391 The payer through intervention acquires the rights resulting from the Bill of Exchange against the person for whom he has paid and against all those who are held towards the latter by virtue of the Bill of Exchange. However, he may not endorse the Dill of Exchange afresh. Endorsers subsequent to the signatory for whom payment has been effected are released. In case of concurrence for payment through intervention, he who operates the most releases is preferred. He who intervenes, knowingly, contrary to this rule, forfeits his recourses against those who would have been released. CHAPTER 10 - Plurality of exemplars and copies Section 1 - Plurality of exemplars', 'en', 'Commercial Code (Expanded), Article 391', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '392', 'Article 392 The Bill of Exchange may be drawn in several identical exemplars. These exemplars must be numbered in the very wording of the title failing which each of them is considered as a distinct Bill of Exchange. Every bearer of a Bill which does not indicate that it has been drawn in a single exemplar may demand the delivery of several exemplars on his account. To this end, he is to apply to his immediate endorser who is bound to lend him his assistance to act, against his own endorser and so on, by going back to the drawer. Endorsers are bound to reproduce the endorsements on the new exemplars.', 'en', 'Commercial Code (Expanded), Article 392', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '393', 'Article 393 The payment made on one of the exemplars amounts to clearance, even though it is not stipulated that such payment nullifies the effect of the other exemplars. However, the drawee remains held by virtue of each accepted exemplar which he has failed to recover. The endorser who has transferred the exemplars to different persons, as well as subsequent endorsers are held by virtue of all the exemplars bearing their signature and which have not been returned.', 'en', 'Commercial Code (Expanded), Article 393', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '394', 'Article 394 He who has sent one exemplar for acceptance must indicate on the other exemplars the name of the person in whose hand this exemplar stands. The latter is bound to remit it to the legitimate bearer of another exemplar. If he refuses to do so, the bearer may not exercise recourse except after he has established by protest 1 - that the sent exemplar has not been returned on his request; 2 - that acceptance or payment has not been obtained on another exemplar. Section 2 - Copies', 'en', 'Commercial Code (Expanded), Article 394', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '395', 'Article 395 Every bearer of a Bill of Exchange is entitled to have copies made therefrom. The copy must reproduce exactly the original with the endorsements and all the other mentions made in it. It must indicate where it stops. It must be endorsed and guaranteed in the same manner and with the same effects as the original.', 'en', 'Commercial Code (Expanded), Article 395', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '396', 'Article 396 The copy must indicate the holder of the original instrument. The latter is required to remit the said instrument to the legitimate bearer of the copy. If he refuses to do so, the bearer may not initiate his recourse against all the persons who have endorsed or guaranteed the copy except after he has established by a protest that the original has not been remitted to him upon his request. If the original instrument, after the last endorsement occurring before the copy was made out, carries the phrase : "hence endorsement is valid only on the copy" or any equivalent wording, an endorsement subsequently signed on the original is null. CHAPTER 11 - Changes', 'en', 'Commercial Code (Expanded), Article 396', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '397', 'Article 397 In case of changes in the text of a Bill of Exchange, signatories subsequent to this change are held within the terms of the changed text; prior signatories are held within the terms of the original text. CHAPTER 12 - Prescription', 'en', 'Commercial Code (Expanded), Article 397', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '398', 'Article 398 A11 actions resulting from a Bill of Exchange against the acceptor are limited to three years computed from the date of maturity. The bearer''s actions against endorsers and against the drawers are limited to one year dating from the protest in due time or from maturity in the event of a clause of return without charges. The actions of endorsers the ones against the others and against the drawer are limited to six months dating from the day when the endorser has repaid the Bill or from the day when he himself was prosecuted.', 'en', 'Commercial Code (Expanded), Article 398', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '399', 'Article 399 Prescriptions in the case of actions in Court run from the day of the last legal proceedings. They do not apply in case of conviction or if the debt has been acknowledged by separate deed. Interruption of prescription has effect only against the person on whose behalf the interrupting act was done. Nonetheless the alleged debtors would be bound, if they are so required, to state under oath that they are no longer indebted; and their heirs or interested parties, whom they believe, in good faith, that nothing more is due. CHAPTER 13 - General provisions', 'en', 'Commercial Code (Expanded), Article 399', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '400', 'Article 400 The payment of a Bill of Exchange the maturity of which falls on a legal holiday may not be exacted except on the first working day following. Likewise, all other acts relating to the Bill of Exchange, notably presentation for acceptance and protest, may not be made except on a working day. When one of these acts must be completed within a certain time-limit the last day of which is a legal holiday, the time is extended up to the first working day following the expiry. Intervening holidays are comprised in the computation of the time-limit.', 'en', 'Commercial Code (Expanded), Article 400', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '401', 'Article 401 Legal or conventional time-limits do not comprise the day which serves as starting-point.', 'en', 'Commercial Code (Expanded), Article 401', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '402', 'Article 402 No grace day, either legal or judicial, is allowed, except for those cases referred to in articles 365 and 367. TITLE II - THE PROMISSORY NOTE', 'en', 'Commercial Code (Expanded), Article 402', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '403', 'Article 403 The promissory note contains 1- The phrase "to order" or the denomination of the instrument inserted within the text itself and expressed in the language used in the writing of the instrument; 2- The promise pure and simple to pay a determined sum; 3- The indication of maturity; 4- The place where payment is to be effected; 5- The name of the person to whom or to whose order payment is to be made; 6- The date and place where the note is subscribed; 7- The name of he who issues the instrument (subscriber).', 'en', 'Commercial Code (Expanded), Article 403', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '404', 'Article 404 The instrument in which one of the statements indicated in the preceding article is missing is not valid as promissory note, except in the cases determined by the following sub-paragraphs - The promissory note the maturity of which is not indicated is considered as payable at sight. In the absence of special indication, the place where the instrument is created is reputed to be the place of payment, and, at the same time, the place of the subscriber''s domicile. - The promissory note which does not indicate the place of its creation is considered as subscribed in the place designated beside the subscriber''s name.', 'en', 'Commercial Code (Expanded), Article 404', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '405', 'Article 405 Are applicable to the promissory note, in so far as they are not inconsistent with the nature of this instrument, the provisions relating to the Bill of Exchange arid concerning Endorsement (articles 325 - 335) Maturity (articles 348 - 352) Payment (articles 353 - 364) Remedy for default in payment (articles 365 - 372, 374 - 376) Protests (articles 377, 380) Replacement (articles 381, 382) Payment through intervention (articles 387 - 391) Copies (articles 395, 396) Changes (article 397) Prescription (articles 398, 399) Holidays, the computation of time-limits and prohibition of grace days (articles 400, 402)', 'en', 'Commercial Code (Expanded), Article 405', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '406', 'Article 406 Are likewise applicable to the promissory note the provisions concerning the Bill of Exchange payable at a Third Party''s or in a locality other than that of the drawee''s domicile (articles 317 and 342), the stipulation of interests (article 318), differences of statements regarding the sum to be paid (article 319), the consequences of affixing a signature in the conditions referred to in article 320, those of the signature of a person who acts without powers or in excess of his powers (article 321).', 'en', 'Commercial Code (Expanded), Article 406', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '407', 'Article 407 Equally applicable to the promissory note are those provisions relating to guarantee (articles 345 and 34?) as is referred to in article 346, last subparagraph; if the guarantee does not indicate for whose account it has been given, it is reputed to have been for the account of the promissory note subscriber.', 'en', 'Commercial Code (Expanded), Article 407', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '408', 'Article 408 A promissory note subscriber is obliged in the same manner as the acceptor of a Hill of Exchange. Promissory note payable at deferred sight must be presented to the subscriber for signature within the time-limit set in article 338. The time-limit for sight runs from the date of the subscriber''s signature on the note. The subscriber''s refusal to give his dated-signature is established by protest (article 340.) the date of which serves as starting-point for the sight time limit. TITLE III - THE CIRQUE CHAPTER 1 - The creation and form of cheque', 'en', 'Commercial Code (Expanded), Article 408', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '409', 'Article 409 The cheque contains 1- The denomination of cheque inserted within the very text of the instrument and expressed in the language used in the making out of the instrument; 2- The order pure and simple to pay a determined sum; 3- The name of he who is to pay (drawee); 4- The place where payment is to be effected; 5- The date and place where the cheque is created; 6- The signature of he who issues the cheque (drawer).', 'en', 'Commercial Code (Expanded), Article 409', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '410', 'Article 410 The instrument in which one of the statements indicated in the preceding article is missing is not valid as a cheque, except in those cases as are determined in the following sub-paragraphs In the absence of a special indication, the place designated beside the name of the drawee is reputed to be the place of payment. If several places are indicated beside the name of the drawee, the cheque is payable in the first indicated place. In the absence of these indications and of any other indication, the cheque is payable in the place where the drawee has his main establishment. The cheque without indication of the place of its creation is considered as subscribed in the place designated beside the name of the drawer.', 'en', 'Commercial Code (Expanded), Article 410', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '411', 'Article 411 The cheque may not be drawn except on a banker having, at the time of the creation of the instrument, funds at the drawer''s disposal and in conformity with an agreement express or tacit by which the drawer is entitled to dispose of his funds by cheque.', 'en', 'Commercial Code (Expanded), Article 411', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '412', 'Article 412 The cheque may not be accepted. Mention of acceptance carried on the cheque is reputed unwritten. However the drawee is entitled to sign the cheque; signing has for effect to establish the existence of provision at the time when it is given.', 'en', 'Commercial Code (Expanded), Article 412', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '413', 'Article 413 The cheque may be stipulated payable - To a designated person, with or without the express phrase "to the order"; - To a designated person, with or without the phrase "not to order", or an equivalent phrase; - To bearer. The cheque for the benefit of a designated person, with the mention "or to bearer" or an equivalent phrase is valid as cheque to bearer. The cheque without indication of the beneficiary is valid as a cheque to bearer.', 'en', 'Commercial Code (Expanded), Article 413', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '414', 'Article 414 The cheque may be to the order of the drawer himself. The cheque may be drawn for a Third Party''s account. The cheque may not be drawn on the drawer himself, except in the case of a cheque drawn among different establishments of the same drawer and on condition that the cheque is not to bearer.', 'en', 'Commercial Code (Expanded), Article 414', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '415', 'Article 415 Any stipulation of interests inserted in the cheque is reputed unwritten.', 'en', 'Commercial Code (Expanded), Article 415', 'Negotiable instruments', 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-001-EXPANDED', '416', 'Article 416 The cheque may be payable at a Third Party''s domicile, either in the locality where the drawee has his domicile, or in another locality, on condition however that the Third Party is a banker.', 'en', 'Commercial Code (Expanded), Article 416', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '417', 'Article 417 The drawer is guarantor of payment. Any clause by which the drawer exonerates himself from such guarantee is reputed unwritten. CHAPTER 2 - Transmission', 'en', 'Commercial Code (Expanded), Article 417', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '418', 'Article 418 The cheque stipulated payable for the benefit of a stipulated person, with or without the express phrase "to order", is transferable by endorsement. The cheque stipulated payable for the benefit of a designated person, with the phrase "not to order" or an equivalent phrasing, is transferable only in the form and with the effects of an ordinary conveyance.', 'en', 'Commercial Code (Expanded), Article 418', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '419', 'Article 419 Endorsement may be made either for the benefit of the drawer or any other obligee. These persons may endorse the cheque anew.', 'en', 'Commercial Code (Expanded), Article 419', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '420', 'Article 420 Endorsement must be pure and simple. Any condition to which it is subordinated is reputed unwritten. Partial endorsement is null. The drawee''s endorsement is equally null. Endorsement to bearer is valid as blank endorsement. Endorsement for the drawee is valid as receipt, except in the case where the drawee has several establishments or where the endorsement is made for the benefit of an establishment other than that on which the cheque has been drawn.', 'en', 'Commercial Code (Expanded), Article 420', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '421', 'Article 421 The holder of an endorseable cheque is considered as legitimate bearer, if he justifies his title by an uninterrupted succession of endorsements even if the last endorsement is blank. Struck-off endorsements are, in this respect, reputed unwritten. When a blank endorsement is followed by another endorsement, the latter''s signatory is reputed having acquired the cheque through the blank endorsement.', 'en', 'Commercial Code (Expanded), Article 421', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '422', 'Article 422 An endorsement standing on a cheque to bearer renders the endorser liable to the terms of the provisions regulating recourse; it does not convert the instrument into a cheque to order.', 'en', 'Commercial Code (Expanded), Article 422', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '423', 'Article 423 When a person has been disposed of a cheque to order by whatever occurrence this may be, the beneficiary who justifies his title in the manner indicated in article 421 is not bound to relinquish the cheque except if he has acquired it through ill faith or if, by acquiring it, he has committed a grievous fault.', 'en', 'Commercial Code (Expanded), Article 423', 'Liability and damages', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '424', 'Article 424 Endorsement made after protest or after expiry of the time-limit for presentation produces the effects of a mere conveyance. Except for proof to the contrary, undated endorsement is presumed having been made before the protest or before expiry of the time-limit referred to in the preceding sub-paragraph. CHAPTER 3 - Presentation and payment', 'en', 'Commercial Code (Expanded), Article 424', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '425', 'Article 425 The cheque is payable at sight. Any mention to the contrary is reputed unwritten. The cheque presented for payment before the day indicated as date of issue. is payable on the day of presentation.', 'en', 'Commercial Code (Expanded), Article 425', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '426', 'Article 426 The cheque issued and payable in Lebanon must be presented for payment within eight days. The cheque issued out of Lebanon and payable in Lebanon must be presented within 20 days if the date of issue is located in one of the countries bordering on Lebanon or Syria, in Europe, or in a country bordering on the Mediterranean. The time-limit is of 70 days if the cheque was issued in any other country.', 'en', 'Commercial Code (Expanded), Article 426', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '427', 'Article 427 When the cheque payable in Lebanon is issued in a country where there is in use a calendar other than the Gregorian calendar, the date issue shall be brought back to the corresponding day in the Gregorian Calendar.', 'en', 'Commercial Code (Expanded), Article 427', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '428', 'Article 428 (as modified by Law NO 30/67 of 16 May 1967) The drawee must pay even after expiry of the time-limit for presentation. Opposition to the payment of the cheque by the drawer is receivable only in the event of loss of the cheque or of the insolvency of the Bearer. If, in spite of this defense, the drawer puts a bar for other causes, the judge of the Summary Court, even when an instance in principal should be initiated, shall be bound upon the bearer''s request to remove this opposition.', 'en', 'Commercial Code (Expanded), Article 428', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '429', 'Article 429 Neither the drawer''s death, nor his incapacity occurring after the issue touch the effects of the cheque.', 'en', 'Commercial Code (Expanded), Article 429', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '430', 'Article 430 The drawee may demand, on paying the cheque, that it is remitted to him duly settled by the bearer. The bearer may not refuse a partial payment. If the fund is less than the amount of the cheque the bearer is entitled to exact payment up to the limit of the fund. In case of partial payment, the drawee may demand that mention of this payment be made on the cheque or that receipt therefor be given him. Partial payments against the amount of the cheque are a discharge for drawers and endorsers. The bearer is bound to protest the cheque for the surplus.', 'en', 'Commercial Code (Expanded), Article 430', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '431', 'Article 431 He who pays a cheque without opposition is presumed validly released. The drawee who pays an endorsable cheque is obliged to verify that the succession of endorsements is in order,-but not so the endorsers'' signatures.', 'en', 'Commercial Code (Expanded), Article 431', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '432', 'Article 432 When a cheque is stipulated payable in a currency which is not legal tender in Lebanon, the amount of it may be paid, within the time-limit for the presentation of the cheque, according to its value in Lebanese pounds on the day of payment. If payment has not been effected on presentation, the bearer may, as he chooses, require that the amount of the cheque be paid to him in Lebanese pounds according to the rate ruling, either on the day of presentation or the day of payment. Lebanese usages for the quotation of foreign currencies in which cheques are made out must be observed to determine the value of these currencies in Lebanese pounds. However, the drawer may stipulate that the sum to be paid shall be calculated according to a rate set in the cheque. The above stated rules do not apply when the drawer has stipulated that payment shall have to be made in a certain indicated currency (clause of actual payment in a foreign currency). CHAPTER 4 - Crossed cheque', 'en', 'Commercial Code (Expanded), Article 432', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '433', 'Article 433 The drawer or bearer of a cheque may cross it with the effects indicated in the following article. Crossing is effected by means of two parallel bars affixed recto. It may be general or special. Crossing is general if it does not carry between-.the two bars any designation or the word "banker" or an equivalent term; it is special if a banker''s name is written between the two bars. General crossing may be changed into special crossing, but special crossing may not be transformed into general crossing. Striking-off the crossing or the name of the designated banker is reputed not having occurred.', 'en', 'Commercial Code (Expanded), Article 433', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '434', 'Article 434 A cheque with general crossing may not be paid by the drawee except to a banker or to a client of the drawee. A cheque with special crossing may not be paid by the drawee except to a designated banker or, if the latter is the drawee, to his client. However the designated banker may have resort to another banker to cash-in. A banker may not acquire a crossed cheque except through one of his clients or another banker. He may not cash it for the account of other persons except these ones. The drawee or the banker who fails to observe the above provisions is liable for prejudice up to the amount of the cheque.', 'en', 'Commercial Code (Expanded), Article 434', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '440', 'Article 440 When the presentation of the cheque, the making of the protest or the equivalent proof within the prescribed time-limits is prevented by an insuperable obstacle (legal prescription or cases of force majeure) these time-limits are extended. The bearer is bound to serve, without delay, notice to his endorser of the case of force majeure and to mention this notice, dated and signed by him, on the cheque or on an allonge; for the surplus the provisions of article 367 are applicable. After the termination of force majeure, the bearer must, without delay, present the cheque for payment and, if need be, make protest or establish an equivalent proof. If force majeure persists beyond fifteen days dating from the day when the bearer, even before expiry of the time-limit for presentation, gave notice of the force majeure to his endorser, recourses may be initiated, neither the presentation nor the protest nor an equivalent proof being necessary in such case. Facts purely personal to the bearer or to the person he has entrusted with the presentation of the cheque, the making of the protest or the establishment of an equivalent proof, are not considered as constituting cases of force majeure. CHAPTER 6 - Plurality of exemplars', 'en', 'Commercial Code (Expanded), Article 440', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '441', 'Article 441 Excepting cheques to bearer, all cheques issued in a country and payable in another country or in a section overseas of the same country and vice-versa, or issued and payable in the same part or in diverse parts overseas of the same country, may be drawn in several identical exemplars. When a cheque is established in several exemplars, these exemplars must be considered as a distinct cheque. CHAPTER 7 - Prescription', 'en', 'Commercial Code (Expanded), Article 441', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '442', 'Article 442 The bearer''s actions in recourse against the endorsers, the drawer and other obligees, are limited to six months from expiry of the presentation time limit. Recourse actions of various obligees to the payment of a cheque the ones against the others are limited to six months dating from the day when the obligee has paid the cheque or from the day when he himself was prosecuted. However in case of forfeiture or lapse by passage of time there still lies an action against the drawer who has not provided fund or the other obligees who have unjustly enriched themselves. The action of the cheque bearer against the drawee lapses within three years CHAPTER 8 - General and penal provisions', 'en', 'Commercial Code (Expanded), Article 442', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '443', 'Article 443 Presentation and protest of a cheque may not be initiated except on a working day. When the last day of the time-limit granted by the law to undertake actions relating to the cheque and notably for its presentation or for the making of protest, or for an equivalent action, is a legal holiday, this time-limit is extended up to the first working day following the expiry. Intermediate holidays are comprised in the computation of the time-limit.', 'en', 'Commercial Code (Expanded), Article 443', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '444', 'Article 444 Remittance of a cheque for payment, accepted by a creditor, does not imply substitution. In consequence, the original claim remains, with all the guarantees attached thereto, until the said cheque has been paid.', 'en', 'Commercial Code (Expanded), Article 444', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '445', 'Article 445 Independently of the formalities prescribed to bring an action in guarantee, the bearer of a protested cheque may, by obtaining the authorization of the head of the of the Executive Office and without being compelled to provide security, distrain by way of conservation the movable belongings of the drawers and endorsers.', 'en', 'Commercial Code (Expanded), Article 445', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '446', 'Article 446 (as modified by Law NO 30/67 of 16 May 1967) The drawer who issues a cheque bearing no indication of the place of issue or of date, he who vests the cheque with a false date, is under penalty of a fine of 6 per cent of the sum for which the cheque is drawn, but such fine may not be less than five Lebanese pounds. The same fine is due, personally and without recourse, by the first endorser or the bearer of a cheque without indication of a place of issue or without date or bearing a later date than that at which it was endorsed or presented. This fine is due, on the other hand, by he who pays or receives in compensation a cheque without indication of the place of issue or without date.', 'en', 'Commercial Code (Expanded), Article 446', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '447', 'Article 447 (as modified by Law N° 30/67 of 16 May 1967) Any banker who, having fund, delivers to his creditor blank cheque forms payable at his counter, must, under penalty of a fine of one Lebanese pound per infringement, mention on each form the name of the person to whom this form is delivered. Every banker must print on the cover of the cheque books he delivers to his clients the text of article 666 of the Penal Code, under penalty of a fine of 10 Lebanese pounds per infringement.', 'en', 'Commercial Code (Expanded), Article 447', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '448', 'Article 448 (as modified by Law N° 30/67 of 16 May 1967) The offence of issuing an unfunded cheque is subject to the penalties provided by article 666 of. the Penal Code.', 'en', 'Commercial Code (Expanded), Article 448', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '449', 'Article 449 The drawee who knowingly mentions a fund less than the existing fund is subject to a fine of between 25 and 500 Lebanese pounds.', 'en', 'Commercial Code (Expanded), Article 449', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '450', 'Article 450 In so far as they are not inconsistent with the nature of the cheque, are additionally applicable to this instrument articles 319 to 321; 32? to 329, 331, 332, 335, 345 to 347, 353 - second sub-paragraph, 359, 361 to 364, 367 to 369, 372, 377, 393; 397, 399, 401 and 402 of the present code. The protest action referred to under article 362 must be made, at the latest, the first working day following the expiry of the time-limit for the presentation of the cheque. TITLE IV - OTHER TITLES TRANSFERABLE BY ENDORSEMENT', 'en', 'Commercial Code (Expanded), Article 450', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '451', 'Article 451 Any title by which the subscriber undertakes to deliver to a determined place and at a determined time a certain sum of money or a certain quantity of fungible things may be transmitted by endorsement, if it has been expressly created to order. Barring provisions contrary to the law or to the title itself, endorsement is regulated by the provisions of articles 325 and the following ones, concerning the endorsement of Hills of Exchange. The debtor may not oppose other exceptions than those resulting from the title itself or those that lie directly against the plaintiff, unless the latter is of ill faith. He is not bound to pay except in return for the remittance of the title to order duly settled.', 'en', 'Commercial Code (Expanded), Article 451', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '452', 'Article 452 Except for the parties'' contrary volition, the remittance of a Hill of Exchange, of a promissory note or of any other negotiable instrument, in settlement of a debt, operates no change by which a new title is substituted to an old one. TITLE V - MOVABLE SECURITIES', 'en', 'Commercial Code (Expanded), Article 452', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '453', 'Article 453 Shares, debentures, rents and all other negotiable securities which, issued in the lump and representing claims to identical sums of money, are apt to have currency on a Stock Market, may be either registered, or to bearer, or to order.', 'en', 'Commercial Code (Expanded), Article 453', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '454', 'Article 454 When the security is created to bearer, conveyance is operated by mere delivery. Every security holder is supposed to be qualified to exercise the rights relevant to this security; and, so long as he has not received regular opposition, the debtor validly frees himself from debt between the bearer''s hands. The debtor may not oppose the bearer but for the exceptions drawn from the nullity of the security or deriving from its own text.', 'en', 'Commercial Code (Expanded), Article 454', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '455', 'Article 455 In the case of a registered security, the title of the security owner is established by an entry made in his name on the registers of the issuing establishment. Ownership of the security results from the entry itself.', 'en', 'Commercial Code (Expanded), Article 455', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '456', 'Article 456 Conveyance of the registered security is operated by a declaration of transfer entered on the registers and signed by he who makes the assignment or by a proxy. The debtor establishment may require, before entering the assignment, that the declarer justifies his identity and capacity. Transfer confers on the new registered holder a title proper and direct; the debtor establishment cannot oppose to him any exception on account of the previous holders.', 'en', 'Commercial Code (Expanded), Article 456', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '457', 'Article 457 Registered securities may be provided with detachable coupons allowing the payment of arrears, dividends or interests to any bearer of these coupons (mixed securities).', 'en', 'Commercial Code (Expanded), Article 457', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '458', 'Article 458 Movable securities created to order are conveyed by endorsement. Except for provisions to the contrary resulting from laws and regulations or from the very nature of the security itself, endorsement is governed by the same rules as the endorsement of the Dill of Exchange. HOOK V COMPOSITION AND SIMPLE INSOLVENCY TITLE I - COMPOSITION', 'en', 'Commercial Code (Expanded), Article 458', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '459', 'Article 459 Any trader, either before his suspension of payment, or within the ten days of his suspension of payment, may apply to the Court of primary jurisdiction where lies his main establishment, and ask for the convocation of all his creditors to propose them a scheme of arrangement (composition).', 'en', 'Commercial Code (Expanded), Article 459', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '460', 'Article 460 In support of his petition the trader is required to submit his compulsory trade books, kept in accordance with regulations for the last three years, or since the beginning of his going into trade in which he has engaged for at least three years; the evidence of his registration on the trade register; a detailed estimate statement of his operations; a list of all his creditors, stating their names, the figure of their respective claims and their domicile; and, in the case of a company, all such documents as may prove that the company has been formed in conformity with regulations. The trader shall state the reasons which have prompted him to petition for a scheme of arrangement. He shall indicate the dividends which he intends to propose to his creditors or the reasons for which he may not immediately declare his proposals. He shall equally state the real or personal guarantees that he offers his creditors. In all cases, the proposed dividend must be at least 50% of his unsecured claims payable within a year, of 75% if maturity is within eighteen months, of 100 if it is three years away.', 'en', 'Commercial Code (Expanded), Article 460', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '461', 'Article 461 The Court, after hearing the Public prosecutor, shall be required to declare the petition unreceivable 1- If the petitioner has failed to deposit the books and documents designated in the preceding article; 2- If the petitioner has been previously convicted for fraudulent bankruptcy, forgery, theft, breach of trust, swindling, embezzlement of public funds, or if he has not honored commitments to which he has pledged himself on the occasion of a previous scheme or if, having been declared in solvent, he has not fully paid all his creditors or has failed to meet in full the obligations deriving from composition; 3- If he offers no serious guarantees enabling him to pay the proposed dividend; 4- If he has absconded after closing down all his stores or if he has embezzled or fraudulently reduced his patrimony. In all such cases, the Court shall officially adjudicate insolvency, if the trader has stopped paying out his trade debts.', 'en', 'Commercial Code (Expanded), Article 461', 'Theft and robbery', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '462', 'Article 462 If the Court acknowledges that the petition is in order and receivable, it shall ordain, by a ruling subject to no appeal, the convocation of creditors before a judge delegated to discuss and debate the proposal of the scheme of arrangement. It shall designate the place, the day and the hour of the meeting, within a maximum 30 days dating from the ruling, as well as the time-limit in which such ruling shall be published and notified to the creditors. It shall appoint a trustee, who may not be one of the creditors, whose duty will consist in supervising, meanwhile, the management of the business, the auditing of its liabilities and assets, examining how the debtor has acted and submit a report to the meeting of creditors. It shall allow the petitioner a time-limit not exceeding five days so that he may complete the nominal list of all his creditors, whenever the trader has stated in his petition the reasons why it is impossible for him to produce such a complete list immediately. At the diligence and under the signature of the delegated judge and the Clerk, the ruling shall be mentioned immediately after the last entries on the books, which shall be returned to the petitioner.', 'en', 'Commercial Code (Expanded), Article 462', 'Taxation', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '463', 'Article 463 The ruling shall be, at the Clerk''s diligence, published by means of posters affixed on the Court door and by an abstract inserted in a media of legal advertising, and entered on the trade register, as shall be determined by the time-limit set down in the ruling itself. If the nominal list of the creditors is incomplete or if a wider publicity is deemed necessary, the Court may designate other newspapers, even foreign ones, in which an insertion shall have to be made. The Clerk shall communicate to each creditor, by registered letter or by cable according to what the distance may require, a notice setting out the names of the debtor, of the delegated judge and the trustee, the date of the ruling summoning the creditors, the place and date of the meeting, with summary indication of the debtor''s proposals. The documentary evidence proving that the publication and communications to the creditors have been made, must be annexed to the file.', 'en', 'Commercial Code (Expanded), Article 463', 'Press and media', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '464', 'Article 464 Beginning from the filing of the petition and until the ruling in confirmation of the scheme arrangement has gained power as an adjudicated matter, no creditor in possession of a claim prior to the ruling shall be allowed, under penalty of nullity, to initiate or proceed with action for enforcement, acquire a preferential claim whatsoever on the debtor''s property, nor have a mortgage registered. Prescriptions, time-limitations or forfeitures, which would be interrupted s,.. Ordinary claims having no preferential rights shall be considered as forfeited and the running of interests shall be suspended in respect of the creditors only. The sums due by way of taxes, even preferentials, shall not be submitted to the effects provided in the present article.', 'en', 'Commercial Code (Expanded), Article 464', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '465', 'Article 465 Throughout the procedure of the scheme of arrangement, the debtor shall retain the management of his property and shall continue all normal operations pertaining to his enterprise, under the trustee''s supervision and the directives of the delegated judge. Both can always examine the trade books.', 'en', 'Commercial Code (Expanded), Article 465', 'Property law', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '466', 'Article 466 Donations and other acts, gratuitous or as security, granted by the debtor in the course of procedure, shall be no bar to the creditors. It shall be likewise with acts by which the debtor shall have acquired loans, even in the form of a Hill of Exchange, operated transactions or compromises, granted transfers of property which are not within the scope of trade, mortgages or pledges, without the authorization of the delegated judge, who shall not give such authorization except in cases of evident utility.', 'en', 'Commercial Code (Expanded), Article 466', 'Property law', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '467', 'Article 467 Should the debtor contravene the provisions of the preceding two articles or if it is proven that he has concealed part of his assets or that he has fraudulently omitted certain claims or, broadly speaking, committed any fraud, the delegated judge shall refer the matter to the Court Council Chamber, which shall adjudicate insolvency, without prejudice to other penal sanctions incurred by the trader.', 'en', 'Commercial Code (Expanded), Article 467', 'Fraud', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '468', 'Article 468 After examining the debtor''s books and titles and with such information as he may be able to gather, the trustee ''shall check the list of creditors and debtors, entering thereon all the necessary modifications with indication of the respective amount of claims and debts. If necessary, he shall require the interested parties to furnish useful clarifications. He shall then draft a detailed report on the debtor''s trading situation and his administration, depositing such report in the Clerk''s office at least three days before the meeting provided for the arrangement scheme.', 'en', 'Commercial Code (Expanded), Article 468', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '469', 'Article 469 The creditor''s meeting shall be chaired by the delegated judge. Any creditor may have himself represented by a special proxy duly vested with power; such power may be given in writing and without formality, on the letter or telegram giving notice of the meeting The debtor or his legal representative shall have to appear in person. Representation by special proxy shall be admitted only in the event of the debtor''s absolute impediment established by the delegated judge. Following the reading of the trustee''s report, the debtor shall table his final proposals. If, at the appointed day, it is not possible to terminate all the operations, continuation shall be reputed adjourned to the nearest working day, without further notice to the creditors even the absentees, and so forth until the end of the operations.', 'en', 'Commercial Code (Expanded), Article 469', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '470', 'Article 470 Any creditor may put forward the reasons for which he considers as challengeable such or such a claim, or the debtor as undeserving the favor he claims, or the proposals tabled by him as unacceptable. The debtor shall be entitled to answer and shall have to furnish all the clarifications that may be requested. Summary mention of these incidents shall be made in the proces-verbal, to which the documents shall be attached.', 'en', 'Commercial Code (Expanded), Article 470', NULL, 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-001-EXPANDED', '471', 'Article 471 The scheme of arrangement shall have to be approved by all the creditors who have cast their votes and who shall be required to represent at least three-fourths of all the claims unpreferential or unguaranteed by mortgage or by pledge. Creditors in possession of a mortgage, a preference or a pledge may however combine to form this majority, if they renounce using their surety. Such renunciation may apply only to part of the claim and its accessories, provided that the portion of the sum for which it occurs is determined and is no less than one-third of the aggregate amount of the claims. The vote cast without declaration of limited renunciation and the subsequent adherence to the agreement which shall be dealt with hereinafter carry, as a matter of right, renunciation of the surety over the entire claim. The Court, in its ruling of confirmation, shall take into account the possible increase of the debtor''s assets as a result of these votes or of these adherences. The effects of renouncing a preference, a mortgage or a pledge, even partial, shall rightfully cease, whenever the scheme has not materialized or has been cancelled.', 'en', 'Commercial Code (Expanded), Article 471', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '472', 'Article 472 To form the majority indicated in the preceding article, claims of the debtor''s spouse shall not be accounted, nor shall be those of family relations and relations by marriage up to the fourth degree inclusive. Shall equally be excluded from the vote the transferees and purchasing parties of such claims in the year preceding the petition for an arrangement scheme. Conveyance of claims subsequent to the ruling summoning the creditors shall be no title to voting on the scheme.', 'en', 'Commercial Code (Expanded), Article 472', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '473', 'Article 473 The delegated judge shall have the adherence entered in the proces-verbal which shall be signed by all the adherents. In the majority, account shall be taken of the adherences sent by cable or letter, addressed to the delegated judge or the Clerk within five days following the closure of the proces-verbal of the meeting. These adherences shall be entered by the Clerk, on the margin of the proces-verbal, and annexed.', 'en', 'Commercial Code (Expanded), Article 473', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '474', 'Article 474 By ordinance in the proces-verbal before the affixing of signatures, the delegated judge shall refer the parties to a determined session of the Court for confirmation of the scheme, within a maximum time limit of 20 days.', 'en', 'Commercial Code (Expanded), Article 474', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '475', 'Article 475 Three days before the Court session set for confirmation, the trustee shall deposit in the Clerk''s office his findings on whether the scheme of arrangement is receivable. At the session the delegated judge shall table his report. Both the debtor and the creditors shall be entitled to intervene in the proceedings. The Court may summon the trustee to the Council Chamber to ask him for information, subject to prior notice to the debtor and creditors who may have intervened.', 'en', 'Commercial Code (Expanded), Article 475', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '476', 'Article 476 The Court, in its award of confirmation, shall appreciate in a provisional manner and through presumption, the importance and the amount of the declared claims, so as to establish if the required majority exists, without prejudice to the definitive rulings that they may intervene.', 'en', 'Commercial Code (Expanded), Article 476', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '477', 'Article 477 The Court, if it acknowledges that the debtor deserves the benefit of a com position, that the oppositions referred to in the preceding articles allow the existence of the required majority, that the composition proposals not less than the legal minimum are legitimate and that the execution thereof is assured, shall grant the solicited confirmation. - In the same ruling, it shall ordain the delivery of the dividend which may be assigned to the declared claims. If, on the contrary, confirmation is not granted, the Court shall adjudicate insolvency, as a matter of course.', 'en', 'Commercial Code (Expanded), Article 477', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '478', 'Article 478 Except for a contrary covenant consented in the scheme in another deliberation, taken within the framework of the aforementioned conditions and confirmed by the Court, the debtor shall not be entitled, prior to executing in full the commitments set down in the scheme, to alienate or mortgage his buildings, engage in pledge, or in general divert part of his assets in a manner other than that which is required by the nature of his trade and of his industry. Any act performed in violation of this prohibition shall be of no effect in respect of creditors prior to the confirmation of the scheme.', 'en', 'Commercial Code (Expanded), Article 478', 'Mortgage', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '479', 'Article 479 Rulings granting or rejecting the confirmation of a scheme shall be published in accordance with the rules which shall be laid down hereinafter for the order adjudicating insolvency.', 'en', 'Commercial Code (Expanded), Article 479', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '480', 'Article 480 Dissenting creditors may, within five days of the final closure of the proces-verbal, oppose the confirmation of the scheme of arrangement. Such opposition must be motivated and notified to the debtor and the trustee. Appeal is receivable only from the debtor himself and from those creditors who have moved an opposition. The time-limit for appeal is fifteen days. As soon as the award of confirmation has become final, the trustee''s functions officially come to an end, except if a specific clause of the scheme of arrangement had charged the trustee with the control of its execution. The charges and sums which shall be due to the latter shall be set by the delegated judge; any agreement to the contrary is void.', 'en', 'Commercial Code (Expanded), Article 480', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '481', 'Article 481 Approval shall reader the scheme of arrangement enforceable upon all the creditors. The creditors, even if they have voluntarily agreed to the scheme, shall retain all their rights unimpaired against all codebtors, the debtor''s transferees and securities, who may however intervene in the instance to table their remarks on the scheme of arrangement.', 'en', 'Commercial Code (Expanded), Article 481', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '482', 'Article 482 The benefit of the scheme of arrangement granted to a company applies even to those partners who are personally held for the company''s liabilities, except for provisions to the contrary.', 'en', 'Commercial Code (Expanded), Article 482', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '483', 'Article 483 In the case of any trading company having issued debentures amounting to more than twenty per cent of total liabilities, the scheme of arrangement may be granted only in so far as the proposals have been approved by the meeting of debenture-holders, deliberating in accordance with the terms of quorum and majority laid down for joint-stock companies. The adherence of the group of debenture-holders would always be required, irrespective of the ratio of debenture-holder liabilities to total liabilities, when the scheme of arrangement should include special conditions not conforming to those which might have been fixed at the time of issue in respect of debenture-holders.', 'en', 'Commercial Code (Expanded), Article 483', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '484', 'Article 484 Whenever it shall become useful to convene a meeting of the debenture holders, the time-limit which has been stated above for the convening of creditors may be extended up to 60 days.', 'en', 'Commercial Code (Expanded), Article 484', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '485', 'Article 485 Holders of debentures with redemption premiums shall produce not only for the price of issue, but also for that portion of the premium which the time elapsed has earned them.', 'en', 'Commercial Code (Expanded), Article 485', 'Insurance', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '486', 'Article 486 On the request of any creditor, put forward within three years dating from the publication of the award of confirmation, the Court may cancel the scheme of arrangement and declare the debtor''s insolvency, if it is proved that the latter has fraudulently inflated his liabilities or concealed an appreciable part of his assets. No other action in nullity of the scheme of arrangement shall be received after its confirmation. Should the scheme of arrangement be cancelled, the sureties who have not been party to the fraud shall be released of the commitments accepted by them in the scheme, and the mortgages and other guarantees constituted in the same deed shall lapse as a matter of right.', 'en', 'Commercial Code (Expanded), Article 486', 'Fraud', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '487', 'Article 487 If the debtor fails to discharge in full his obligations under the scheme of arrangement, any creditor may - after the sureties have been discussed and the rights conceded by way of guarantee have been asserted - cancel the scheme and have the debtor''s insolvency adjudicated.', 'en', 'Commercial Code (Expanded), Article 487', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '488', 'Article 488 The scheme of arrangement may have provided that the trader shall be definitively released of the reduction under the scheme only if he does not revert to better fortune, but the application of this clause must be limited to a period of rive years, and to the case when the debtor''s assets happened to exceed his. liabilities by at least twenty-five per cent. TITLE II - INSOLVENCY (1) CHAPTER 1 - Opening of insolvency', 'en', 'Commercial Code (Expanded), Article 488', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '489', 'Article 489 Subject to the enforcement of the provisions of the preceding title, is in state of insolvency any trader who suspends the payment of his trade debts or who upholds his credit only by means manifestly illicit.', 'en', 'Commercial Code (Expanded), Article 489', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '490', 'Article 490 Insolvency is declared by adjudication of the Court of primary jurisdiction in the principal place of business. Such adjudication is provisionally executory. If several Courts should simultaneously adjudicate insolvency to the same trader, there would be a case for settlement by judges. The aforementioned Court is competent to take cognizance of all actions stemming from the rules proper to insolvency.', 'en', 'Commercial Code (Expanded), Article 490', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '491', 'Article 491 The Court may be acquainted first by the trader''s own declaration; the trader is bound, under penalty of committing an offence of simple bankruptcy, to make this declaration within twenty days of his suspending payments, at the same time as he submits a detailed balance sheet duly certified true to the situation of his liabilities and assets.', 'en', 'Commercial Code (Expanded), Article 491', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '492', 'Article 492 The Court may also be acquainted by the writ of one or several creditors, which shall be served within three days. In urgent cases, such as when the trader has closed his stores and absconded, or has caused the disappearance of a substantial portion of his assets, the creditors shall be entitled to act by mere petition without a writ of summons. In this event the Court shall adjudicate in Council Chamber.', 'en', 'Commercial Code (Expanded), Article 492', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '493', 'Article 493 The Court is entitled to decree the conservation measures required to safeguard the creditors'' rights, either on order from the Public Prosecutor''s office, or on its own initiative. It could even, if need be, adjudicate insolvency, in its own right. (1) In the present legislative text, "insolvency" is meant to connote the French word "faillite", whereas "bankruptcy" is meant to connote the French word "banqueroute".', 'en', 'Commercial Code (Expanded), Article 493', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '494', 'Article 494 The insolvency of a trader who has retired from business or is deceased may be pronounced within the year of the suspension of trading or of death if the facts of suspension of payment are prior to these events. Hut the deceased trader''s heirs may not themselves petition for his insolvency.', 'en', 'Commercial Code (Expanded), Article 494', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '495', 'Article 495 The adjudication of insolvency determines the period in which payments have been suspended. But this period may be fixed at an older date by one or several carry-over rulings pronounced subsequently on the commissioner-judge''s report, either officially, or on the request of any interested party, notably the creditors acting individually. Such a request shall not be receivable after the time-limit set by article 551, at the end of which the statement of the debts is definitively closed. At the expiry of this time-limit, the period of suspension of payment shall remain irrevocably determined in relation to the creditors. The period of suspension of payments may not be fixed to a prior date of more than eighteen months from adjudication of insolvency.', 'en', 'Commercial Code (Expanded), Article 495', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '496', 'Article 496 The adjudication of insolvency, as well as the carry-over ruling of the date of suspension of payment must be, through the good offices of Receivers, posted within five days in the Court auditorium which has pronounced them and in the premises of the nearest Exchange. They must equally be inserted by abstracts in a press medium, within the same time-limit. This publicity shall be made in the district where insolvency has been declared as well as in the various places where the insolvent has trading establishments. The said adjudication and ruling shall equally be entered on the trade register .and communicated to the public prosecutor, through the good offices of the Clerk.', 'en', 'Commercial Code (Expanded), Article 496', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '497', 'Article 497 Adjudication and ruling are subject to opposition and appeal. The same app- . lies in respect of all rulings in insolvency matters, except for provisions to the contrary in the present code. The time-limits for opposition shall be of a uniform eight days and the time-limits of appeal of fifteen days, dating from the rulings. However as regards those rulings subject to publicity formalities and insertion by abstract in newspapers, the time-limits are computed from the day when formalities have been completed. Appeal is judged by the Court within three months.', 'en', 'Commercial Code (Expanded), Article 497', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '498', 'Article 498 When in the course of a civil, commercial or penal suit, the judges incidentally ascertain the evident insolvent state of a trader, they may, though insolvency has not been declared, apply its basic rules as they are laid down in the present book. CHAPTER 2 - Immediate effects of adjudication of insolvency', 'en', 'Commercial Code (Expanded), Article 498', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '499', 'Article 499 The name of tradesmen declared insolvent and not rehabilitated shall be posted on a notice board at the door of each court and in the Ring of all Exchanges. Such posting does not take place if the tradesman was dead at the time of adjudication of insolvency, and it shall be struck off within six months of his death in all other cases.', 'en', 'Commercial Code (Expanded), Article 499', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '500', 'Article 500 Every insolvent is additionally the object of civic forfeitures : he is no longer an elector, nor is he eligible to political or professional assemblies; he can hold no public office or function.', 'en', 'Commercial Code (Expanded), Article 500', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '501', 'Article 501 The adjudication of insolvency carries with it, as a matter of course, from the very day it was declared, relinquishment by the insolvent in favor of Receivers, of the management of all his property, even of those which may revert to him during the period of insolvency. The insolvent may not notably alienate any item of his property; he can no longer effect any payment, nor receive any, unless this concerns the settlement made in good faith of a trade dill; he can contract no obligation, or take legal proceedings, except as party to the case in actions initiated by the Receivers. But he may take all conservation actions designed to safeguard his rights.', 'en', 'Commercial Code (Expanded), Article 501', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '502', 'Article 502 Excluded from relinquishment are those rights attaching exclusively to the person of the insolvent or to his quality as family head as well as those which may put at stake an interest of an essentially moral order, except where Receivers are intervening parties in a suit which is to lead to a conviction involving money. Equally outside the scope of relinquishment are those items of property which by law are not subject to distraint, as well as earnings which the insolvent can secure by his activity or his industry, so long as they remain within the limits set by the commissioner-judge as corresponding to the needs of his subsistence and that of his family.', 'en', 'Commercial Code (Expanded), Article 502', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '503', 'Article 503 Adjudication of insolvency suspends, in relation to unsecured creditors and creditors provided with general preference, individual proceedings which are henceforth in the hands of Receivers, no distinction-being drawn between a civil or a trade debt.', 'en', 'Commercial Code (Expanded), Article 503', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '504', 'Article 504 The adjudication of insolvency suspends, in relation to capital stock only, the run of interests on debts not guaranteed by a preference, a pledge or a mortgage. The interests on guaranteed debts may not be claimed except on sums resulting from the sale of goods pertaining to surety.', 'en', 'Commercial Code (Expanded), Article 504', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '505', 'Article 505 The adjudication of insolvency entails in relation to the insolvent, but not in relation to his -co-obligees, the forfeiture of the term, even on behalf of such creditors as may hold a surety. Holders of debentures with redemption premiums shall deliver particulars immediately as has been provided under the title of the scheme of arrangement.', 'en', 'Commercial Code (Expanded), Article 505', 'Insurance', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '506', 'Article 506 If the insolvent is the owner of buildings or the holder of actual real estate rights, the adjudication of insolvency is submitted to the rules of publicity applicable on mortgages. It is inscribed through the Receivers'' care and gives rise, from the date of inscription, to a compulsory mortgage on behalf of capital stock.', 'en', 'Commercial Code (Expanded), Article 506', 'Mortgage', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '507', 'Article 507 Are void, relatively to the capital stock, when they have been made by the debtor, from the period of suspension of payment such as has been laid down by the Court or within twenty days prior to such period: 1- Gratuitous acts and conveyances, except the usual minimal donations, the creation of wakfs (endowments for charitable purposes). 2- Advance payments, under any form they may have been made. 3- Payment of mature cash debts effected otherwise than in cash, Bills of Exchange, money orders and broadly speaking any giving in payment. 4- The creation of a conventional or juridical mortgage, or a pledge or other surety on a debtor''s goods as collateral of a prior debt. When the giving in payment has been effected through the conveyance of a building, nullity shall have effect only in relation to the creditor who has dealt with the insolvent and shall not impair the rights of subsequent acquirers by way of payment, if such acquirers have acted in good faith.', 'en', 'Commercial Code (Expanded), Article 507', 'Mortgage', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '508', 'Article 508 All other payments effected by the debtor for mature debts and all other acts he has transacted against considerations after the suspension of payments and before the adjudication of insolvency, may be made void if, on the part of those who have received from him or dealt with him, such acts have occurred with due knowledge of the suspension of payment.', 'en', 'Commercial Code (Expanded), Article 508', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '509', 'Article 509 The cancellation of the aforementioned acts shall give rise to proceedings for return. In the case of payment of a Bill of Exchange or of a cheque, proceedings may not be taken except against the person for whose account the Bill has been provided. If it is a promissory note, proceedings may be taken only against the first endorser. In either case, proof must be established that the person from whom restitution is demanded was aware of the suspension of payment at the time when the title was issued.', 'en', 'Commercial Code (Expanded), Article 509', 'Negotiable instruments', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '510', 'Article 510 Shall be void relatively to capital stock the inscriptions of mortgages made after the registration of the adjudication of insolvency. Shall be subject to nullity such inscriptions as have been taken after the period of suspension of payments or within the twenty days preceding it, if more than fifteen days have elapsed between the date of the creation of the surety and that of inscription, and if the delay has caused prejudice to the creditors.', 'en', 'Commercial Code (Expanded), Article 510', 'Guarantees and sureties', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '511', 'Article 511 The actions in nullity provided under articles 507, 508 and 510 shall be time-limited to eighteen months from the day of the adjudication of insolvency. CIL42TER 3 - Insolvency procedure Section 1 - Insolvency organs', 'en', 'Commercial Code (Expanded), Article 511', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '512', 'Article 512 The management of the insolvent''s patrimony is entrusted to a salaried proxy, the Receiver. The adjudication of insolvency appoints one or several Receivers. The number of Receivers may be, at any period, raised to three; their charges and fees shall be taxed by the commissioner-judge, in conformity with the rates annexed to Legislative Decree N° 79 L of 13 March 1933. The debtor and creditors may oppose the tax within eight days; opposition shall be dealt with by the Court in Council Chamber.', 'en', 'Commercial Code (Expanded), Article 512', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '513', 'Article 513 By ordinance of the commissioner-judge, one or two supervisors may, at any period, be appointed from among those creditors who have applied for the function.', 'en', 'Commercial Code (Expanded), Article 513', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '514', 'Article 514 None of the family relations or the relations by marriage of the insolvent up to the fourth degree inclusive may be appointed Receiver.', 'en', 'Commercial Code (Expanded), Article 514', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '515', 'Article 515 If the case requires the addition or replacement of one or several Receivers, the matter shall be referred to the commissioner-judge who shall proceed with the appointment.', 'en', 'Commercial Code (Expanded), Article 515', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '516', 'Article 516 If several Receivers have been appointed, they cannot act but collectively. However, one or several of them may be given special authority by the commis sioner-judge to act separately in certain acts of administration. In the latter case the authorized receivers shall be solely liable.', 'en', 'Commercial Code (Expanded), Article 516', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '517', 'Article 517 If any complaints arise against any of the Receivers'' operations, the commis sioner-judge shall deal with the case within three days. The commissioner-judge''s decision shall be provisionally executory.', 'en', 'Commercial Code (Expanded), Article 517', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '518', 'Article 518 The commissioner-judge may, either on complaints filed by the insolvent or by the creditors, or even in discharge of his duties, propose the dismissal of one or several of the Receivers. If within eight days the commissioner-judge has not done justice to the complaints addressed to him, such complaints may be brought before the Court. The Court, in Council Chamber, shall hear the commissioner-judge''s report and the Receivers'' explanations and shall in the course of the sitting give its verdict on the dismissal.', 'en', 'Commercial Code (Expanded), Article 518', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '519', 'Article 519 Ruling in respect of the appointment or the dismissal of Receivers is open to no appeal.', 'en', 'Commercial Code (Expanded), Article 519', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '520', 'Article 520 In its adjudication of insolvency, the Court shall designate one of its members as commissioner-judge.', 'en', 'Commercial Code (Expanded), Article 520', 'Bankruptcy and insolvency', 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-001-EXPANDED', '521', 'Article 521 The commissioner-judge shall be specially charged to speed up and supervise the operations and management of the insolvency. He shall report to the Court on all the issues that the insolvency may give rise to and which shall be within the competence of- this Court.', 'en', 'Commercial Code (Expanded), Article 521', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '522', 'Article 522 The commissioner-judge''s ordinances are immediately lodged in the Clerk''s office. They shall in all cases be subject to opposition from any interested party before the Court, which may intervene officially. Opposition shall be formed by simple declaration in the Clerk''s office within five days dating from the ordinance. The Court shall deal with the case within eight days by a ruling open to no recourse.', 'en', 'Commercial Code (Expanded), Article 522', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '523', 'Article 523 The Court may, at any time, replace the commissioner-judge pertaining to the insolvency by another from its own members, no recourse being possible against this ruling nor against that appointing the commissioner-judge. Section 2 - Management of the insolvency''s estate', 'en', 'Commercial Code (Expanded), Article 523', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '524', 'Article 524 By its adjudication of insolvency, the Court ordains the affixing of the seals. It may, at any event; ordain that the insolvent shall be forcibly arrested and brought before it. In no case can the insolvent move away from his domicile without the commissioner-judge''s authorization. If the commissioner-judge is of the opinion that insolvent''s assets can be stock-taken in a single day, no seals shall be affixed, and it shall be immediately proceeded with stock-taking.', 'en', 'Commercial Code (Expanded), Article 524', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '525', 'Article 525 The Court''s clerk shall immediately address to the conciliation magistrate notice of the provision of the ruling which has ordained the affixing of the seals. The conciliation magistrate may, even before the ruling, affix the seals either in his official capacity, or on the request of one or several creditors, but only in the event of the disappearance of the debtor or of embezzlement of the whole or part of his assets.', 'en', 'Commercial Code (Expanded), Article 525', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '526', 'Article 526 Seals shall be affixed on the insolvent''s stores, counters, cash desks, portfolios, books, papers, furniture and belongings. In the event of the failure of a private company, seals shall be affixed not only on the main establishment of the company, but also on the individual domicile of each of the joint partners. In all cases, the conciliation magistrate shall immediately notify the Court President of the affixing of the seals.', 'en', 'Commercial Code (Expanded), Article 526', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '527', 'Article 527 If the affixing of the seals had not occurred before the appointment of the Receivers, the latter should require the conciliation magistrate to proceed therewith.', 'en', 'Commercial Code (Expanded), Article 527', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '528', 'Article 528 On the Receivers'' request, the commissioner-judge shall dispense them from placing under seals, or authorize them to withdraw therefrom : the clothes, wardrobe, furniture and belongings necessary to the insolvent and his family and whose delivery shall be authorized by the commissioner-judge, on the statement which shall be submitted by the Receivers. He may grant the same exemption for 1- Perishable objects or objects subject to impending depreciation; 2- Objects used in the exploitation of the stock-in-trade, when such exploitation could not be interrupted without prejudice to the creditors. The objects comprised within the preceding two paragraphs shall be immediately entered on the stock list, and valued by the Receivers, in the presence of the conciliation magistrate who shall sign the proces-verbal', 'en', 'Commercial Code (Expanded), Article 528', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '529', 'Article 529 Sale of the perishable objects or of objects subject to impending depreciation, or costly to keep, shall be left to the care of the Receivers duly authorized by the commissioner-judge. Exploitation of the stock-in-trade through the good offices of the Receivers shall not be authorized by the Court, on the evidence of the commissioner-judge''s report, except when public interest or the creditors'' should imperatively request it.', 'en', 'Commercial Code (Expanded), Article 529', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '530', 'Article 530 The books shall be extracted from the seals and remitted by the conciliation magistrate to the Receivers, after having been closed by him; he shall summarily state in his report the condition in which they have been found. Short maturity Bills likely to be accepted, or for which conservation action must be taken shall also be extracted from the seals by the conciliation magistrate, described and remitted to the Receivers for recovery. Statement thereof shall be remitted to the commissioner judge. The other claims shall be recovered by the Receivers against their receipts Letters addressed to the insolvent shall be remitted to the Receivers who shall open them; the insolvent may, if he is present, attend the opening.', 'en', 'Commercial Code (Expanded), Article 530', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '531', 'Article 531 The insolvent may obtain for himself and his family, out of the assets of the insolvency, allowances for food which shall be fixed, on the receivers'' proposal, by the commissioner judge.', 'en', 'Commercial Code (Expanded), Article 531', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '532', 'Article 532 The Receivers shall call the insolvent to come to them to close the books in his presence. If he does not respond to the invitation, he shall be summoned to appear within forty-eight hours, at latest. He may appear by proxy, if he established causes of impediment which the commissioner-judge acknowledges as valid.', 'en', 'Commercial Code (Expanded), Article 532', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '533', 'Article 533 In the event when the balance sheet had not been deposited by the insolvent, the Receivers shall strike it immediately on the evidence of the insolvent''s books and papers as well as on information which they shall procure, and shall deposit it in the Clerk''s office of the Court.', 'en', 'Commercial Code (Expanded), Article 533', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '534', 'Article 534 The commissioner-judge is authorized to hear the insolvent, his clerks and employees and any other person, on the formation of the balance sheet as well as on the causes and circumstances of the insolvency.', 'en', 'Commercial Code (Expanded), Article 534', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '535', 'Article 535 When a tradesman has been declared insolvent after his death, or when the insolvent happens to die after the adjudication of insolvency, his widow, his children, his heirs may present themselves or have themselves represented to stand in his place in the formation of the balance sheet, as well as in all other operations of the insolvency.', 'en', 'Commercial Code (Expanded), Article 535', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '536', 'Article 536 Within three days of the affixing of the seals, or of the adjudication of insolvency whenever such a measure had occurred prior, the Receivers shall request the lifting of the seals and proceed with the stock-taking of the personal chattel of the insolvent, who shall attend or be duly called.', 'en', 'Commercial Code (Expanded), Article 536', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '537', 'Article 537 Stock-taking shall be established in duplicate minute by the Receivers as and when the seals are removed, and in the presence of the conciliation magistrate who shall sign at every sitting. One of these minutes shall be lodged in the Clerk''s office of the Court within 24 hours; the other shall remain in the hands of the Receivers. Receivers are free to have themselves assisted by whomsoever they deem suitable, in the listing as well as the valuation of the objects. Shall be subject to checking those objects which, in conformity with what has been said previously, had been exempted from the seals or had bean extracted therefrom and had already been stocklisted and valued.', 'en', 'Commercial Code (Expanded), Article 537', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '538', 'Article 538 In the event of adjudication of insolvency after death, when no stock-taking has occurred prior to this adjudication, or in the case of the insolvent''s death before the opening of the stock-taking, this shall be immediately proceeded with within the forms of the preceding article and in the presence of the heirs or them who-have been duly called.', 'en', 'Commercial Code (Expanded), Article 538', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '539', 'Article 539 In any insolvency, Receivers are required, within fifteen clear days of their taking office, to remit the commissioner-judge a memo or summary account of the apparent state of the insolvency, of its main causes, circumstances and characters as may outwardly appear. The commissioner-judge shall immediately transmit the memos, with his remarks, to the public prosecutor. If they have to advise the public prosecutor indicating the causes of the delay.', 'en', 'Commercial Code (Expanded), Article 539', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '540', 'Article 540 Officers from the public prosecutor''s office shall be authorized to go to the insolvent''s domicile and attend stock-taking. They shall be entitled at any time to request communication of all the deeds, books or papers relevant to the insolvency.', 'en', 'Commercial Code (Expanded), Article 540', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '541', 'Article 541 At the close of stock-taking, the goods, money, credit claims, books and papers, furniture and the debtor''s personal belongings shall be handed over to the Receivers, who shall take charge thereof at the bottom of the stock-list.', 'en', 'Commercial Code (Expanded), Article 541', 'Banking and credit', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '542', 'Article 542 Dating from their going into office, Receivers are required to transact all acts for the conservation of the insolvent''s rights against his debtors. They shall also be bound to require the inscription of mortgages on the buildings of the insolvent''s debtors, if such inscription has not been requested by him; inscription shall be taken on behalf of the capital stock by the Receivers who shall attach to their statements a certificate proving their appointment. Finally, Receivers shall be bound to take inscription of the forced mortgage of the capital stock, which has been referred to above.', 'en', 'Commercial Code (Expanded), Article 542', 'Mortgage', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '543', 'Article 543 Under the supervision of the commissioner-judge, Receivers shall continue to proceed with the recovery of the asset debts.', 'en', 'Commercial Code (Expanded), Article 543', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '544', 'Article 544 After having heard the insolvent or duly summoned him, the commissioner-judge may authorize the Receivers to proceed with the sale of the movable chattel or merchandise. He shall decide if the sale be made in private or by public auction through the executive office. Having heard the insolvent and after having further requested the advice of the supervisors, if any have been appointed, Receivers may with the same authorization exceptionally proceed with the sale of the buildings, preferably those which are not necessary for the commercial exploitation, such sale to be conducted according to the forms outlined hereinafter for the transfer of immovable after union.', 'en', 'Commercial Code (Expanded), Article 544', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '545', 'Article 545 After subtracting the sums adjudicated by the commissioner-judge for the amount of expenses and charges, proceeds from sales and recoveries shall be immediately paid into a bank duly approved for the receipt of State deposits. Proof of such payments shall be evidenced to the commissioner-judge within three days of the receipt of proceeds; in the event of delay, Receivers shall be held for the interests of those sums they have not paid in. The money paid in by Receivers and all other sums remitted by third parties, for the insolvent''s account, may not be withdrawn except by virtue of an ordinance from the commissioner-judge. Should there be oppositions, the Receivers must obtain prior repletion. The commissioner-judge may ordain that payment shall be made by the bank direct into the hands of the insolvent''s creditors, according to a statement of distribution laid down by the Receiver and ordered by him.', 'en', 'Commercial Code (Expanded), Article 545', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '546', 'Article 546 I With the authorization of the commissioner-judge and after the insolvent has been duly summoned, Receivers may compromise on all disputes regarding capital stock, even those disputes relative to realty rights and actions. If the deal is of an undetermined value or of a value exceeding five hundred pounds, it shall have to be approved by the Court. The insolvent shall be summoned for the approval; he shall in all cases be entitled to oppose it. His opposition will be sufficient to stop the deal, if this involves real estate. Acts of relinquishment, renunciation or acceptance may not be performed by Receivers except on the same conditions. Section 3 - Proof of Liabilities', 'en', 'Commercial Code (Expanded), Article 546', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '547', 'Article 547 Dating from the adjudication of insolvency, creditors may lodge with the Receivers their titles with a statement listing the documents remitted and the sums claimed. The statement is signed by the creditor or by his agent whose power of proxy must be attached. Receivers give a receipt of the dossier of the documents produced; this dossier may be addressed to them by registered mail, with acknowledgement of receipt. After the meeting for the scheme of arrangement, Receivers return the documents which have been entrusted to them; they are liable for the titles for one year only dating from this meeting.', 'en', 'Commercial Code (Expanded), Article 547', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '548', 'Article 548 Creditors entered on the balance sheet who have not produced their claims within eight days of the adjudication of insolvency are, on the expiry of this time-limit, advised by insertions in newspapers or by letters from the Receivers that they are to submit their titles and the relevant statement to the Receivers within fifteen clear days of such insertions. As regards creditors domiciled outside Lebanon, this time-limit is increased according to the rules set down in the code of civil procedure under the heading of adjournments.', 'en', 'Commercial Code (Expanded), Article 548', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '549', 'Article 549 The verification of the claims is made by the Receivers assisted by the supervisors of the insolvency if any have been appointed, subject to the rectification of the commissioner-judge and in the presence of the debtor who has been duly summoned. If the claim is discussed as a whole or in part by the Receivers, the latter notify the creditor thereof by registered letter. The creditor will be given 10 days to provide written or oral explanations.', 'en', 'Commercial Code (Expanded), Article 549', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '550', 'Article 550 Soon after the ending of verification or at the latest within three months of the adjudication of insolvency, Receivers deposit in the Clerk''s office a statement of the debts which they have had to check, with indication of the decision taken by the commissioner-judge on the proposals made by them in connection with each one of them. The Clerk shall immediately advise the creditors of the deposit of this statement by insertions in newspapers; in addition, he shall send them a letter indicating for each of them the sum for which his claim has been entered. In absolutely exceptional circumstances, it may be possible to derogate to the time-limit fixed by the first sub-paragraph by decision of the commissioner-judge.', 'en', 'Commercial Code (Expanded), Article 550', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '551', 'Article 551 Any creditor duly checked or listed in the balance sheet is authorized within eight days of the insertions referred to in the preceding article to formula-, to corrections or complaints to the Court Clerk, either by himself or through an agent, which are annotated on the statement. The insolvent shall have the same right. At the expiry of this time-limit, the commissioner-judge, according to the proposals which have been made by the Receivers and without prejudice to the corrections and complaints submitted to the Court, closes definitely the statement of the debts, and the Receivers give effects to his decision by signing on the statement of the produced uncontested documents the following declaration : "on my affidavit, Mr. or the company... is admitted as creditor (unsecured, preferential or mortgagee) in the liabilities of the insolvency, j for the sum of...".', 'en', 'Commercial Code (Expanded), Article 551', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '552', 'Article 552 Contested debts are referred by the Court Clerk to a session of the commercial court within thirty days dating from the insertions referred to in article 550 to be judged on the evidence of the commissioner-judge''s report. Indication of the session shall be given to the parties by registered letter from the Clerk at feast three days in advance.', 'en', 'Commercial Code (Expanded), Article 552', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '553', 'Article 553 The Court shall provisionally decide that the creditor shall be admitted to the deliberations for a sum which the same ruling shall determine. This ruling shall be open to no recourse.', 'en', 'Commercial Code (Expanded), Article 553', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '554', 'Article 554 The creditor, whose preference or mortgage only is contested, shall be admitted to the deliberations of the insolvency, as an ordinary creditor.', 'en', 'Commercial Code (Expanded), Article 554', 'Mortgage', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '555', 'Article 555 If they fail to appear and to produce (the documents) within the time-limits applicable to them, defaulters known and unknown shall not be comprised in the distribution; however recourse to appeal shall be open to them until the money distribution inclusively; the appeal charges shall always be borne by them. Their opposition may not suspend the distribution ordained by the commissioner-judge; but if new allotments occur before their opposition has been dealt with,-they shall be comprised for the sum which shall be provisionally determined by the Court and which shall be held over as reserve until adjudication on their opposition. If they are subsequently acknowledged as creditors, they shall not be authorized to claim anything from the allotments ordinanced by the commissioner-judge; but they shall be entitled to draw against the assets as yet undistributed the dividends relating to their claims in the first allotments.', 'en', 'Commercial Code (Expanded), Article 555', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '556', 'Article 556 Debentures issued according to regulations by a trading company shall not be subject to this verification procedure. CHAPTER 4 - Solutions to insolvency Section 1 - Simple Scheme of Arrangement', 'en', 'Commercial Code (Expanded), Article 556', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '557', 'Article 557 Within three days of the closing of the statement of debts or, in the event of dispute, within three days of the Court ruling in application of article 553, the commissioner-judge shall have the Clerk summon the creditors whose claims have been received in order to deliberate on the formation of the scheme of arrangement. The insertions in newspapers and the letters convening them shall indicate the purpose of the meeting. The provisionally admitted creditors shall be advised individually by registered letter within three days of the decision taken by the Court in their respect.', 'en', 'Commercial Code (Expanded), Article 557', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '558', 'Article 558 At the place, date and hour which shall be fixed by the commissioner-judge, the meeting shall be held under his chairmanship; the creditors admitted definitively or provisionally shall attend there in person or by proxy. The insolvent shall be summoned to this meeting; he shall be required to attend in person and may not be represented there except for valid reasons duly approved by the commissioner-judge.', 'en', 'Commercial Code (Expanded), Article 558', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '559', 'Article 559 The Receivers shall report to the meeting on the state of the insolvency, on the formalities that shall have to be fulfilled and the operation that will have taken place; the insolvent shall be given a hearing. The Receiver''s report will be remitted, duly signed by them, to the commissioner-judge who shall draft the proces-verbal of what has been said and decided in the meeting.', 'en', 'Commercial Code (Expanded), Article 559', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '560', 'Article 560 Subject to nullity, the scheme of arrangement subsequent to insolvency may not be accepted by the deliberating creditors except if the following conditions have been met. The scheme shall not be established except by the vote of a number of creditors forming the majority and representing, on the other hand, two thirds of the amount of the debts definitively admitted or admitted provisionally, in accordance with section 3 of chapter 3. However the claims of those who have not taken part in the vote shall be deducted for the assessment of majorities in relation to number and sums. Shall be excluded from the vote the debtor''s spouse, his family relations and relations by marriage up to the fourth degree as well as their transferees within the framework of the conditions laid down under the heading of scheme of arrangement.', 'en', 'Commercial Code (Expanded), Article 560', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '561', 'Article 561 Mortgagees, pledgees and preferential creditors shall be entitled to the vote except if they relinquish their sureties, according to the conditions laid down under the heading of the scheme of arrangement.', 'en', 'Commercial Code (Expanded), Article 561', 'Electoral', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '562', 'Article 562 The scheme of arrangement shall be, subject to nullity, signed on the spot. If it is accepted only by a number majority or a majority of two-thirds of the sum, deliberation shall be continued within eight days, at the latest. In this event, the creditors attending or legally represented having signed the proces-verbal of the first meeting, shall not be bound to attend the second meeting; the resolutions they have taken and the adherence they have given remain definitively acquired if they have not come to modify them in this last meeting. The creditors'' signature in the meetings may be replaced by a signature on a ballot-paper which is annexed to the proces-verbal', 'en', 'Commercial Code (Expanded), Article 562', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '563', 'Article 563 If the insolvent has been convicted for fraudulent bankruptcy, the scheme of arrangement may not be formed. When a preliminary investigation for fraudulent bankruptcy has been initiated, the creditors shall be convened to decide if they reserve themselves (the right) to discuss a scheme of arrangement, in case of discharge, and if, in consequence, they put off their decision, until after the end of the proceedings. This delay may not be pronounced except by the majority of number and sums determined above. If, at the expiry of the delay, there is a case for deliberating a scheme of arrangement, the rules laid down by the preceding article shall apply to the new deliberations.', 'en', 'Commercial Code (Expanded), Article 563', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '564', 'Article 564 If the insolvent has been convicted as simple bankrupt the scheme of arrangement may be formed. Nevertheless, if proceedings have been initiated, the creditors may postpone deliberations until after the end of the proceedings, conforming themselves to the provisions of the preceding article.', 'en', 'Commercial Code (Expanded), Article 564', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '565', 'Article 565 If the case concerns a trading company having issued debentures, the scheme of arrangement may not be granted except if it is approved by the meeting of debenture-holders, having expressed their opinion in the case and according to the conditions specified under the heading of the scheme of arrangement.', 'en', 'Commercial Code (Expanded), Article 565', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '566', 'Article 566 All the creditors who have been given right to join in the scheme or whose title has been acknowledged since, as well as the representatives of the debenture-holders group, if any, may oppose the scheme. Subject to nullity, opposition shall be motivated and notified to the Receiver and the insolvent, within eight days dating from the scheme of arrangement or the meeting of the debentures-holders; it shall include a writ of summons to the first session of the Court. If only one Receiver has been appointed and if he joins the contestants of the scheme, he will be required to call for the appointment of a new Receiver towards whom he shall have to fill the forms prescribed in the present article.', 'en', 'Commercial Code (Expanded), Article 566', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '567', 'Article 567 Approval of the scheme of arrangement shall be pursued before the Court, at the request of the most diligent party, but the Court shall not adjudicate before the expiry of eight days as laid down in the preceding article. If oppositions have taken shape during this period, the Court shall adjudicate on these oppositions and on the confirmation in one and the same ruling. If opposition is entertained, cancellation of the scheme of arrangement shall be pronounced in relation to all the parties ''concerned.', 'en', 'Commercial Code (Expanded), Article 567', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '568', 'Article 568 In all cases, before judgement is passed on the confirmation, the commissioner-judge shall report to the Court on the characters of the insolvency and the admissibility of the scheme of arrangement.', 'en', 'Commercial Code (Expanded), Article 568', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '569', 'Article 569 If the aforementioned rules are not-observed, or when the motives stemming from public interest or from the creditors'' interest shall appear likely to prevent the scheme of arrangement, the Court shall refuse its confirmation. It shall likewise be allowed to refuse confirmation of the scheme if the latter does not embody a clause providing for the appointment by the Court president of one or several trustees intended to supervise its execution, to lift the mortgage on the capital stock, if the creditors have so authorized him, and to supervise the selling of the assets.', 'en', 'Commercial Code (Expanded), Article 569', 'Mortgage', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '570', 'Article 570 The confirmation of the scheme of arrangement shall render it compulsory upon all creditors whether listed or not listed on the balance sheet, checked or not checked, and even on those creditors domiciled outside the Lebanese territory, as well as on those who had provisionally been admitted to deliberate, whatever the sum which the Court might subsequently allot them., . But the scheme of arrangement shall be no bar to mortgagees and preferential creditors who have not relinquished their surety, nor to unsecured creditors whose claim was born in the course of the insolvency.', 'en', 'Commercial Code (Expanded), Article 570', 'Guarantees and sureties', 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-001-EXPANDED', '571', 'Article 571 As soon as the verdict of approval has gained power of enforcement, the effects of the insolvency shall cease, without prejudice to those civic forfeitures referred to in article 500. The Receivers, whose functions come to an end, shall give final account to the insolvent in the presence of the commissioner-judge; this account shall be debated and closed. They shall remit the insolvent all his goods, books, papers and personal belongings. Discharge therefor shall be given by the insolvent. A comprehensive report shall be drafted by the commissioner-judge whose duties shall cease. In the event of disputed matters, the Court shall adjudicate.', 'en', 'Commercial Code (Expanded), Article 571', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '572', 'Article 572 The scheme of arrangement implies time-limits for the payment of debts, which shall be staggered over successive installments. Likewise, it generally involves rebates to the debtor amounting to a more or less substantial portion of his liabilities, though such rebates leave behind them a natural obligation. The scheme of arrangement may be granted only conditionally pending the return to better fortunes, according to the conditions laid down under the title of composition.', 'en', 'Commercial Code (Expanded), Article 572', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '573', 'Article 573 Mortgage of the capital stock remains for the settlement of the dividend under the scheme of arrangement.', 'en', 'Commercial Code (Expanded), Article 573', 'Mortgage', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '574', 'Article 574 Creditors can further demand that the execution of the scheme is guaranteed by one or several sureties.', 'en', 'Commercial Code (Expanded), Article 574', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '575', 'Article 575 So long as the dividend under the scheme of arrangement has not been paid, the debtor shall not be entitled to perform acts of abnormal disposal and unrequired for the very operation of the trade, unless otherwise provided in accordance with the rules set down in this respect under the title of composition.', 'en', 'Commercial Code (Expanded), Article 575', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '576', 'Article 576 No proceedings in nullity of the scheme of arrangement shall be receivable subsequently to the approval, except for a fraud uncovered after this approval and resulting either from the concealments of the assets or the feather-bedding of the liabilities. Such proceedings may be initiated by any of the creditors, but only within the five years following the uncovering of the fraud. The scheme of arrangement shall be equally cancelled following the condemnation of the insolvent for fraudulent bankruptcy. Cancellation of the scheme of arrangement releases the sureties not accomplices to the fraud.', 'en', 'Commercial Code (Expanded), Article 576', 'Fraud', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '577', 'Article 577 When, after the confirmation of the scheme of arrangement, the insolvent is sued for fraudulent bankruptcy and placed under a warrant of deposit or arrest, the Court may prescribe such measures of conservation as it deems necessary. These measures shall cease, as a matter of right, on the day of the declaration that there is no case for proceedings, or adjudication of dis charge, or absolution.', 'en', 'Commercial Code (Expanded), Article 577', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '578', 'Article 578 Upon the failure of the insolvent to execute the conditions of the scheme of arrangement, the annulment of the scheme may be proceeded with against him before the Court, in the presence of the sureties, who would be duly summo ned, if any exist.', 'en', 'Commercial Code (Expanded), Article 578', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '579', 'Article 579 On sight of the conviction judgment for fraudulent bankruptcy, or by the ruling which shall pronounce cancellation, or the annulment of the scheme of arrangement, the Court shall appoint a commissioner-judge and one or several Receivers. These Receivers may have the seals affixed. They shall proceed without delay, with the assistance of the conciliation magistrate, on the old stock-taking, with the re-examination of the valuables arid papers, and proceed, if the case so requires, with the fisting of a supplementary stock-taking. They shall equally strike a supplementary balance sheet. They shall immediately put up on billposts and insert in appropriate newspapers, alongside an abstract of the ruling appointing them, an invitation to the new creditors, if any exist, to produce within fifteen clear days their titles to claims for verification. Such verification is affected in the manner provided in section 3 of chapter 3.', 'en', 'Commercial Code (Expanded), Article 579', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '580', 'Article 580 Verification of the titles to claims duly produced in accordance with the preceding article shall be proceeded with without delay. It shall not be deemed necessary to undertake a fresh verification of the claims previously received and confirmed without prejudice however to the rejection or reduction of those which since then had been paid totally or partially.', 'en', 'Commercial Code (Expanded), Article 580', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '581', 'Article 581 on the termination of these operations, if no fresh scheme of arrangement intervenes, the creditors shall be convened to voice their opinion on whether the Receivers should be maintained or replaced.', 'en', 'Commercial Code (Expanded), Article 581', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '582', 'Article 582 Acts performed by the insolvent subsequently to the ruling of approval and prior. to the cancellation or annulment of the scheme of arrangement shall not be void except in the event of fraud relative to the rights of the creditors.', 'en', 'Commercial Code (Expanded), Article 582', 'Fraud', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '583', 'Article 583 Creditors prior to the scheme of arrangement shall recover their rights in full in respect of the insolvent only, but they may not figure in the capital stock, except for the following proportions, namely : if they have received no share in the dividend, for the whole of their claims; if they have received part of the dividend, for the portion of their original claims corresponding to that portion of the promised dividend which they have not cashed. The provisions of the present article shall be enforced in the event of a second insolvency occurring without prior cancellation or annulment of the scheme of arrangement. Section 2 - Union', 'en', 'Commercial Code (Expanded), Article 583', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '584', 'Article 584 When no scheme for arrangement has been reached, the creditors shall be in a state of union, as a matter of right. The commissioner-judge shall immediately consult them as much on the facts of management as on the utility of maintaining or replacing the Receivers. Pledges, mortgagees and preferential creditors shall be admitted to this deliberation. A proces-verbal shall be drafted on the saying and observations of the creditors, and on sight of this document, the Court shall appoint the Receivers of the union. The Receivers who were not returned shall have to give account to the new Receivers in the presence of the commissioner-judge, the insolvent having been duly summoned.', 'en', 'Commercial Code (Expanded), Article 584', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '585', 'Article 585 The creditors shall be consulted on whether assistance may be extended to the insolvent out of the assets of the insolvency. When the majority of the attending creditors have consented, a sum may be granted to the insolvent by way of assistance out of the assets of the insolvency. The Receivers shall propose the portion, which shall be fixed by the commissioner-judge, except for an appeal in Court from the Receivers only.', 'en', 'Commercial Code (Expanded), Article 585', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '586', 'Article 586 When a partnership is in insolvency, the creditors shall be entitled to grant a scheme of arrangement in favor of one or several of the partners. In this event, all the assets of the partnership shall remain under the union regime. The personal chattel of those with whom the scheme has been granted shall be excluded, and the individual agreement concluded with them may not contain an undertaking to pay a dividend except on the assets foreign to the partnership assets. The partner who has obtained an individual scheme of arrangement shall be discharged of every solidarity.', 'en', 'Commercial Code (Expanded), Article 586', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '587', 'Article 587 The Receivers represent the bulk of creditors and are charged to proceed with liquidation. However the creditors may give proxy for the continuation of the exploitation of the assets. The deliberation which shall confer this proxy shall determine its duration and extent, as well as the sums which they shall be entitled to retain in their hands for the purpose of meeting expenses and charges. It may not be taken except in the presence of the commissioner-judge and at a three-quarters majority of the creditors in both number and sums. Recourse to opposition shall be open against this deliberation to the insolvent and the dissenting creditors. This opposition shall not suspend execution.', 'en', 'Commercial Code (Expanded), Article 587', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '588', 'Article 588 When the Receivers'' operations shall entail commitments in excess of the assets of the union, only the creditors who have authorized these operations shall be personally held beyond their share in the assets, but merely within the limits of the proxy they have given; they shall contribute at the prorate of their claims.', 'en', 'Commercial Code (Expanded), Article 588', 'Agency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '589', 'Article 589 The Receivers shall proceed with the recoveries which have not yet been effected. They shall be authorized to consent transactions along the same conditions as in the previous period, notwithstanding opposition from the insolvent. Regarding lump agreements, the creditors are required to deliberate thereon in the course of a meeting convened by the commissioner-judge, on the-request of the Receiver or any other creditor, and the Court shall have to grant ,au-, to the Receivers.', 'en', 'Commercial Code (Expanded), Article 589', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '590', 'Article 590 Receivers must proceed with the sale of movable property of every nature, including the stock-intrade, under the commissioner-judge''s supervision and without it being necessary to call the insolvent, in accordance with the forms prescribed for the sale of movables during the preparatory period.', 'en', 'Commercial Code (Expanded), Article 590', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '591', 'Article 591 If no proceedings for expropriation have been initiated before the period of the union, the Receivers alone shall be admitted to proceed with the sale; they shall be bound to proceed with it within eight days, subject to the authorization of the commissioner-judge and through the care of the executive office of the state of the assets.', 'en', 'Commercial Code (Expanded), Article 591', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '592', 'Article 592 The Receivers shall compile the specifications on which tenders shall be invited. This deed shall contain the indications referred to in', 'en', 'Commercial Code (Expanded), Article 592', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '744', 'article 744 of the code of civil procedure. Shall further be applied to the sale, in so far as their provisions are not excluded by the nature of this procedure, articles 746, 747 (1st paragraph), 753 to ?61, 763 to 767, 778 to 792 of the code of civil procedure. The tender shall be self-operative; it shall purge all preferences and mortgages.', 'en', 'Commercial Code (Expanded), Article 744', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '593', 'Article 593 The creditors in a state of union shall be convened at least once in the first year, and, if need be in the following years, by the commissioner-judge. In the course of these meetings the Receivers shall be required to account for their management.', 'en', 'Commercial Code (Expanded), Article 593', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '594', 'Article 594 The amount of the assets, after deduction of the charges and expenses for the management of the insolvency, the assistance that might have been granted to the insolvent and his family and the sums paid over to the preferential creditors shall be apportioned among all the creditors at so many piastres per pound of their verified claims.', 'en', 'Commercial Code (Expanded), Article 594', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '595', 'Article 595 To this effect the Receivers shall remit to the commissioner-judge a monthly statement on the situation of the insolvency and of the money deposited with the bank approved for the reception of State deposits; the commissioner-judge shall ordain,. if need be, an apportionment among the creditors, fix the portion therefor and see to it that all the creditors are advised.', 'en', 'Commercial Code (Expanded), Article 595', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '596', 'Article 596 No payment shall be made by the Receivers except on the representation of the. The Receivers shall mention on the title the sum paid or ordinanced by them. However, should it be impossible to represent the title, the commissioner-judge may authorize payment on sight of the proces-verbal of verification. In all cases, the creditor shall give discharge on the margin of the statement of apportionment.', 'en', 'Commercial Code (Expanded), Article 596', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '597', 'Article 597 When the liquidation of the insolvency has been terminated, the creditors shall be convened by the commissioner-judge. In this last meeting, the Receivers shall render account. The insolvent shall attend or be duly summoned. The creditors shall give their opinion on whether the bankrupt is to be excused. A proces -verbal shall be drafted to this effect, in which every creditor shall be authorized to put down what he has to say and his remarks. Before the closing of this meeting, the union shall be dissolved as a matter of course.', 'en', 'Commercial Code (Expanded), Article 597', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '598', 'Article 598 The commissioner-judge shall table before the ,Court the deliberation of the creditors relative to the insolvent''s grounds for excuse and a report on the characters and the circumstances of the insolvency. The Court shall adjudicate on whether or not the insolvent is excusable.', 'en', 'Commercial Code (Expanded), Article 598', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '599', 'Article 599 May not be declared excusable fraudulent bankrupts, persons convicted for forgery, theft, swindling or breach of trust, and the accountants of public funds. Section 3 - Scheme of arrangement due to relinquishment of assets', 'en', 'Commercial Code (Expanded), Article 599', 'Theft and robbery', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '600', 'Article 600 A scheme of arrangement may be granted for total or partial relinquishment of the insolvent''s assets. Conditions for the formation of this scheme are the same as those prescribed for the simple scheme of arrangement. However, this scheme does not put an end to relinquishment in what concerns the abandoned chattel; such chattel is sold through the good offices of Receivers appointed in like manner as Receivers for the union. Sales and the apportionment of cash are submitted to the same rules as govern the case of union. An abatement is allowed to the debtor over what is in excess. of his liabilities as against the proceeds of the sale of the relinquished assets. Section 4 -Closure for insufficient assets', 'en', 'Commercial Code (Expanded), Article 600', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '601', 'Article 601 If, at any time whatsoever, before the confirmation of the scheme of arrangement or the formation of the union, the course of the insolvency operations comes to a standstill due to short assets, the Court may, in the light of the commissioner-judge''s report, pronounce, even officially, the closure of the insolvency operations. This ruling shall restore every creditor to the performance of his individual actions.', 'en', 'Commercial Code (Expanded), Article 601', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '602', 'Article 602 The insolvent or any other interested party may, at any time, have it rescinded by the Court, by proving that sufficient funds exist to meet the operational charges of the insolvency, or by consigning to the Receivers an adequate sum to provide thereto. In all cases, charges for proceedings exercised by virtue of the preceding article shall be settled beforehand. CHAPTER 5 - Special rights that may be advocated against the insolvency Section 1 - Creditors with several co-debtors', 'en', 'Commercial Code (Expanded), Article 602', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '603', 'Article 603 The creditor holding an undertaking by the insolvent and other joint obligees who are insolvent, shall participate in the distribution of all the capital stocks, and shall be entered therein for the nominal value of his title until full payment.', 'en', 'Commercial Code (Expanded), Article 603', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '604', 'Article 604 No recourse by reason of paid dividends is open to insolvencies of joint obligees the ones against the others, except when the amalgamation of the dividends that would be yielded by these insolvencies would exceed the total of the claim, in principal and accessories, in which case such excess shall revert, according to the rotation order of the undertakings, to those joint obligees who would have the others as guarantors.', 'en', 'Commercial Code (Expanded), Article 604', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '605', 'Article 605 If the creditor holding joint undertakings between the insolvent and other joint-obligees has received, before the insolvency, a first payment against his claim, he shall be included in the capital stock only after deduction of this first payment, and shall retain, in respect of what shall remain due, his rights against the joint obligee or the surety. The joint obligee or the surety who shall have effected the partial payment shall be included in the same capital stock for that all he has paid in dis charge of the insolvent.', 'en', 'Commercial Code (Expanded), Article 605', 'Guarantees and sureties', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '606', 'Article 606 Notwithstanding the scheme of arrangement, the creditors shall retain their action for the total of their claims against all the co-obligees of the bankrupt, who are entitled to intervene in the proceedings for the approval of the scheme of arrangement, so that they may put forward their remarks. Section 2 - Recovery and retaining', 'en', 'Commercial Code (Expanded), Article 606', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '607', 'Article 607 Third Parties, claiming to be the owners of chattel in the insolvent''s possession, shall assert their right. The Receivers may, with the approval of the commissioner-judge, receive petitions for recovery. In case of a dispute the Court shall adjudicate after having heard the commissioner-judge.', 'en', 'Commercial Code (Expanded), Article 607', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '608', 'Article 608 May be notably claimed remittances in trade Bills and other unpaid titles which shall be found in kind in the bankrupt''s portfolio at the time of the opening of his insolvency, when such remittances have been made by the owner with the simple mandate that they should be recovered and their value kept at his disposal, or when they have been specifically earmarked by him for determined payments. Equally subject to claiming are the banknotes deposited with the insolvent, if the depositor is in a position to identify them.', 'en', 'Commercial Code (Expanded), Article 608', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '609', 'Article 609 Also subject to claiming, so long as they exist-in kind, wholly or partially, the goods consigned with the insolvent by way of deposit or for subsequent sale on the owner''s behalf. Even the price or portion of the price for such goods which has been neither paid nor compensated into current account between the bankrupt and the buyer, may be claimed.', 'en', 'Commercial Code (Expanded), Article 609', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '610', 'Article 610 May be retained by the seller the goods and other movable chattel, sold by him, which have not been delivered to the insolvent or which have not yet been dispatched, either to him or to a Third Party for his account.', 'en', 'Commercial Code (Expanded), Article 610', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '611', 'Article 611 In order to exercise his right of retaining, the seller may regain the possession of goods dispatched to the insolvent, so long as they have not been delivered to the latter''s stores or in a place which he apparently could dispose of, or in the stores of a commissioner instructed to sell them for the bankrupt''s account. But the seller shall not be admitted to take action, if the goods, before their arrival, have been re-sold without fraud to a sub-acquirer in good faith.', 'en', 'Commercial Code (Expanded), Article 611', 'Fraud', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '612', 'Article 612 If the buyer has taken possession of the goods before his insolvency, the seller may not initiate proceedings for cancellation of the sale, neither for recovery, nor for preference.', 'en', 'Commercial Code (Expanded), Article 612', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '613', 'Article 613 In cases where the seller is entitled to exercise his right of retaining, the Receivers, duly authorized by the commissioner-judge, shall have the power to demand the delivery of the goods by paying the agreed price to the seller.', 'en', 'Commercial Code (Expanded), Article 613', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '614', 'Article 614 If the Receivers do not take this decision, the seller may have the sale cancelled and shall refund into the capital stock all the partial payments he has received. He may obtain damages on the ground of prejudice which could be caused him through the non execution of the sale and produce therefor in the unsecured capital stock.', 'en', 'Commercial Code (Expanded), Article 614', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '615', 'Article 615 Recovery rights of the bankrupt''s wife shall be within the limits of the rules laid down hereinafter. Section 3 - Pledgees and preferential creditors over movables', 'en', 'Commercial Code (Expanded), Article 615', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '616', 'Article 616 The insolvent''s pledgee creditors as well as all those who have a special preference over movables, shall not be inscribed in the capital stock except for recollection.', 'en', 'Commercial Code (Expanded), Article 616', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '617', 'Article 617 The Receivers may, at any time, with the commissioner-judge''s authorization, withdraw the pledge in favor of the insolvency, by repaying the debt.', 'en', 'Commercial Code (Expanded), Article 617', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '618', 'Article 618 In the event when the pledge has not been withdrawn by the Receivers, if it is sold by the creditor for a price which is in excess of the debt, the surplus shall be recovered by the Receivers. If the price is less than the debt, the pledgee shall be put to contribution, for the surplus, in the capital stock as ordinary creditor.', 'en', 'Commercial Code (Expanded), Article 618', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '619', 'Article 619 The Receivers shall suhnnit to the commissioner-judge a statement of the creditors claiming a preference over the movable chattel, aid the commissioner-judge shall authorize, if need be, payment of these debts out of the first revenue. If the preference is contested, the Court shall adjudicate. Section 4 - Mortgagees and preferential creditors over immovable property', 'en', 'Commercial Code (Expanded), Article 619', 'Property law', 'Commercial Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-COM-001-EXPANDED', '620', 'Article 620 When the distribution of the price of immovables has been made prior to that of the price of movable chattel, or simultaneously, the preferential creditors and mortgagees not settled out of the price of the immovable property shall compete proportionately to what is left owing them with the unsecured creditors, for the money belonging to the unsecured capital stock, provided however that their claims have been verified according to the forms laid down above.', 'en', 'Commercial Code (Expanded), Article 620', 'Property law', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '621', 'Article 621 If one or several distributions of the money of movables precede the distribution of the price of immovable property, the verified preferential creditors and mortgagees shall compete in the allotment proportionately to their total claims, excepting, eventually, for diversions that shall be dealt with hereinafter.', 'en', 'Commercial Code (Expanded), Article 621', 'Property law', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '622', 'Article 622 After the sale of the immovable property and the final settlement of the order between the mortgagees and preferential creditors, those among them who shall come in subsequent order against the price of the immovable property for the whole of their claim shall not receive the amount of their mortgagee rank except after the subtraction of the sums they have received out of the unsecured capital stock. The sums thus deducted shall not remain in the mortgagee capital stock, but shall revert to the unsecured capital stock for the benefit of which diversion shall be made.', 'en', 'Commercial Code (Expanded), Article 622', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '623', 'Article 623 Concerning the mortgagee creditors who are in partial collocation in the distribution of the price of the immovable property, it shall be proceeded as follows : their rights over the unsecured capital stock shall be definitively settled according to the sums for which they shall remain creditors after their collocation in the immovable property, and the money they shall have received in excess of this proportion in the prior distribution, shall be deducted out of the amount of their mortgagee collocation and reversed into the unsecured capital stock.', 'en', 'Commercial Code (Expanded), Article 623', 'Property law', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '624', 'Article 624 The creditors who are not set in useful order shall be considered as unsecured and submitted, as such, to the effects of the scheme of arrangement and of all the operations of the unsecured capital stock. Section 5 -.Rights of the insolvent''s wife', 'en', 'Commercial Code (Expanded), Article 624', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '625', 'Article 625 In the event of the husband''s insolvency, the wife shall recover in kind the immovable and movable property which she shall prove to have been her own before marriage, as well as those which have gratuitously reverted to her in the course of marriage. It shall equally be so in respect of the chattel she acquired in the course of marriage by the use of money according to the conditions indicated above, provided that the declaration of use is expressly stipulated in the contract of acquisition and that the wife proves the origin of the money.', 'en', 'Commercial Code (Expanded), Article 625', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '626', 'Article 626 j Outside the hypothesis outlined in the second paragraph of the preceding article, the chattel acquired by the wife in the course of marriage, for a money consideration, shall be presumed paid out of the husband''s money; they must be lumped to the insolvent''s asset capital stock, except when the wife can furnish proof to the contrary. Article 62? If the wife has paid debts for her husband, the legal presumption is that she did so with the latter''s money and as a consequence she shall not be entitled to exercise any action in the insolvency, except for proof to the contrary.', 'en', 'Commercial Code (Expanded), Article 626', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '6213', 'Article 6213 When the husband is a trader at the time of the wedding ceremony, or when having no determined profession at the time, he has become a trader in the course of the year, the immovable property which belonged to him at the time of the wedding ceremony, or which intervened since, either through inheritance, or through donation between testamentary or persons living, shall solely be subject to the wife''s mortgage.', 'en', 'Commercial Code (Expanded), Article 6213', 'Mortgage', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '629', 'Article 629 The wife whose husband was a trader at the time of the wedding ceremony, or whose husband, having then no other determined profession, has become a trader in the course of the year following this ceremony, shall not be entitled to exercise in the insolvency any action by reason of the advantages laid down in the marriage settlement, and in this event the creditors shall not be able, in what concerns them, to avail themselves of the advantages made by the wife to her husband in this same settlement. Donations made in the course of marriage are equally void. TITLE III - SUMMARY PROCEDURE', 'en', 'Commercial Code (Expanded), Article 629', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '630', 'Article 630 If as a result of the balance sheet tabled by the insolvent or of subsequent information it is shown that the assets of the insolvency are not in excess of two thousand five hundred Lebanese Pounds, or if the dividend to be distributed does not appear to be over ten per cent, the Court may, either on its own initiative, or at the request of the creditors, ordain that the operations of the insolvency shall run their course in accordance with the procedure said to be summary.', 'en', 'Commercial Code (Expanded), Article 630', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '631', 'Article 631 Summary procedure differs from the ordinary procedure of insolvency by the following particularities 1 - The time-limit of document presentation, opposition, appeal and other procedural time-limits set down in articles 49?, 512, 548, 556 and 579 of the present code are reduced by half. If the time-limit is fifteen clear days, it is reduced to sight days. The increase of the time-limit provided under article 548 in favor of creditors domiciled outside the Lebanese territory is subject to no reduction; 2 - The affixing of seals does not occur; 3 - Supervisors are not appointed; 4 - Disputes on claims are solved by the commissioner-judge, except for appeal, if any, before the Court; 5 - All transactions may be authorized by the commissioner-judge; b - Only one apportionment of the money takes place; ? -Disputes relative to the Receiver''s accounts and his fees are solved by the commissioner-judge. TITLE IV - BANKRUPTCIES', 'en', 'Commercial Code (Expanded), Article 631', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '632', 'Article 632 Cases of simple bankruptcies shall be tried by the Courts of Misdemeanor Police, following proceedings from the Receivers, the creditors or the public prosecutor, and punished by a term of imprisonment from one month to a year subject to extenuating circumstances.', 'en', 'Commercial Code (Expanded), Article 632', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '633', 'Article 633 Shall be declared simple bankrupt, any failing trader who shall find himself in one of the following cases 1- If his personal expenses or the expenses of his house are deemed excessive; 2- If he has used up large sums either in operations of sheer chance, or in fictitious Exchange operations or in commo dities; 3- If, subsequently to the period of suspension of payment and with intent to delay his insolvency, he made purchases for underselling; if, with the same intent, he resorted to loans, circulations of Bills, or other ruinous means to secure funds; 4- If, after suspension of his payments, he paid a creditor to the prejudice of the capital stock.', 'en', 'Commercial Code (Expanded), Article 633', 'Sale of goods', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '634', 'Article 634 May be declared simple bankrupt, any failing trader who shall find himself in one of the following situations 1- If he has contracted for the account of another, without receiving values in exchange, commitments deemed too considerable by comparison with his situation when he contracted them; 2- If he is adjudicated once more insolvent without having honored commitments from a previous scheme of arrangement; 3- If he has failed to conform to obligations relative to the trade regis ter; 4- If within twenty days of his suspension of payments he has not made in the Clerk''s office the declaration required by the present code, or if this declaration does not contain the names of all the jointly liable partners; 5- If he has not kept books and taken correct stock; if these books or stock-takings are incomplete or irregularly kept, or if they do not reflect the true position of his liabilities and assets, though there is no fraud.', 'en', 'Commercial Code (Expanded), Article 634', 'Fraud', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '635', 'Article 635 Charges for proceedings in simple bankruptcy initiated by the public prosecutor may in no case be debited to the capital stock. In the event of a scheme of arrangement, recourse by the Public Treasury against the insolvent may not be exercised except after expiry of the terms granted by this agreement.', 'en', 'Commercial Code (Expanded), Article 635', 'Contracts and obligations', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '636', 'Article 636 Charges of proceedings brought by the Receivers in the name of creditors, shall be borne, in case of a discharge, by the capital stock, and if a conviction ensues, by the Public Treasury, except for its recourse against the insolvent, in conformity with the preceding article.', 'en', 'Commercial Code (Expanded), Article 636', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '637', 'Article 637 The Receivers may not bring proceedings in simple bankruptcy, nor stand civil party to the case in the name of the capital stock, except after having been authorized by a deliberation taken by the individual majority of the attending creditors.', 'en', 'Commercial Code (Expanded), Article 637', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '638', 'Article 638 Charges for proceedings moved by a creditor shall be borne, in the event of a conviction, by the Public Treasury; if there is discharge, by the proceeding creditor.', 'en', 'Commercial Code (Expanded), Article 638', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '639', 'Article 639 (as modified by the Law of 30 September 1944) Shall be declared fraudulent bankrupt and submitted to the penalties provided for fraudulent bankruptcy, any insolvent trader who has abstracted books, embezzled or concealed part of his assets or who, either in his writings, or by public acts or by commitments under private signature, or by his balance sheet, shall have acknowledged himself fraudulently debtor of sums that he did not owe.', 'en', 'Commercial Code (Expanded), Article 639', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '640', 'Article 640 Charges for proceedings in fraudulent bankruptcy may not, in any case, be expensed on the capital stock. If one or several creditors have stood civil parties in their personal name, the expenses, in case of discharge, shall remain on his charge.', 'en', 'Commercial Code (Expanded), Article 640', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '641', 'Article 641 Shall be condemned to the penalties of fraudulent bankruptcy 1- Individuals convicted of having in the interest of the insolvent, abstracted, received or concealed all or part of his movable or immovable chattel, this being without prejudice to other cases of complicity provided by the penal code; 2- Individuals convicted of having fraudulently presented in the insolvency and asserted, either in their name or by the intervention of persons, supposed claims; 3- Individuals who, carrying on trade under the name of another or a supposed name, have rendered themselves guilty of facts of fraudulent bankruptcy.', 'en', 'Commercial Code (Expanded), Article 641', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '642', 'Article 642 The spouse, the descendants or ascendants of the insolvent, or his relations by marriage in the same degree, who would have embezzled, diverted or received Bills belonging to the insolvency, without having acted as accomplice to the insolvent, shall be subject to the penalties of theft.', 'en', 'Commercial Code (Expanded), Article 642', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '643', 'Article 643 In the cases referred to in the preceding articles the tribunal or the Court shall adjudicate, even though there had been a discharge 1- Officially upon the return to the capital stock of creditors, of all chattel, rights or actions fraudulently abstracted; 2- On the damages which had been claimed and which the ruling or adjudication shall arbitrate.', 'en', 'Commercial Code (Expanded), Article 643', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '644', 'Article 644 Any Receiver who shall have been guilty of embezzlements in his management shall be punished by way of correction under the penalties for breach of trust. - 128 -', 'en', 'Commercial Code (Expanded), Article 644', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '645', 'Article 645 The creditor who shall have stipulated, either with the insolvent, or with any other person, specific advantages against his vote in deliberations over the insolvency, or who shall have concluded a special agreement from which there would derive in his favor an advantage out of the insolvent''s assets, shall be punished for misdemeanor by a term of imprisonment of between one month and a year and by a fine which shall not exceed 250 Lebanese Pounds, subject to extenuating circumstances Imprisonment may be increased to two years, if the creditor is the Receiver of the insolvency.', 'en', 'Commercial Code (Expanded), Article 645', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '646', 'Article 646 Additionally, covenants shall be declared void towards all persons and even in respect of the insolvent. The creditor shall be required to return to whomsoever is legally qualified for the purpose the sums or values he shall have received by virtue of the cancelled agreements.', 'en', 'Commercial Code (Expanded), Article 646', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '647', 'Article 647 All decisions and rulings from conviction pronounced by virtue of the provisions of the present title shall be posted and published, in accordance with the forms established for the publicity of adjudication of insolvency. j', 'en', 'Commercial Code (Expanded), Article 647', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '648', 'Article 648 Proceedings taken for simple or fraudulent bankruptcy entail no modification to the ordinary rules governing the administration of the insolvency.', 'en', 'Commercial Code (Expanded), Article 648', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '649', 'Article 649 In this case, however, the Receivers shall be bound to remit to the public prosecutor the documents, titles, papers and information that shall be required of them.', 'en', 'Commercial Code (Expanded), Article 649', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '650', 'Article 650 The documents, titles and papers delivered by the Receivers shall be held, throughout the course of investigation, for the communication via the Clerk''s office. Such communication shall occur upon the request of the Receivers who may take therefrom private abstracts or require authentic ones which shall be dispatched by the Clerk. The documents, titles and papers, the legal deposit of which has not been ordained, shall be, following the award or the ruling, remitted to the Receivers who shall give discharge therefor. TITLE V - REHABILITATION', 'en', 'Commercial Code (Expanded), Article 650', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '651', 'Article 651 When ten years have elapsed since the adjudication of insolvency, the insolvent non-bankrupt is rehabilitated as a matter of right, without formalities being completed. Such rehabilitation shall in no way impair the functions of the Receivers, if their term of- office has not ended, nor the creditors'' rights, in case the debtors have not wholly paid up.', 'en', 'Commercial Code (Expanded), Article 651', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '652', 'Article 652 Is rehabilitated, as a matter of right, the insolvent who has paid up the sums owed by him as capital, interests and charges, interests being unclaimable beyond five years. In order to be rehabilitated as a matter of right, the partner in a company of persons fallen into insolvency is to justify that he has settled, within the same condition, his contribution to the debts of the company, even though he may have been granted a private scheme of arrangement. In the event of disappearance, absence or refusal to receive from one or several creditors, the sum due is deposited in the bank approved for the recaption of State deposits, justification of such deposit being tantamount to clearance.', 'en', 'Commercial Code (Expanded), Article 652', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '653', 'Article 653 To obtain rehabilitation, in the event of acknowledged probity 1 - The insolvent who, having obtained a scheme of arrangement, shall have paid up in full the promised dividends. This provision is applicable to the partner in a company of persons lapsed into insolvency who has obtained from creditors a private scheme of arrangement. 2 - He who justifies the total remittance of his debts by his creditors or their unanimous consent to his rehabilitation.', 'en', 'Commercial Code (Expanded), Article 653', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '654', 'Article 654 Every petition for rehabilitation shall be addressed to the prosecutor of the Republic at the Court which has adjudicated insolvency, with the receipts and documents justifying it. This magistrate shall communicate all the documents to the Court president who has awarded the insolvency and to the prosecutor of the Republic of the petitioner''s domicile, charging them to collect all the evidence they can se cure on the truth of the facts put forward. The production of receipts and other documents for the purpose of rehabilitation shall not, by itself, render registration compulsory.', 'en', 'Commercial Code (Expanded), Article 654', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '655', 'Article 655 Notification of the petition shall be served by registered letter by the Court Clerk to every creditor to the insolvency, duly verified or acknowledged by subsequent judicial award, who has not been fully paid up.', 'en', 'Commercial Code (Expanded), Article 655', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '656', 'Article 656 Any creditor who has not received his dividend in full under the scheme of arrangement or who has not wholly remitted his debts to the debtor may, within a month of the serving of this notification, move opposition to the rehabilitation, by simple deed in the Clerk''s office, supported by documentary evidence. The opposing creditor may, by petition filed with the Court and notified to the debtor, intervene in the rehabilitation procedure.', 'en', 'Commercial Code (Expanded), Article 656', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '657', 'Article 657 After expiry of the time-limit, the result of the inquiries prescribed above and the oppositions moved by the creditors shall be communicated to the prosecutor of the Republic to whom the petition has been referred, and transmitted by him, with his motivated opinion, to the Court president.', 'en', 'Commercial Code (Expanded), Article 657', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '658', 'Article 658 The Court shall convene, if need be, the petitioner and his opponents and shall cross-hear them in Council chamber. The petitioner may have himself assisted by a counsel. In case of total payment of the debts, the Court shall restrict itself to the bona fide of the justifications produced and, if they conform to the law, it shall award rehabilitation. In the event of optional rehabilitation, the Court shall appreciate the circumstances of the cause. The award shall be rendered in public session. It may be appealed against, as much by the petitioner as by the prosecutor of the Republic, and by the creditors, within a month from the notification which shall have been served to them by registered letter. The contesting creditors shall equally be advised of the award. They may exercise their right of opposition before the Court of Appeal. The Court shall adjudicate, following examination and according to the forms prescribed above.', 'en', 'Commercial Code (Expanded), Article 658', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '659', 'Article 659 If the petition is dismissed, it may not be taken up again except after the lapse of one year. If it is received, the ruling or award shall be transcribed on the Court''s register in the place of the insolvency and that of the petitioner''s domicile. It shall further be addressed to the prosecutor of the Republic who shall have received the petition and, through the letter''s good offices, to the prosecutor of the Republic in the petitioner''s birthplace, who shall enter it on the judiciary record in front of the adjudication of insolvency. The said decision shall equally be entered on the trade register.', 'en', 'Commercial Code (Expanded), Article 659', 'Bankruptcy and insolvency', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '660', 'Article 660 Shall not be admitted to trade rehabilitation, fraudulent bankrupts, persons convicted of theft, swindling or breach of trust, unless they have obtained penal rehabilitation.', 'en', 'Commercial Code (Expanded), Article 660', 'Theft and robbery', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '661', 'Article 661 The insolvent may not be rehabilitated, after his death. ''TITLE VI - SPECIAL PROVISIONS FOR COMPANY INSOLVENCIES', 'en', 'Commercial Code (Expanded), Article 661', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '662', 'Article 662 Resides the rules already indicated in the course of the preceding titles, companies are submitted to the following provisions.', 'en', 'Commercial Code (Expanded), Article 662', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '663', 'Article 663 All trading companies, with the exception of participating companies, are likely to obtain a scheme of arrangement or be adjudicated insolvent. A company, even in a state of liquidation, may be declared insolvent. This is possible, even if the company has been judicially annulled, whenever a de facto company still remains.', 'en', 'Commercial Code (Expanded), Article 663', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '664', 'Article 664 Petition for a scheme of arrangement, as well as the declaration for the purpose of having insolvency adjudicated, must be signed by the partner or partners who are authorized to sign for the company, if the case concerns a limited joint stock company or a limited partnership, by the manager or director who discharges such duties, following a resolution by the board of directors when a joint-stock company is concerned. When the company has gone into liquidation, it is incumbent upon the Receiver to make the declaration. The petition or declaration must be lodged with the Clerk of the Court in whose territorial jurisdiction the company operates its head office.', 'en', 'Commercial Code (Expanded), Article 664', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '665', 'Article 665 All the partners in a private company, and the financed in sleeping partnership companies, must equally, in so far as they are concerned, make the declaration required by the present code within the twenty days of the company''s suspension of payments. The Court shall, in a single ruling, adjudicate the company''s insolvency and that of the jointly-liable partners, and shall appoint in principle a single commissioner-judge and one and same Receiver, although these different insolvencies remain distinct and that the capital stock of each of them is differently constituted.', 'en', 'Commercial Code (Expanded), Article 665', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '666', 'Article 666 In all companies, the Receiver may compel the partners to complete the payment of their contributions, even before the date set by the Articles.', 'en', 'Commercial Code (Expanded), Article 666', 'Companies and corporate', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '667', 'Article 667 In the event of a company''s bankruptcy, may be sued, if need be, as penalty liable, both the jointly-liable partners and the financed, as well as the manager of joint-stock companies or the director discharging these duties. General and Transitional Provisions', 'en', 'Commercial Code (Expanded), Article 667', 'Penalties and sentencing', 'Commercial Law'),
  ('LB-COM-001-EXPANDED', '668', 'Article 668 (as modified by the Law of 30 September 1944) Dating from the day when the provisions of the present code become executory, all the previous legislative provisions shall be divested of power in those matters which are the object of the present code. The present code shall be enforced six months after its publication in the Official Gazette. Beirut, 24 December 1942 Signed: Alfred Naccache By the President of the Republic The President of the Council of Ministers The Minister of Commerce and Industry Signed: Sami Solh The Minister of Justice Signed: Ahmed Husseini', 'en', 'Commercial Code (Expanded), Article 668', NULL, 'Commercial Law'),
  ('LB-COM-001-EXPANDED', NULL, 'Full article-level text of the Lebanese Commercial Code (Legislative Decree No. 304/1942). Covers trade, merchants, commercial companies (partnerships, joint stock, limited liability), negotiable instruments, bankruptcy and insolvency, maritime commerce, and commercial agency.', 'en', 'Commercial Code (Expanded) — Historical Context', 'Historical context and overview', 'Commercial Law'),
  ('LB-CONST-012', NULL, 'An unwritten verbal agreement between President Bechara el-Khoury (Maronite Christian) and Prime Minister Riad al-Solh (Sunni Muslim) in 1943. Formalized through al-Solh''s ministerial declaration to the Chamber of Deputies on October 7, 1943. Key provisions: (1) Muslims would not seek unity with Syria, (2) Christians would relinquish French protection, (3) Lebanon would have an ''Arab face'', (4) Key political positions distributed by confession: President = Maronite, PM = Sunni, Speaker = Shia. The Pact established the confessional power-sharing that defines Lebanese governance. It has no formal legal text but carries constitutional weight through custom and practice. The 6:5 Christian-to-Muslim ratio in Parliament was also formalized around this period (though technically from a July 1943 French High Commissioner decision). The Taif Agreement of 1989 modified but did not replace the National Pact''s core principles.', 'en', 'Lebanese National Pact of 1943 — Historical Context', 'Historical context and overview', 'Constitutional Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CONST-013', NULL, 'Signed on October 22, 1989, in Taif, Saudi Arabia, by 62 of the 73 surviving Lebanese Members of Parliament to end the 15-year Lebanese Civil War (1975-1990). Approved by Parliament on November 5, 1989, and implemented through constitutional amendments ratified on August 21, 1990, signed into law on September 21, 1990. Key reforms: (1) Equalized confessional representation in Parliament from 6:5 Christian/Muslim to 1:1, expanding to 108 then 128 seats; (2) Transferred significant executive power from President to Council of Ministers; (3) Enhanced role of Prime Minister and Speaker; (4) Established Constitutional Council; (5) Called for eventual abolition of political confessionalism (never implemented); (6) Called for administrative decentralization; (7) Disbanded militias (partially implemented); (8) Affirmed Lebanese sovereignty. Brokered by Saudi Arabia with backing from the Arab League and international community.', 'en', 'Taif Agreement / Charter of Lebanese National Reconciliation — Historical Context', 'Historical context and overview', 'Constitutional Law'),
  ('LB-CRIM-002-EXPANDED', '1', 'The purpose of the Code of Criminal Procedure is to regulate criminal justice and to define its scope and the measures to be taken in criminal investigations and trials. It also sets out the types of appeal available against judgements and decisions rendered. A further purpose is to regulate the procedures for bringing to light the facts and evidence of criminal offences in application of criminal legislation.', 'en', 'Code of Criminal Procedure (Expanded), Article 1', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '2', 'Ordinary criminal trials are divided into the following categories: (a) A Single Judge hears all cases concerning misdemeanours and contraventions unless special provision is made for exceptions. The Public Prosecution Service is not represented; (b) Each chamber of an Appeal Court is composed of a President and two Auxiliary Judges. The Public Prosecution Service is represented by an Appeal Court Prosecutor, an Appeal Court Advocate- General, the Financial Prosecutor or an Advocate-General attached to the Financial Prosecutor’s Office; (c) Each chamber of the Court of Cassation is composed of a President and two Auxiliary Judges. The Public Prosecution Service is represented by the Public Prosecutor at the Court of Cassation or an Advocate-General of the Court of Cassation.', 'en', 'Code of Criminal Procedure (Expanded), Article 2', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '3', 'The Investigation Department in each governorate is composed of the First Investigating Judge and one or more Investigating Judges, depending on the provisions of the Administration of Justice Act. A chamber of the civil Appeal Court performs the functions of an Indictment Division in each governorate.', 'en', 'Code of Criminal Procedure (Expanded), Article 3', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '4', 'The Administration of Justice Act establishes the procedures governing the appointment of judges, the number of chambers of the Court of Cassation in the capital city, and the number of Appeal Court chambers, Single Judges, Investigating Judges and Advocates-General in the capital city, the governorates and the districts. Public prosecutions and civil actions', 'en', 'Code of Criminal Procedure (Expanded), Article 4', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '5', 'Responsibility for initiating a public prosecution, the purpose of which is to prosecute perpetrators of crimes and their accomplices and to subject them to penalties and other measures, lies with the Judges of the Public Prosecution Service in accordance with this Code. Every aggrieved person also has the right to bring a civil action for damages suffered as a result of an offence. Any person against whom a public prosecution is initiated shall be termed a defendant; a person charged with a misdemeanour shall be termed a charged person; and a person accused of committing a felony shall be termed an accused.', 'en', 'Code of Criminal Procedure (Expanded), Article 5', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '6', 'The Public Prosecutor’s Office shall be responsible for exercising the public prosecution. It may not discontinue the proceedings or arrange an amicable settlement. English version (STL Draft Official Translation of Arabic) Version 1.0 3 A civil action may be initiated following the public prosecution before the judicial authority responsible for the latter. Such an action may also be brought separately before the competent civil authority.', 'en', 'Code of Criminal Procedure (Expanded), Article 6', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '7', 'Any aggrieved person may assume the status of a civil party before the First Investigating Judge in the case of a felony or misdemeanour or before the Single Judge in the case of a misdemeanour or contravention. A civil party may also be joined to the public prosecution before the Criminal Court. An aggrieved person may file suit to bring a public prosecution if the Public Prosecutor’s Office has not done so. The party may withdraw the civil action or reach an amicable settlement without thereby affecting the public prosecution unless the circumstances are such that the extinction of the civil action entails the extinction of the public prosecution.', 'en', 'Code of Criminal Procedure (Expanded), Article 7', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '8', 'An aggrieved person who has brought an action before the competent civil court may not abandon the case and bring an action before a criminal court unless the Public Prosecutor’s Office initiated a public prosecution on a date subsequent to that on which the party brought the action before the civil court, provided that a final judgement has not been delivered in the civil proceedings. The competent civil authority shall not proceed with a civil action until the public prosecution has been finally disposed of; a court of summary jurisdiction shall be authorized to take summary measures even if a civil action has been brought before the criminal court.', 'en', 'Code of Criminal Procedure (Expanded), Article 8', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '9', 'The public prosecution shall be initiated before the criminal authority which has jurisdiction in the area in which the crime was committed, the place of residence of the defendant, or the place in which the defendant was arrested.', 'en', 'Code of Criminal Procedure (Expanded), Article 9', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '10', 'The public prosecution shall be extinguished under the following circumstances: (a) Death of the defendant; (b) A general amnesty; (c) Expiry of a prescription period of ten years in the case of a felony, three years in the case of a misdemeanour, and one year in the case of a contravention; (d) Extinction of the civil action in the cases specified by law. – The prescription period shall begin to run in the case of one-time offences on the date of their occurrence. In the case of continuing, persistent or successive offences, the prescription period shall begin to run on the date on which the criminal situation comes to an end. – The expiry of the prescription period for the public prosecution shall entail the suspension of all acts of prosecution, investigation or trial. – The grounds for prescription of public prosecutions shall also be applicable to civil actions. However, the grounds for prescription of civil actions shall not entail the prescription of public prosecutions. – The prescription period shall be suspended if it proves impossible, because of force majeure, to perform any act of prosecution, investigation or trial, and it shall resume as soon as the impediment is eliminated. – The above-mentioned provisions regarding the prescription period shall not preclude the application of provisions regarding certain misdemeanours and contraventions. English version (STL Draft Official Translation of Arabic) Version 1.0 4 – The criminal court that is seized of an action shall continue, in the event of the extinction of the public action on one of the above-mentioned grounds, to hear the civil action. It shall order the confiscation of impounded articles if such articles are prohibited by law. – The prescription period for the civil action is governed by the Civil Code. – The provisions of the Criminal Code governing the prescription period shall be applicable to the penalties imposed. English version (STL Draft Official Translation of Arabic) Versio', 'en', 'Code of Criminal Procedure (Expanded), Article 10', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '11', 'Public prosecutions at the Court of Cassation are conducted by the Public Prosecutor with the assistance of Advocates-General. The duties of the Financial Prosecutor’s Office at the Court of Cassation are performed by the Public Prosecutor with the assistance of Advocates-General. The duties of the Public Prosecutor’s Office at the Appeal Court are performed by the Public Prosecutor with the assistance of one or more Advocates-General. The work of the Public Prosecutor’s Office at the Military Court is carried out by a Government Commissioner, who is subject to the authority of the Public Prosecutor at the Court of Cassation and is assisted by one or more Advocates-General.', 'en', 'Code of Criminal Procedure (Expanded), Article 11', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '12', 'Each Public Prosecutor heads a department and assigns activities falling within his remit to the Advocates-General who assist him in his duties. Chapter I Duties of the Public Prosecutor at the Court of Cassation', 'en', 'Code of Criminal Procedure (Expanded), Article 12', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '13', 'Article 13 (as amended by Act No. 359/2001) - The Public Prosecutor’s Office at the Court of Cassation is headed by a Public Prosecutor who is appointed by a decree of the Council of Ministers based on a proposal by the Minister of Justice. He is assisted by Advocates-General. The authority of the Public Prosecutor at the Court of Cassation extends to all Judges of the Public Prosecution Service, including the Government Commissioner at the Military Court. He shall provide them with written or oral instructions for the conduct of the public prosecution. They shall be free, however, to make statements at trial hearings. The prosecutor shall refer to them, depending on their area of jurisdiction, the reports and records produced with respect to any offence, and request them to conduct the requisite public prosecution. Subject to Article 79 of the Organization of the Legal Profession Act, in all cases in which a criminal prosecution requires a licence or the consent of a non-judicial authority, the Public Prosecutor at the Court of Cassation shall be empowered, where a dispute arises between the authority in question and the Appeal Court Prosecutor’s Office, the Financial Prosecutor’s Office or the Government Commissioner at the Military Court, to take a final decision on the matter notwithstanding any public or private provision.', 'en', 'Code of Criminal Procedure (Expanded), Article 13', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '14', 'Article 14 (as amended by Act No. 359/2001) - The Minister of Justice may request the Public Prosecutor at the Court of Cassation to prosecute any offences of which he has knowledge. The latter shall be entitled, if necessary, to undertake the investigation directly or through his assistants – the Judges of the Public Prosecution Service assigned to assist him or members of the Judicial Police force subject to his authority – but he shall not be entitled to lay charges.', 'en', 'Code of Criminal Procedure (Expanded), Article 14', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '15', 'The Public Prosecutor at the Court of Cassation oversees the actions of Judicial Police officers in the performance of their duties as assistants to the Public Prosecutor’s Office. He may make such observations as he sees fit to their supervisors regarding the work referred to above, and may request the Appeal Court Prosecutor, the Financial Prosecutor or the Government Commissioner at English version (STL Draft Official Translation of Arabic) Version 1.0 6 the Military Court to take action against any officer who commits a criminal offence during the performance of his duties or in connection with their performance, without having to obtain prior permission. Such offences shall be handled by the ordinary courts notwithstanding any provision to the contrary.', 'en', 'Code of Criminal Procedure (Expanded), Article 15', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '16', 'The Appeal Court Prosecutor, the Financial Prosecutor, the Government Commissioner at the Military Court, the Director-General of the Internal Security Forces, the Director- General of General Security and the Director-General of State Security shall inform the Public Prosecutor at the Court of Cassation of serious offences of which they have knowledge and shall comply with his instructions in this regard. The Public Prosecutor at the Court of Cassation may inspect the file pertaining to an investigation being conducted by an Investigating Judge and ask the responsible Public Prosecutor to show that the submissions comply with his written instructions. He may admonish a members of the Public Prosecution Service for any shortcomings in their work, or he may recommend to the Judicial Inspectorate that they be referred to the Disciplinary Board.', 'en', 'Code of Criminal Procedure (Expanded), Article 16', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '17', 'The Public Prosecutor at the Court of Cassation shall undertake the following activities: (a) Apply for the setting aside of judgements and decisions in criminal proceedings in accordance with the procedures laid down in this Code; (b) Demand that a judicial authority be designated and that a case be transferred from one court to another; (c) Prosecute offences referred to the Judicial Council; (d) Prosecute offences committed by members of the national legal service either within or outside the context of their judicial office; (e) Represent the Public Prosecutor’s Office at the Court of Cassation and before the Judicial Council; (f) Deal with requests for the extradition of criminals and forward them to the Minister of Justice together with his observations; (g) Compile a detailed report for insertion in the case file of persons sentenced to death when the case is referred to the Pardon Commission; (h) Any other duties and powers mentioned in this Code and in any other legislation. English version (STL Draft Official Translation of Arabic) Version 1.0 7 Chapter II Duties of the Financial Prosecutor’s Office', 'en', 'Code of Criminal Procedure (Expanded), Article 17', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '18', 'The Financial Prosecutor is appointed by a decree of the Council of Ministers based on a proposal by the Minister of Justice. The Financial Prosecutor shall exercise, within the limits of the duties specified in this Code, the same powers as those of the Public Prosecutor at the Court of Cassation.', 'en', 'Code of Criminal Procedure (Expanded), Article 18', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '19', 'The Financial Prosecutor has the authority to prosecute the following offences: (a) Offences arising from breaches of the provisions of the legislation relating to duties and taxes in the various public utilities and establishments and municipalities, including state and municipal taxes, customs duties, and telecommunication and wireless communication fees; (b) Offences arising from breaches of the legislation concerning banks, financial institutions and the stock exchange, particularly those defined in the Currency and Credit Act; (c) Offences arising from breaches of the legislation on joint-stock companies and offences by multinational companies; (d) Offences that adversely affect the State’s financial standing, or Lebanese or foreign banknotes circulating by law or by custom in Lebanon, and offences involving the counterfeiting, forgery and circulation of currency, public securities, stamps and stamped papers; (e) Offences involving the embezzlement of public funds; (f) Offences pertaining to bankruptcy.', 'en', 'Code of Criminal Procedure (Expanded), Article 19', 'Companies and corporate', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '20', 'Banking offences arising from breaches of the Law on Currency and Credit may be prosecuted only on the basis of a written request from the Governor of the Banque du Liban. Offences pertaining to customs duties may be prosecuted only on the basis of a written request from the Director-General of Customs. In cases where the administration concerned is entitled to reach an amicable settlement with the defendant, the public prosecution shall be extinguished if the settlement is reached prior to the delivery of a judgement. Enforcement of the penalty shall be suspended if the settlement is reached thereafter, provided that no contrary legal provision is applicable.', 'en', 'Code of Criminal Procedure (Expanded), Article 20', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '21', 'The Financial Prosecutor shall exercise the powers vested in him by this Code under the authority of the Public Prosecutor at the Court of Cassation and subject to the rules and regulations applied by the Appeal Court Prosecutor on the basis of this Code and financial legislation. These powers of the Financial Prosecutor shall extend throughout the Lebanese territory. In this connection, he may request, through the Public Prosecutor at the Court of Cassation, the Appeal Court Prosecutor in any governorate to initiate a public prosecution before the Investigating Judges or to initiate proceedings directly before the courts exercising jurisdiction.', 'en', 'Code of Criminal Procedure (Expanded), Article 21', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '22', 'The Financial Prosecutor may seek the assistance of experts in banking, fiscal and financial affairs in performing technical tasks, after they take the oath of legal expertise, unless they are sworn experts. The Public Prosecutor at the Court of Cassation may, of his own motion or at the request of the Financial Prosecutor, request the Prime Minister through the Minister of Justice to instruct the Central Inspectorate to undertake an investigation into any financial matters that he is authorized to have examined. English version (STL Draft Official Translation of Arabic) Version 1.0 8', 'en', 'Code of Criminal Procedure (Expanded), Article 22', 'Taxation', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '23', 'The Financial Prosecutor’s Office shall maintain a special legal record of all companies to which Decree No. 3094 of 25 January 1993 is applicable. He shall record all criminal judgements delivered against them. The registrars at the courts exercising jurisdiction shall inform the Financial Prosecutor’s Office of any criminal judgement that has been or is being delivered against a company so that it may be recorded in the special legal register of companies within three months of the date of the judgement. Chapter III Duties of the Public Prosecutor’s Office at the Appeal Court and procedures in the case of offences discovered during their commission or immediately afterwards Section I Duties of the Public Prosecutor’s Office at the Appeal Court', 'en', 'Code of Criminal Procedure (Expanded), Article 23', 'Companies and corporate', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '24', 'The duties of the Public Prosecutor’s Office at the Appeal Court are as follows: (a) To investigate offences characterized as misdemeanours or felonies and to prosecute those who participated in their commission. The office may apply directly for assistance from the law enforcement authorities in the performance of its duties; Where it obtains knowledge of the commission of a serious offence, it shall immediately inform the Public Prosecutor at the Court of Cassation and carry out his instructions. (b) To initiate and exercise public prosecutions; (c) To represent the Public Prosecution Service at appeal courts and criminal courts and to enforce their judgements; (d) To issue a wanted notice if the person named in a complaint or a suspect cannot be found or if his domicile is unknown; the notice shall contain his full identity and the details of the alleged offence; – When a warrant is executed, the issuing Prosecutor’s Office shall be informed forthwith. – The warrant expires ten days after its date of issue unless the Public Prosecutor decides to extend it for thirty days, following which it shall expire. (e) To set aside criminal judgements or to stay or suspend their enforcement pursuant to', 'en', 'Code of Criminal Procedure (Expanded), Article 24', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '147', 'Evidence held on file, summonses, judgements and decisions are served and judicial measures are executed through special security units under the direct authority of the Public Prosecutor, the First Investigating Judge and the Presidents of special authorities and courts. They are answerable to the President of the judicial body who charges or instructs them to serve any document or execute any measure in the event of their failure to do so at the appointed time. The process server may not serve a document on himself or on his spouse, or on their ascendants, descendants, relatives by marriage or any other relatives up to the fourth degree of kinship. The document to be served shall state the name of the person requesting service, the name and address of the process server, the date on which he was instructed to serve the document and the name and address of the addressee. If the addressee is a legal person, the document shall be served at its main office. In addition to the foregoing, the document to be served shall specify the offence that is the subject of the prosecution, investigation or trial, the legal provision applicable thereto, the judicial authority seized of the case, and the status of the person to be served with the document: plaintiff, defendant, property administrator, surety, witness, etc. The person serving the document shall execute his instructions without delay and do his utmost to notify the addressee himself. The addressee shall sign the original of the document served and shall be provided with a copy thereof. If he refuses or is unable to sign, or if he refuses to take delivery of the copy, this shall be noted by the process server on the original document. If the person to be served with a document is not present at his elected place of residence or domicile, the document shall be served through a member of his family, a domestic employee or any other person living in the same dwelling provided that it may be inferred from his', 'en', 'Code of Criminal Procedure (Expanded), Article 147', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '25', 'The Public Prosecutor’s Office obtains information regarding offences by one or more of the following means: (a) Investigations conducted by the office itself; (b) Reports from the official authority or an officer who obtained knowledge of an offence during the performance of his duties or concurrently or in connection with their performance. He is English version (STL Draft Official Translation of Arabic) Version 1.0 9 entitled to carry out an investigation in public administrations or establishments but he may not initiate proceedings; (c) Preliminary inquiries conducted by the Judicial Police force where it has been instructed to investigate offences, and the reports it submits relating thereto; (d) Complaints or reports filed with it directly or through the Public Prosecutor’s Office at the Court of Cassation or its assistants; (e) Any lawful means that enables it to obtain information regarding the offence.', 'en', 'Code of Criminal Procedure (Expanded), Article 25', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '26', 'The Public Prosecutor’s Office at the Appeal Court brings charges and names those charged with the offence. It may bring charges against an unknown person before the Investigating Judge, thereby initiating a public prosecution.', 'en', 'Code of Criminal Procedure (Expanded), Article 26', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '27', 'A complaint is filed by a victim or his legal representative and a report is submitted by an informant who knew of the offence or heard about it. A report is admissible only if it is submitted in writing and signed by the informant or his legal representative. Every complaint or report shall state, clearly and in full, the name of the complainant or informant and his place of residence.', 'en', 'Code of Criminal Procedure (Expanded), Article 27', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '28', 'Any person who witnesses a breach of the peace or an offence against a person’s safety, life or property is required to report the matter to the Appeal Court Prosecutor or one of his assistants in the place where the offence occurred, the place where the perpetrator was apprehended, or his place of residence. Anyone who fails to comply with this requirement without lawful excuse shall be prosecuted before the Single Criminal Judge responsible for the area where the offence occurred and shall be sentenced to a fine of between two hundred thousand and two million Lebanese pounds. Section II Procedures to be followed by the Public Prosecutor’s Office in the case of an offence discovered during its commission or immediately afterwards', 'en', 'Code of Criminal Procedure (Expanded), Article 28', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '29', 'An offence discovered during its commission or immediately afterwards is: (a) An offence discovered as it occurs; (b) An offence where the perpetrator is apprehended during or immediately after its commission; (c) An offence following which the suspected perpetrator is chased by hue and cry; (d) An offence detected immediately after being committed with clearly discernible signs of its commission; (e) An offence where a person is caught in possession of articles, weapons or documents indicating that he is the perpetrator within twenty-four hours of the commission of the offence.', 'en', 'Code of Criminal Procedure (Expanded), Article 29', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '30', 'Felonies and misdemeanours shall have the status of offences discovered during their commission or immediately afterwards if they occur within a dwelling whose owner or occupier requests the Public Prosecutor’s Office to conduct an investigation within twenty-four hours of their discovery.', 'en', 'Code of Criminal Procedure (Expanded), Article 30', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '31', 'In the case of a felony discovered during its commission or immediately afterwards, the Public Prosecutor or the Advocate-General shall proceed forthwith, on receiving the information, to English version (STL Draft Official Translation of Arabic) Version 1.0 10 the scene of the crime and shall inform the First Investigating Judge or the Investigating Judge on duty thereof, without being required to wait for him to arrive in order to take the following steps: (a) Prepare a report describing the traces left in connection with the crime, the scene and the apparent circumstances of the crime; (b) Seizure of weapons and other items used in the commission of the offence as well as any items that may assist in establishing the facts, and questioning of the suspect about the seized items shown to him; (c) Interview of persons who witnessed the offence or obtained information concerning it after they swear an oath as legal witnesses. Each statement shall be reflected in a record, which shall be signed by the Public Prosecutor or Advocate-General, the clerk and the witness. If the latter refuses to sign, this shall be noted in the record.', 'en', 'Code of Criminal Procedure (Expanded), Article 31', 'Taxation', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '32', 'Article 32 (as amended by Act No. 359/2001) - The Public Prosecutor or the Advocate-General may prohibit persons present at the scene of the felony from leaving it. Anyone who breaches the prohibition decision shall be prosecuted before the Single Criminal Judge responsible for the area where the offence occurred and shall be sentenced to a fine of between two hundred thousand and two million Lebanese pounds. If there are strong suspicions regarding one of the persons present, the prosecutor or his deputy shall order his arrest for questioning and the person shall remain in custody for the purposes of the investigation for a period not exceeding forty-eight hours unless additional time is required for the investigation, in which case his custody shall be extended for a further forty-eight hours. The person being questioned may appoint an advocate to be present during the questioning. During the period of custody, he, his advocate, or a member of his family may request a medical examination, and the Public Prosecutor or the Advocate-General shall appoint a doctor as soon as the request is made. The Judicial Police officers and their assistants shall not be present when the doctor carries out the examination. The doctor shall submit his report to the person who authorized the examination and present a copy thereof to the defendant within a period not exceeding forty-eight hours. If the suspect absconded or was not present at the beginning of the investigation, the Public Prosecutor or the Advocate-General shall issue a warrant to bring the suspect before them immediately. When the suspect appears before them, they shall question him forthwith. The submission of a report shall not of itself be a sufficient ground to issue a summons in respect of a person whose place of residence is known. Investigative measures relating to a felony discovered at the time of its commission or immediately afterwards shall end eight days after their commencement.', 'en', 'Code of Criminal Procedure (Expanded), Article 32', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '33', 'The Public Prosecutor may enter a suspect’s home to search for items that he believes will help to shed light on the investigation. He may seize such items, which shall be described clearly and in detail in his report. He may also decide to retain the seized items, depending on their nature. The search shall be conducted in the presence of the suspect or the defendant. If the suspect or defendant is not present or refuses to take part, if he is unable to be present or if he has absconded, the search shall be conducted in the presence of his advocate, two adult members of his family, or two witnesses selected by the Public Prosecutor. English version (STL Draft Official Translation of Arabic) Version 1.0 11 – As soon as the search is completed and the items seized, the Public Prosecutor shall display the seized items to the suspect, the defendant, his advocate or the aforementioned persons and ask each person to sign the record. If they refuse, this shall be noted in the record. – If the Public Prosecutor finds prohibited items during the search, he shall seize them. If they are not items resulting from, used in or associated with the offence, he shall report them in a separate record. – The Public Prosecutor may instruct a Judicial Police officer to conduct a search of the home of the suspect or defendant, on his authority and under his control in accordance with the rules to be observed by the Public Prosecutor himself. – It is permissible to enter homes to conduct a search or to look for a perpetrator only between 5 a.m. and 8 p.m. unless the homeowner explicitly agrees to such actions outside that time period. However, the Public Prosecutor or the authorized Judicial Police officer may conduct a search or look for a suspect at any time in public places or in places that have acquired such status by virtue of the use made of them.', 'en', 'Code of Criminal Procedure (Expanded), Article 33', 'Inheritance and succession', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '34', 'If the nature of the crime or its impact requires the assistance of one or more experts to clarify technical points, the Public Prosecutor shall appoint the expert and clearly specify his assignment. – If the victim’s condition necessitates medical assistance or an autopsy, the Public Prosecutor shall send for a forensic or specialist physician and give him clear and detailed instructions regarding his assignment. – The expert or doctor shall carry out the assignment only after swearing an oath to act truly and faithfully. – He may not exceed the bounds of the assignment. After completing it, he shall file a report specifying the authority that appointed him, the task assigned, the measures taken and his conclusions.', 'en', 'Code of Criminal Procedure (Expanded), Article 34', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '35', 'The Public Prosecutor shall take any other investigative measures he deems necessary to gather useful information regarding the felony, to collect evidence and to identify the perpetrators or accomplices. The measures must be lawful and must not be vitiated by moral or material coercion. He shall record in his reports all measures taken, the time of their commencement and completion, and all means employed in their implementation. He shall then sign each report together with the clerk who assisted him.', 'en', 'Code of Criminal Procedure (Expanded), Article 35', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '36', 'The Public Prosecutor shall suspend his investigation of an offence discovered during its commission or immediately afterwards when the Investigating Judge arrives, and he shall provide the judge with his reports and the items seized, except for those which are unrelated to the offence and were seized on the ground that they are prohibited items. The Public Prosecutor shall inform the Investigating Judge of the offence that has been committed and shall name any persons whose involvement in the offence appears to be supported by evidence or suspicions. He shall charge those against whom evidence exists or who are suspected of having participated in the commission of the offence. If the time limit applicable to offences discovered during their commission or immediately afterwards expires before the Investigating Judge arrives, the Public Prosecutor shall complete his investigations and forward the documents contained in the case file to the Investigating Judge, together with the statement of charges. English version (STL Draft Official Translation of Arabic) Version 1.0 12', 'en', 'Code of Criminal Procedure (Expanded), Article 36', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '37', 'When an offence discovered during its commission or immediately afterwards occurs within his area of jurisdiction, the Single Judge shall proceed to the scene to undertake an investigation if the Public Prosecutor or the Investigating Judge is not present. He shall observe the rules applicable to the Public Prosecutor in this regard. He shall suspend his inquiries as soon as either of them arrives. On completion of his investigation, he shall forward the file to the Public Prosecutor. English version (STL Draft Official Translation of Arabic) Version 1.0 13 Part II The Judicial Police Chapter I Members of the Judicial Police', 'en', 'Code of Criminal Procedure (Expanded), Article 37', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '38', 'The duties of the Judicial Police are performed, under the supervision of the Public Prosecutor at the Court of Cassation, by Public Prosecutors and Advocates-General. The persons listed below assist the Public Prosecution Service and work under its supervision in performing the duties of the Judicial Police within their fields of competence, as specified in this Code and in the legislation governing their profession: 1. Governors and district commissioners; 2. The Director-General of the Internal Security Forces, officers of the Internal Security Forces, the Judicial Police, non-commissioned officers serving in the regional sectors, and the heads of Internal Security Forces police stations; 3. The Director-General of General Security, General Security officers and non- commissioned General Security investigators; the Director-General of State Security, the Deputy Director-General, State Security officers and non-commissioned State Security investigators; 4. Village mayors; 5. Captains of ships and aircraft.', 'en', 'Code of Criminal Procedure (Expanded), Article 38', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '39', 'Village guards, supervisory officials at the Ministry of Health, forest and consumer protection supervisors, customs supervisors, tobacco control supervisors, supervisors at ports and airports and at the Ministry of Tourism and night watchmen may keep an account of all infringements within their fields of competence and in accordance with the regulations they are required to apply, record them in rigorously compiled reports and submit them to the competent Single Judge. Chapter II Measures to be taken by the Judicial Police in connection with offences whether or not they were discovered during or immediately after their commission', 'en', 'Code of Criminal Procedure (Expanded), Article 39', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '40', 'Judicial Police officers shall take the same measures in the case of an offence discovered at the time of its commission or immediately afterwards as are taken by the Public Prosecutor when he is unable to do so himself. In undertaking such measures, the Judicial Police officer shall comply with the legal rules applicable to the Public Prosecutor when he investigates an offence discovered at the time of its commission or immediately afterwards. Moreover, in the case of offences not discovered at the time of their commission or immediately afterwards, the Judicial Police, acting on the instructions of the Public Prosecutor’s Office, shall investigate felonies or misdemeanours that are the subject of complaints and reports referred to them by the Public Prosecutor’s Office. English version (STL Draft Official Translation of Arabic) Version 1.0 14 Section I Measures to be taken by the Judicial Police in connection with offences discovered at the time of their commission or immediately afterwards', 'en', 'Code of Criminal Procedure (Expanded), Article 40', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '41', 'If an offence discovered at the time of its commission or immediately afterwards occurs, the Judicial Police officer shall proceed forthwith to the place where it occurred and shall inform the competent Public Prosecutor thereof. He shall preserve any clues, traces and evidence that might disappear and anything that might assist in shedding light on the facts. He shall look for and seize weapons and materials used in or resulting from the commission of the offence. He shall interview witnesses without requiring them to take an oath. He shall make inquiries, arrest anyone who is strongly suspected of having committed the offence or of having participated in its commission, conduct a search of his home and seize any incriminating materials or prohibited items that he finds. He shall seek expert assistance if necessary. He may question the suspect provided that the latter makes his statement of his own free will in full knowledge of the facts and without being subjected to any form of coercion. If he decides to remain silent, he may not be compelled to speak. The Judicial Police officer who investigates the offence discovered during its commission or immediately afterwards shall inform the competent Public Prosecutor of his inquiries and shall comply with his instructions. If the competent Public Prosecutor directs the Judicial Police officer to perform certain acts that fall within his jurisdiction, he shall act within the parameters of the assignment.', 'en', 'Code of Criminal Procedure (Expanded), Article 41', 'Inheritance and succession', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '42', 'Article 42 (as amended by Act No. 359/2001) - If the offence discovered at the time of its commission or immediately afterwards is a felony, and the requirements of the investigation demand that the suspect be held in custody for a longer period, the time limit may be extended up to a maximum period of four days upon a reasoned decision in writing by the Appeal Court Prosecutor, who shall issue it after examining the file and verifying the justifications provided. During the extended period, the suspect, his advocate or a member of his family may request that he be examined by a doctor. The Public Prosecutor shall appoint a doctor as soon as the petition is filed and the doctor shall carry out the examination without a Judicial Police officer being present and shall submit his report to the Public Prosecutor within twenty-four hours. In all circumstances, this period of custody shall be deducted from any sentence imposed. The Judicial Police officer shall observe strict confidentiality in all the measures that he takes. If it is ascertained that he divulged the content of seized documents or letters or any confidential material that the suspect wished to remain secret, he shall be prosecuted before the Single Criminal Judge with jurisdiction for the area in which the acts complained of occurred and shall be punishable by imprisonment of between one month and one year, and/or a fine of between two hundred thousand and two million Lebanese pounds.', 'en', 'Code of Criminal Procedure (Expanded), Article 42', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '43', 'If the Judicial Police officer believes that a person who is not under strong suspicion possesses documents or materials that are useful for the investigation, the Public Prosecutor or the Investigating Judge shall carry out a search of the person’s home instead of the Judicial Police officer unless the person concerned consents without coercion to a search by the latter. Any house search carried out by the Judicial Police in breach of the rules of procedure legally applicable to the Public Prosecutor in the case of felonies discovered during their commission or immediately afterwards shall be declared null and void. A Judicial Police officer who enters a home and undertakes a search in violation of these rules shall be liable to prosecution for the misdemeanour English version (STL Draft Official Translation of Arabic) Version 1.0 15 defined in Article 370 of the Criminal Code. However, the nullity shall be applicable only to the search and not to the other investigative measures.', 'en', 'Code of Criminal Procedure (Expanded), Article 43', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '44', 'If the Public Prosecutor or the Investigating Judge is present, the Judicial Police officer shall suspend his operations unless he receives written instructions from either of them to continue. Under such circumstances, he may also be tasked with questioning the suspect. Once the situation pertaining to offences discovered during their commission or immediately afterwards has come to an end, the Judicial Police officer may not carry out any additional inquiries but shall transmit the records he has compiled to the Public Prosecutor forthwith, together any items seized during the search.', 'en', 'Code of Criminal Procedure (Expanded), Article 44', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '45', 'In the event of a felony or misdemeanour discovered at the time of its commission or immediately afterwards being punishable by imprisonment, any person is entitled to arrest the perpetrator caught in the act and to take him to the nearest Judicial Police station.', 'en', 'Code of Criminal Procedure (Expanded), Article 45', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '46', 'If the offence discovered at the time of its commission or immediately afterwards is a misdemeanour punishable by imprisonment of at least one year, the Judicial Police officer may arrest the suspect and investigate the misdemeanour under the authority of the Public Prosecutor. The Public Prosecutor may decide to detain a person charged with a misdemeanour and to bring him forthwith before the Single Judge so that he may be prosecuted in accordance with the rules laid down in this Code. Section II Measures to be taken by the Judicial Police in connection with offences other than those discovered at the time of their commission or immediately afterwards', 'en', 'Code of Criminal Procedure (Expanded), Article 46', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '47', 'Article 47 (as amended by Act No. 359/2001) - Judicial Police officers, acting as assistants to the Public Prosecutor’s Office, shall perform the duties assigned to them by the Public Prosecutor’s Office. They investigate offences not discovered at the time of their commission or immediately afterwards, gather information, make inquiries aimed at identifying the perpetrators and accomplices and gather evidence against them, and carry out actions necessitated by these duties, such as the seizure of incriminating items, the conduct of physical searches of crime scenes, scientific and technical analyses of any samples, and taking statements from witnesses without requiring them to take an oath and of statements from persons complained of or suspects. If they refuse to make a statement or remain silent, this fact shall be mentioned in the record; they may not be coerced to speak or to undergo questioning, on pain of nullity of their statements. Judicial Police officers shall inform the Public Prosecutor’s Office of the measures they take and shall abide by its instructions. They may not search a home or person without obtaining prior permission from the Public Prosecutor’s Office. If permission for a search is granted, they shall abide by the legal rules applicable to the Public Prosecutor in the case of offences discovered at the time of their commission or immediately afterwards. Any search conducted in breach of these rules shall be null and void. However, the nullity shall be applicable only to the search and not to other unrelated measures. Judicial Police officers may not detain a suspect at the police station without a decision by the Public Prosecutor’s Office and the period of detention shall not exceed forty-eight hours. This period may be extended by a similar period subject to the consent of the Public Prosecutor’s Office. English version (STL Draft Official Translation of Arabic) Version 1.0 16 The period of custody shall be calculated from the time of arre', 'en', 'Code of Criminal Procedure (Expanded), Article 47', 'Family law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '48', 'If the Judicial Police officer breaches the rules concerning the detention of the defendant or suspect, he shall be liable to prosecution for the offence of unlawful detention set out in', 'en', 'Code of Criminal Procedure (Expanded), Article 48', NULL, 'Criminal Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CRIM-002-EXPANDED', '367', 'The Judicial Council may, of its own motion or pursuant to an application from the Public Prosecutor’s Office at the Court of Cassation, conduct a supplementary investigation into the case by the full bench or through any of its members delegated for the purpose. English version (STL Draft Official Translation of Arabic) Version 1.0 85 Part VII Interlocutory matters', 'en', 'Code of Criminal Procedure (Expanded), Article 367', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '49', 'The Public Prosecutor may carry out the preliminary investigation himself. If he does, the suspect’s advocate may be present with his client during the questioning. If he does not carry out the investigation himself, he shall scrutinize the preliminary investigations conducted by the Judicial Police officer, with the exception of the questioning of the suspect or person complained of. If he ascertains that the offence is a felony or if a misdemeanour necessitates further investigation, he shall seize the Investigating Judge. If the investigation of a misdemeanour proves to be sufficient, he shall seize the competent Single Judge.', 'en', 'Code of Criminal Procedure (Expanded), Article 49', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '50', 'The Public Prosecutor may decide to retain the documents resulting from the preliminary investigation if he considers that the act does not constitute an offence, that there is insufficient evidence that an offence has been commiteed, or that the public prosecution has been extinguished for one of the reasons set out in Article 10 of this Code. The Public Prosecutor who brings charges in a case is not entitled to undertake an investigation or to deliver a judgement thereon. English version (STL Draft Official Translation of Arabic) Version 1.0 17 Part III Investigating Judges and their duties Chapter I Organization of the Investigation Departments', 'en', 'Code of Criminal Procedure (Expanded), Article 50', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '51', 'An Investigation Department composed of a First Investigating Judge and Investigating Judges is attached to each Appeal Court. The Investigation Department is headed by the First Investigating Judge. The submission containing the Public Prosecutor’s Office’s charges is filed with the First Investigating Judge. Actions brought directly by victims of crimes discovered during their commission or immediately afterwards based on their personal charges are also submitted to him. The First Investigating Judge investigates important cases himself and may assign other cases to the Investigating Judges in his department. He oversees the smooth running of his department.', 'en', 'Code of Criminal Procedure (Expanded), Article 51', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '52', 'The Investigating Judge to whom a case is referred may not refuse to investigate it. He may, however, recuse himself. Any party to the litigation may request that he be disqualified. The rules laid down in the Code of Civil Procedure shall be applicable to anyone requesting withdrawal or disqualification. If an Investigating Judge is prevented by any impediment from performing his duties, the First President of the Appeal Court shall appoint a Judge to replace him. The Investigating Judge who investigates a case is not entitled to try the case or to participate in the trial.', 'en', 'Code of Criminal Procedure (Expanded), Article 52', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '53', 'The investigation shall remain confidential until such time as the case is referred to the trial court, except for matters pertaining to the indictment decision. Anyone who breaches the confidentiality of the investigation shall be liable to prosecution before the Single Judge in whose area of jurisdiction the act complained of occurred; he shall be punishable by imprisonment of between one month and one year and by a fine of between one hundred thousand and one million Lebanese pounds or by either of these two penalties.', 'en', 'Code of Criminal Procedure (Expanded), Article 53', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '54', 'Appeals against the Investigating Judge’s decisions lie with the Indictment Division, which has sole authority to issue indictments in the case of felonies and exercises the right of transfer in legally specified cases. English version (STL Draft Official Translation of Arabic) Version 1.0 18 Chapter II Duties of the Investigating Judge in the case of offences discovered at the time of their commission or immediately afterwards', 'en', 'Code of Criminal Procedure (Expanded), Article 54', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '55', 'In the event of an offence discovered during its commission or immediately afterwards, the Investigating Judge shall proceed to the scene of the crime and initiate an investigation without waiting for the Public Prosecutor. If the Public Prosecutor arrives at the scene, he may not participate in the investigation or undertake a separate investigation himself. He may, however, submit any application he sees fit to the Investigating Judge. If he was the first to arrive at the scene of the crime and initiated an investigation, he shall suspend it and comply with the provisions of Article 36 of this Code. The Investigating Judge shall be accompanied to the scene of the crime by the clerk of his department. If he requests the assistance of an officer of the Judicial Police, the latter shall take an oath to perform his work truly and faithfully and to preserve the confidentiality of the investigation.', 'en', 'Code of Criminal Procedure (Expanded), Article 55', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '56', 'The Investigating Judge shall exercise, in the case of a felony discovered during its commission or immediately afterwards, all the prerogatives enjoyed by the Public Prosecutor. He shall carry out all the acts and measures assigned to him and specified in Articles 31, 32, 33, 34 and 35 of this Code.', 'en', 'Code of Criminal Procedure (Expanded), Article 56', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '57', 'On completion of the measures required by the investigation of a felony discovered during its commission or immediately afterwards, the Investigating Judge shall hand over the documents to the Public Prosecutor, who shall bring charges against the suspect and file his submissions. After the Public Prosecutor’s Office brings charges, the Investigating Judge shall undertake the investigation in accordance with the normal rules. The Public Prosecutor may examine the file pertaining to the investigation at any time and submit his requests in writing. The Investigating Judge shall examine them and decide to accept or reject them. If he rejects them, he shall inform the Public Prosecutor thereof. The latter is entitled to file an appeal with the Indictment Division against any decision contrary to his submission. The Investigating Judge must abide by the Indictment Chamber’s decision regarding the appeal.', 'en', 'Code of Criminal Procedure (Expanded), Article 57', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '58', 'In the case of a misdemeanour discovered during its commission or immediately afterwards which is punishable by one year of imprisonment or less, the Public Prosecutor may ask the Investigating Judge for leave to proceed to the scene of the misdemeanour to conduct an on-site investigation. The Investigating Judge shall oversee the measures undertaken in the investigation of a felony discovered during its commission or immediately afterwards. English version (STL Draft Official Translation of Arabic) Version 1.0 19 Chapter III Duties of the Investigating Judge in the case of offences not discovered at the time of their commission or shortly afterwards Section I General provisions', 'en', 'Code of Criminal Procedure (Expanded), Article 58', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '59', 'The Investigating Judge may conduct an investigation in the case of an offence not discovered at the time of its commission or shortly afterwards only if he conducts the public prosecution on the basis of charges brought by the Public Prosecutor’s Office, a direct complaint filed by the victim in the capacity of a civil party, a decision to designate the judicial authority or a decision to transfer the case.', 'en', 'Code of Criminal Procedure (Expanded), Article 59', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '60', 'The Investigating Judge shall conduct the public prosecution in rem. He may question as a defendant anyone suspected of having committed the offence as a perpetrator, accomplice, accessory or instigator independently of the charges brought by the Public Prosecutor’s Office. If he detects in the course of the investigation criminal acts unrelated to the act charged, he shall transmit the file to the Public Prosecutor so that he may bring the relevant charges. However, if the offences disclosed are related to the act charged, he may issue a joinder to the ongoing investigation without having them referred to him beforehand.', 'en', 'Code of Criminal Procedure (Expanded), Article 60', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '61', 'The Investigating Judge must use lawful means in undertaking all investigative measures aimed at establishing the truth. He shall record all measures undertaken in writing. If the investigation requires an inspection of the scene of the crime, the Investigating Judge shall proceed to the scene together with the clerk of his department. He shall inform the Public Prosecutor of this step without waiting for him, and shall take the samples in accordance with the rules. Section II Charges submitted by the Appeal Court Public Prosecutor’s Office to the Investigating Judge', 'en', 'Code of Criminal Procedure (Expanded), Article 61', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '62', 'The charges submitted by the Public Prosecutor to the Investigating Judge shall contain a description of the offence, specify the identity of all those who participated in its commission, the place in which the criminal act occurred and the time of its occurrence, and state his requests. If he has been unable to identify all the participants in the offence, he shall bring charges against those identified or else against an unknown person. The Public Prosecutor’s charges shall initiate a public prosecution, brought either by himself or by one of the Advocates-General. The Public Prosecutor shall attach to the charges the relevant documents, records and supporting evidence.', 'en', 'Code of Criminal Procedure (Expanded), Article 62', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '63', 'The Investigating Judge may not refuse to conduct the public prosecution set in motion by the Public Prosecutor’s charges unless it transpires that the act of which he has been seized does not constitute a criminal offence or that the public prosecution has been extinguished on a specific legal ground. He shall not take such a decision without consulting the Public Prosecutor. English version (STL Draft Official Translation of Arabic) Version 1.0 20 He may decide to stay the public prosecution by a decision taken after consulting the Public Prosecutor if he ascertains that another Investigating Judge has already conducted the same investigation or an investigation into a related offence. The Public Prosecutor may request the Investigating Judge to refrain from proceeding with the prosecution if it involves circumstances in respect of which charges have already been brought, or if it is related to another prosecution under investigation and is being joined thereto.', 'en', 'Code of Criminal Procedure (Expanded), Article 63', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '64', 'It is not for the Investigating Judge to quash the charges brought by the Public Prosecutor’s Office at the Appeal Court on finding a flaw that is liable to render his conduct of the investigation unsound. However, he may decide to refrain from conducting an investigation on account of the flaw. If the Public Prosecutor decides not to rectify the flaw, he shall appeal the Investigating Judge’s decision before the Indictment Division.', 'en', 'Code of Criminal Procedure (Expanded), Article 64', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '65', 'The Investigating Judge may, after consulting the Public Prosecutor’s Office, decide that he lacks competence to investigate the case if it falls outside his territorial or ratione materiae jurisdiction or on account of the status of the defendant. His decision in this regard may be appealed to the Indictment Division.', 'en', 'Code of Criminal Procedure (Expanded), Article 65', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '66', 'The Public Prosecutor may file supplementary charges in respect of acts that were omitted from his original statement of charges and against persons omitted from that statement or from his subsequent statement. The Investigating Judge shall question the persons concerned as defendants and treat them as such throughout the investigation.', 'en', 'Code of Criminal Procedure (Expanded), Article 66', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '67', 'The victim of a crime may file civil charges with the Investigating Judge in connection with the public prosecution initiated by the Public Prosecutor’s Office’s statement of charges. He is required to elect a domicile in the town or borough in which the Investigating Judge’s office is located if his actual domicile is not in that location. Should he fail to do so, he may not object if he is not served with the documents to which he is legally entitled. The victim may be fully or partially exempted from paying the costs of the proceedings, even in the event of a decision not to prosecute the defendant, if it is demonstrated that he did not abuse the right to bring an action. If he is a foreign national, he shall provide surety, the scale and nature of which shall be determined by the Investigating Judge. He may be exempted from providing surety if his civil action warrants such exemption. Section III Charges filed by the direct victim of an offence with the Investigating Judge', 'en', 'Code of Criminal Procedure (Expanded), Article 67', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '68', 'Any victim of a felony or misdemeanour may file a complaint directly with the First Investigating Judge who has jurisdiction over the area in which the offence was committed, the place of residence of the defendant or the place in which he was arrested. The victim may assume the status of a civil party. The complaint shall be recorded in the registry of the First Investigating Judge, who shall determine the costs to be paid in advance, comprising legal fees and costs, which shall not exceed one per cent of the cost of the proceedings. In addition, he shall instruct the complainant, if he is a foreign English version (STL Draft Official Translation of Arabic) Version 1.0 21 national, to present surety in the form of legal tender or property, the scale of which shall be determined in his decision. The complainant shall be exempted from paying an advance if the offence complained of is a felony. If the act is a misdemeanour, the Investigating Judge may exempt the complainant from paying an advance if he is financially unfit to do so. He may also exempt a foreign complainant from paying surety on the same ground by a reasoned decision. The complaint filed by a complainant who acquires the status of a civil party and who makes the required payment, unless exempted therefrom, automatically initiates a public prosecution. If either of these two conditions is not met, it shall be regarded as a report and referred to the Public Prosecutor for a decision on whether to initiate a public prosecution. The complainant may withdraw the civil action. If he does so within two working days of the date of his complaint, he shall not be liable for the costs of withdrawal. His withdrawal shall not affect the course of the public prosecution except in cases where the extinction of the civil action leads to the extinction of the public prosecution.', 'en', 'Code of Criminal Procedure (Expanded), Article 68', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '69', 'The First Investigating Judge shall personally undertake the investigation into a direct complaint, however he may assign it to an Investigating Judge in his department. The Judge handling the direct complaint shall initiate the investigation after consulting the Public Prosecutor’s Office at the Appeal Court. However, he shall not be bound by its opinion if it involves a refusal to proceed with the public prosecution already initiated by a civil action in accordance with the provisions of Article 68, paragraph 4, of this Code. He shall deliver a copy of the complaint and its attachments to the defendant at least twenty-four hours before questioning him.', 'en', 'Code of Criminal Procedure (Expanded), Article 69', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '70', 'The Public Prosecutor may challenge the status of the civil party to the prosecution before carrying out the investigation. The defendant or his advocate may raise this plea prior to the questioning. The Investigating Judge, after informing the civil party of the plea and giving him twenty- four hours to respond, shall issue a ruling after consulting the Public Prosecutor’s Office at the Appeal Court.', 'en', 'Code of Criminal Procedure (Expanded), Article 70', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '71', 'If the Public Prosecutor ascertains that the complaint is unclear, he may request the Investigating Judge to proceed with the investigation forthwith before deciding on his position. In these circumstances, the Investigating Judge shall question the persons designated in the complaint as defendants and shall interview the witnesses. He shall then transmit the file to the Public Prosecutor so that he can decide whether to prosecute. The Investigating Judge may, on obtaining evidence that persons interviewed as witnesses participated in the offence, question them as defendants provided that he abides by Article 61 of this Code.', 'en', 'Code of Criminal Procedure (Expanded), Article 71', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '72', 'If the Investigating Judge decides to stay the prosecution of a person designated by the complainant, the defendant may apply to the Single Criminal Judge for an award of damages against the civil party for abuse of his right to bring an action. He shall bring his action, on pain of inadmissibility, within three months of the date of being notified of the decision to stay the prosecution. English version (STL Draft Official Translation of Arabic) Version 1.0 22 Chapter IV Investigative measures Section I Procedural objections', 'en', 'Code of Criminal Procedure (Expanded), Article 72', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '73', 'The defendant, or his advocate in the absence of his client and the Public Prosecutor’s Office may raise any of the following objections once only prior to the questioning of the defendant: 1. Objection to jurisdiction; 2. Objection of nullity of the public prosecution on one of the legally established grounds of nullity; 3. Objection of inadmissibility of the prosecution on a ground that precludes hearing or proceeding with the case before its substance is examined; 4. Objection on the ground that the act charged does not constitute a legally prosecutable offence; 5. Objection of lis pendens or lis alibi pendens; 6. Objection of res judicata; 7. Objection of nullity of one or more investigative measures. The Investigating Judge, after hearing the civil party and consulting the Public Prosecutor’s Office, shall rule on the objection within a week of the date on which it was filed. Any party to the proceedings may appeal his decision. Section II Questioning of the defendant', 'en', 'Code of Criminal Procedure (Expanded), Article 73', 'Narcotics', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '74', 'The Public Prosecutor shall verify the defendant’s identity and ascertain his family name and first name, his age, his place of birth, his parents’ names, his place of residence, his social and civil status and his criminal record. He may seek the assistance of psychiatric and medical experts in assessing the defendant’s mental and physical health. If the defendant or his advocate requests a psychological or physical examination, the Investigating Judge may deny the request only on the basis of a reasoned decision.', 'en', 'Code of Criminal Procedure (Expanded), Article 74', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '75', 'The Investigating Judge shall question the defendant in his department unless the latter is unable to attend owing to illness, disability or some other valid excuse. Having verified the impediment, the Investigating Judge shall travel, together with his clerk, to the place in which the defendant can be questioned in accordance with the rules set out below.', 'en', 'Code of Criminal Procedure (Expanded), Article 75', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '76', 'When the defendant appears before him for the first time, the Investigating Judge shall inform him of the charges against him, summarizing the facts and informing him of the evidence in his possession or of the suspicions against him so that he can refute them and mount a defence. The Investigating Judge is not required to provide him with a legal characterization of the facts. English version (STL Draft Official Translation of Arabic) Version 1.0 23 The Investigating Judge shall inform him of his rights, particularly the right to the assistance of an advocate during the questioning. If the Investigating Judge fails to inform the defendant of the charges against him, as set out above, or to inform him of his right to the assistance of an advocate, the results of the questioning shall be inadmissible as evidence.', 'en', 'Code of Criminal Procedure (Expanded), Article 76', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '77', 'The Investigating Judge shall respect the principle of the defendant’s exercise of free will during the questioning and shall ascertain that he is making his statement without any outside influence of a moral or material nature. If the defendant refuses to respond and chooses to remain silent, the Investigating Judge may not compel him to speak. If the defendant shows signs of physical, psychological or mental illness during the questioning, the assistance of a medical expert may be sought to diagnose his condition.', 'en', 'Code of Criminal Procedure (Expanded), Article 77', 'Inheritance and succession', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '78', 'If the defendant declines the assistance of an advocate, the Investigating Judge is not required to appoint counsel on his behalf. This fact shall be recorded on pain of nullity of the questioning and the subsequent measures. He shall question him in the absence of counsel and proceed with the investigative measures. If the defendant chooses an advocate to defend him, the Investigating Judge may not question him or proceed with the investigative measures unless the advocate is present and is informed of all the investigative acts except for the witnesses’ statements, on pain of nullity of the questioning and of the subsequent measures. If the defendant is unable to appoint an advocate, the Investigating Judge shall appoint one or ask the President of the Bar Association to do so. At any time during the investigation, the defendant may inform the Investigating Judge of the name of the advocate whom he has appointed to defend him. If he chooses more than one advocate for the purpose, he shall inform the Investigating Judge of the name of the advocate who should be served with notice of the case. The notice inviting the advocate to attend shall be sent at least one day before the questioning. The Investigating Judge’s clerk shall note this step in the record, mentioning the date on which notice was served. If the advocate is not notified before the date of the hearing, his presence during the questioning, without raising an objection to the failure to serve notice, shall preclude the nullity of the questioning. If the client’s advocate fails to attend without a lawful excuse in spite of being duly informed of the date of the hearing, the Investigating Judge may proceed with the questioning.', 'en', 'Code of Criminal Procedure (Expanded), Article 78', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '79', 'Before each examination after the preliminary questioning, the Investigating Judge shall ask the defendant whether he still consents to being questioned without the constant assistance of an advocate, and shall note this step in the record on pain of nullity of the examination in question and the subsequent measures. The defendant may communicate freely with his advocate throughout the investigation period. Their communications shall be confidential. Any evidence resulting from a breach of the principle of confidentiality shall be inadmissible.', 'en', 'Code of Criminal Procedure (Expanded), Article 79', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '80', 'As an exception to the provisions of Articles 78 and 79 of this Code, the Investigating Judge may take a reasoned decision to begin questioning the defendant forthwith if there is a risk that a clue or evidence may disappear. English version (STL Draft Official Translation of Arabic) Version 1.0 24 He may question the defendant without the presence of an advocate in the case of an offence discovered during its commission or immediately afterwards or the equivalent thereof.', 'en', 'Code of Criminal Procedure (Expanded), Article 80', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '81', 'If the defendant’s advocate is present during the questioning, he may not put any questions with his client or the opposing party except through the Investigating Judge. He is permitted to make observations and to object to any aspect of the Investigating Judge’s questioning which, in his view, breaches the rules governing the investigation. If the Investigating Judge does not permit the advocate to speak, to put a question, to make observations or to raise objections, this fact shall be noted in the record of the questioning. The Public Prosecutor or one of his assistants may attend the questioning of the defendant, and he may raise questions or make observations through the Investigating Judge. If the defendant is not proficient in the Arabic language, the Investigating Judge shall appoint an interpreter, who shall begin his work after taking an oath to perform his duties honestly and with integrity. If the defendant is mute, deaf or unable to express himself, the Investigating Judge shall appoint a person who can communicate with him in sign language or in some other way after taking an oath to perform his duties honestly and with integrity. If a deaf or mute person is able to write, the questions and his answers shall be recorded in writing. The paper recording his answers shall be attached to the record of questioning. The civil party, the property administrator and the surety may be present during the questioning of the defendant or may appoint an advocate for the purpose. They may each put questions and make observations through the Investigating Judge. If there is more than one defendant in the case, it is not permissible for one of them or for his advocate to attend the questioning of the other defendants except during confrontations between the defendants.', 'en', 'Code of Criminal Procedure (Expanded), Article 81', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '82', 'If the Investigating Judge has questioned the defendant about an offence as though it constituted a misdemeanour and then ascertains that it should be characterized as a felony, he shall repeat the questioning and indicate that the defendant is entitled to the assistance of an advocate if he has not appointed one to defend him. Subject to the provisions of the penultimate paragraph of Article 81 of this Code, the defendant, the civil party, the property administrator and the surety or their advocates may attend the investigative proceedings, except for the hearings of witnesses. They shall each be notified of the proceedings at least twenty-four hours before the investigative measures concerning them. Otherwise the measures undertaken in their absence shall be null and void. If persons who were to be summoned present themselves without objecting to the manner in which they were notified or to the failure to comply with the twenty-four hour time limit, the investigative proceedings shall be deemed to be valid. The property administrator and the surety shall each elect a domicile within the town or borough in which the Investigating Judge’s department is located, if they have no actual domicile there, for the service of documents and notices. If they fail to do so, they may not object to the failure to serve the documents of which they should be legally notified. Each of the aforementioned persons shall inform the Investigating Judge in writing of any change in his actual or elected domicile. If these persons fail to do so, notices served at the domicile recorded in the case file shall be valid. English version (STL Draft Official Translation of Arabic) Version 1.0 25', 'en', 'Code of Criminal Procedure (Expanded), Article 82', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '83', 'The Investigating Judge may decide to prohibit communication for a period not exceeding five days with a defendant who is being held in custody. The prohibition shall not be applicable to communications between the defendant and his advocate. If an arrest warrant for a detained defendant is executed in his absence, the Investigating Judge, on being apprised of the detention, shall summon the detained defendant and question him concerning the charges against him in accordance with the rules set out above.', 'en', 'Code of Criminal Procedure (Expanded), Article 83', 'Family law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '84', 'If a defendant who resides outside the Investigating Judge’s area of jurisdiction presents a lawful excuse for his inability to present himself before him, the Investigating Judge may request the Investigating Judge or the Single Judge with jurisdiction over the defendant’s place of residence to assist in questioning him. He may not appoint a Judicial Police officer for this purpose. The Investigating Judge may not terminate his investigation without questioning the defendant unless questioning is impossible because he has absconded, or unless he concludes that the evidence assembled is sufficient to terminate the proceedings without the need for questioning. Section III Hearing of witnesses', 'en', 'Code of Criminal Procedure (Expanded), Article 84', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '85', 'If the proceedings require the hearing of statements from the President of the Republic, the Speaker of the Chamber of Deputies or the Prime Minister, the Investigating Judge and his clerk shall proceed to the relevant office and take his statement.', 'en', 'Code of Criminal Procedure (Expanded), Article 85', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '86', 'The Investigating Judge shall summon the persons whose names appear in the complaint, the report or the submissions as well as anybody else who, in his view, may be able to provide evidence to assist the investigation. – He need not summon a witness named by the civil party or the defendant if he considers that the hearing would serve no purpose. However, if he declines to hear a witness named by the Public Prosecutor''s Office, he shall take a reasoned decision in that regard. – The summons shall be served on the witness at least twenty-four hours before the time set for the hearing. – Notice shall be served on members of the diplomatic or consular service through the Ministry of Foreign Affairs. – Summonses to members of the armed forces shall be served through their respective commands. – If the witness resides abroad, the summons shall be served by registered mail with acknowledgement of receipt. – If he is in custody, the witness shall be conveyed under escort.', 'en', 'Code of Criminal Procedure (Expanded), Article 86', 'Family law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '87', 'Before being heard, the witness shall present the summons to appear that he received, and this shall be noted in the record. If he attends before being summoned, he may not refuse to make a statement on the ground that he was not notified of the time of his appearance. The Investigating Judge shall interview each witness individually in the presence of his clerk. The Investigating Judge shall first ask the witness to state his first name and family name, the names of his parents, his age and profession, his domicile or the place where he is staying, and whether he is married to, in the service of or related to one of the parties, asking him to specify the degree of English version (STL Draft Official Translation of Arabic) Version 1.0 26 affinity, and shall then require him to take the following oath: “I swear by almighty God to tell the truth, the whole truth and nothing but the truth.” This shall be noted in the record. The witness shall make his statement orally and may rely on supporting documents. The statement of each witness shall be reflected in a record containing the questions put to him and his answers. The witness’s statement shall be read to him and he shall approve it, signing it on each page. If he refuses to sign or is unable to do so, this shall be noted in the record. The number of pages constituting the witness’s statement shall be noted at the end of the record. The Investigating Judge and his clerk shall sign each page. A list of the names of the persons heard and the dates of the hearings shall be included in the official record. If exhibits are shown to the witness, this shall be noted in the record. The same rules of procedure shall be applicable to hearings of statements by the civil party, the defendant, the property administrator, the surety and the expert. Only the person harmed by a breach of one of the above-mentioned rules may request that the record be annulled.', 'en', 'Code of Criminal Procedure (Expanded), Article 87', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '88', 'If the witness is not proficient in the Arabic language, the Investigating Judge shall appoint an interpreter, who shall take an oath to perform his duties honestly and with integrity before starting work, unless he is already a certified interpreter.', 'en', 'Code of Criminal Procedure (Expanded), Article 88', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '89', 'If the witness makes a false statement, lies or conceals some or all of what he knows regarding the facts of the case concerning which he is being questioned, the Investigating Judge shall refer the record of his statement to the Public Prosecutor’s Office at the Appeal Court so that he may be prosecuted for the offence of perjury defined in Article 408 of the Criminal Code.', 'en', 'Code of Criminal Procedure (Expanded), Article 89', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '90', 'The record of the investigation shall contain no deletions, annotations or additions. If it is necessary to cross out or insert a word, the Investigating Judge, the clerk and the witness shall express their approval of the deletion, annotation or addition by signing the margin of the record. Any unapproved annotation, deletion or addition shall be null and void, and the provisions of the last paragraph of Article 87 of this Code shall be applicable thereto.', 'en', 'Code of Criminal Procedure (Expanded), Article 90', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '91', 'The Investigating Judge shall hear minors under 18 years of age as a source of information. If a minor over 15 years of age has taken a legal oath, his statement shall be considered valid and he may not be prosecuted for the offence of perjury. The ascendants and descendants of the defendant, his brothers and sisters and relatives by marriage of the same degree, his spouse even if they are divorced, and informants who are legally entitled to financial reward for their information are not allowed to testify. The Investigating Judge may hear a statement from any of the aforementioned persons as a source of information.', 'en', 'Code of Criminal Procedure (Expanded), Article 91', 'Family law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '92', 'A witness may not be excused from testifying unless it can be demonstrated that he is legally bound to secrecy. If the Investigating Judge ascertains that the witness’s plea of professional or banking secrecy is legally inappropriate, he shall take a reasoned decision, after consulting the Public Prosecutor’s Office at English version (STL Draft Official Translation of Arabic) Version 1.0 27 the Appeal Court, to dismiss the plea. The witness may file an appeal against the decision within twenty- four hours of the date of his notification thereof. Any person who possesses information that might shed light on the investigation is required to bring it to the attention of the Investigating Judge. If he fails to do so, he shall be liable to a fine of between 100,000 and 200,000 Lebanese pounds, payable in the same manner as taxes. If the information in question is likely to prove the innocence of the defendant, a person who fails to testify or who withholds proof of its existence shall be liable to prosecution pursuant to Article 567 of the Criminal Code, as amended.', 'en', 'Code of Criminal Procedure (Expanded), Article 92', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '93', 'The Investigating Judge shall order that the witness be reimbursed for his travel expenses and the party who requested his presence shall be liable for payment. In the case of a public prosecution, the Treasury shall be liable for payment.', 'en', 'Code of Criminal Procedure (Expanded), Article 93', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '94', 'If the witness resides outside his area of jurisdiction, the Investigating Judge may request the Investigating Judge or Single Judge in whose area of jurisdiction he resides to take his statement. The requesting Judge shall inform the requested Judge clearly and in detail of the facts concerning which the witness should be questioned. The requested Judge shall duly hear the witness’s statement immediately after he takes the oath and shall send the record containing the statement in a sealed envelope to the requesting Judge as speedily as possible.', 'en', 'Code of Criminal Procedure (Expanded), Article 94', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '95', 'Any person who has been duly notified of his duty to appear before the Investigating Judge to testify is under an obligation to appear. If he fails to do so without a lawful excuse, the Investigating Judge shall send a further summons to attend the next hearing after imposing a fine of between 50,000 and 100,000 Lebanese pounds. If he again fails to appear, a warrant shall be issued to have him brought before before the Investigating Judge. If the witness pleads illness and provides a doctor’s certificate in support of his inability to appear, the Investigating Judge may dismiss the plea if he considers that it is not serious, or he may appoint another doctor or medical panel to examine the witness and determine whether his state of health prevents him from appearing. If it appears to the Investigating Judge that the certificate is fallacious, he shall compile a report and refer it to the Public Prosecutor’s Office so that the witness and the doctor who drew up the certificate may be prosecuted pursuant to Article 466 of the Criminal Code. If a plea other than illness is raised and it appears to the the Investigating Judge that it is fallacious, he shall compile a report and refer it to the Public Prosecutor’s Office so that the witness may be prosecuted pursuant to Article 407 of the Criminal Code.', 'en', 'Code of Criminal Procedure (Expanded), Article 95', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '96', 'If the witness is unable to come to the office of the Investigating Judge on account of illness, disability or force majeure, the Judge and his clerk may travel to his place of residence and take his statement.', 'en', 'Code of Criminal Procedure (Expanded), Article 96', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '97', 'In the absence of his clerk or a clerk of the Investigation Department, the Public Prosecutor’s Office or the courts, the Investigating Judge may appoint an Internal Security Forces officer, who shall record the witness’s statement after taking an oath to perform his assignment honestly and with integrity. If there is no clerk available to compile the record, the Investigating Judge may do so himself. The record that he compiles under these circumstances shall not be null and void. English version (STL Draft Official Translation of Arabic) Version 1.0 28 Section IV Attendance, searches and seizure of evidence', 'en', 'Code of Criminal Procedure (Expanded), Article 97', NULL, 'Criminal Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CRIM-002-EXPANDED', '98', 'The Investigating Judge may travel with his clerk to carry out an inspection of the scene of the crime or to search a residence for incriminating materials or items capable of shedding light on the investigation. He shall inform the Public Prosecutor of his movements. If the latter accompanies him, he shall conduct the inspection and search in his presence; if he does not, he shall conduct them alone. The inspection or search shall be conducted in the presence of the civil party and the defendant. If one of them is not present or is unable to attend, it shall be conducted in the presence of his advocate, two witnesses who are members of his family or two witnesses chosen by the Investigating Judge. The Investigating Judge shall compile a detailed record of the investigative measures or the search, which shall be signed by himself, his clerk and all those present. If exhibits or items of interest to the investigation are seized, he shall include a sufficiently detailed description of the nature of each item. He shall preserve the exhibits and articles as befits their nature, placing them under the seal of the Investigation Department and attaching a label listing the seized items, signed by the Investigating Judge, his clerk and those present. If the seized items are registers, documents or statements of account, they shall be placed in sealed envelopes bearing the seal of the Investigation Department, and labelled with a list of the items. These will be kept at the Investigation Department. If the seized items consist of bullion, banknotes or securities, they shall be placed in envelopes bearing the seal of the Investigation Department, labelled with a detailed record of the items seized and deposited in the Palace of Justice vault. If confidential documents are seized during the search, they shall be numbered and may be viewed only by the Investigating Judge and their owner. They shall be placed in sealed envelopes bearing the seal of the Investigation', 'en', 'Code of Criminal Procedure (Expanded), Article 98', 'Banking and credit', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '99', 'If the seized items include any article that cannot be transported to the Investigation Department or the secure depository at the Palace of Justice because of its size or dangerous nature, the Investigating Judge shall deposit it with whichever party he deems best suited to look after it. This shall be noted in a record signed by the Investigating Judge, his clerk, the owner of the seized item and the person with whom it has been deposited.', 'en', 'Code of Criminal Procedure (Expanded), Article 99', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '100', 'When prosecuting a lawyer, the Investigating Judge may not search his office without first informing the President of the Bar Association thereof, except in the case of an offence discovered during its commission or immediately afterwards. – The Investigating Judge shall not breach professional secrecy during the search. – The President of the Bar Association or a person designated by him may be present during the search. – Any interception of the suspected lawyer’s communications shall require a judicial decision and prior notification of the President of the Bar Association.', 'en', 'Code of Criminal Procedure (Expanded), Article 100', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '101', 'If the Investigating Judge finds prohibited items during the search, the acquisition or possession of which constitutes a misdemeanour or a felony, he shall seize them, even if they are English version (STL Draft Official Translation of Arabic) Version 1.0 29 unrelated to the offence being investigated, note this fact in a record signed by himself, his clerk and anyone present during the search, and send the items together with the record to the Public Prosecutor’s Office.', 'en', 'Code of Criminal Procedure (Expanded), Article 101', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '102', 'Seals placed on seized items and items held in safekeeping may be broken only in the presence of the Investigating Judge, his clerk, the defendant or his advocate, and the person who searched his home or in whose presence the search was undertaken. If any of the aforementioned persons fails to appear, the seals shall be broken in their absence provided that they were informed of the time set for the procedure. The Investigating Judge may examine telegrams and correspondence and keep those which he deems necessary to shed light on the facts or which, if seen by third parties, might prove harmful to the investigation. He may not reveal the contents of any seized telegram or correspondence without the consent of the party concerned. The Investigating Judge may not examine correspondence between the defendant and his advocate.', 'en', 'Code of Criminal Procedure (Expanded), Article 102', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '103', 'If the Investigating Judge considers that the investigation will not be served by keeping some or all of the seized items, he shall return them to the legal claimant unless the claim is subject to a legal dispute. If there is a serious dispute regarding the right of ownership or possession of a seized item that may be returned, the Investigating Judge shall defer its return until the dispute has been settled. If the civil party or the defendant requests the return of a seized item, the Investigating Judge shall rule on the request after consulting the opposing party and the Public Prosecutor’s Office. An appeal against his decision in this regard may be filed within twenty-four hours of the date on which he informs the party to the dispute against whom the decision was taken.', 'en', 'Code of Criminal Procedure (Expanded), Article 103', 'Inheritance and succession', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '104', 'If the Investigating Judge wishes to search a residence located outside his area of jurisdiction, he shall seek the assistance of the Investigating Judge or the Single Judge in whose jurisdiction the residence is located. He shall describe the assignment clearly and in detail. The requested Judge shall undertake the assignment and abide by the rules governing the seizure of exhibits or items that may serve the purposes of the investigation. He shall compile a record thereof, sign it together with his clerk and the owner of the residence or two witnesses, and send it with the seized exhibits and items to the requesting Judge in a sealed envelope bearing the seal of his department, attaching a label listing the seized items.', 'en', 'Code of Criminal Procedure (Expanded), Article 104', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '105', 'Any search undertaken in breach of the rules set out above shall be null and void. Any investigative measures based thereon shall also be null and void. The nullity shall not preclude the use of information brought to light by the search for the purposes of the investigation if it includes supporting evidence. The measure shall not be null and void if the aggrieved party consents thereto. English version (STL Draft Official Translation of Arabic) Version 1.0 30 Chapter V Orders issued by the Investigating Judge during the investigation Section I Summonses, warrants to produce a person before the Judge and arrest warrants', 'en', 'Code of Criminal Procedure (Expanded), Article 105', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '106', 'The Investigating Judge may issue a summons to the civil party, defendant, witness, property administrator or surety to attend a hearing, specifying the date and time. The defendant shall proceed to the Investigating Judge’s department on being served with the summons and shall appear before him. If he fails to attend, without presenting a lawful excuse, or if the Investigating Judge fears that he may abscond, a warrant to produce him before the Judge shall be issued, containing a written order to the law enforcement authorities to ensure his presence within twenty-four hours of the date of the scheduled hearing. The Public Prosecutor’s Office shall execute the warrant to produce him before the Judge.', 'en', 'Code of Criminal Procedure (Expanded), Article 106', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '107', 'The Investigating Judge shall question the summoned defendant forthwith. A defendant against whom a warrant to be produced before the Judge has been issued shall be questioned within twenty-four hours of the time of execution of the warrant. – After twenty-four hours have elapsed, the chief of the police station shall automatically conduct the defendant to the Public Prosecutor, who shall request the Investigating Judge to question him. If the latter refuses, if he is absent or if he is precluded from questioning him by a lawful impediment, the Public Prosecutor shall request the First Investigating Judge to question him or to appoint an Investigating Judge to do so. If it proves impossible to question him, the Public Prosecutor shall order his immediate release. If he is held for more than twenty-four hours without being brought before the Public Prosecutor, the custody shall be deemed wrongful and the responsible officer shall be prosecuted for the offence of deprivation of personal liberty. – After questioning the defendant and consulting the Public Prosecutor’s Office, the Investigating Judge may issue an arrest warrant if the offence with which the defendant is charged is punishable by more than one year’s imprisonment or if he has a previous criminal conviction or has been sentenced to more than three months’ imprisonment without suspension. – The arrest warrant shall be based on a reasoned decision and the Investigating Judge shall state the factual and material grounds supporting his decision to issue the warrant, whether the reason is that pre-trial detention is the only way to preserve the evidence or the incriminating material traces, to prevent the coercion of witnesses or victims, or to prevent the defendant from communicating with accomplices or with accessories or inciters, or whether the purpose of the arrest is to protect the defendant himself, to terminate the impact of the offence or to prevent its recurrence, to prevent the defendan', 'en', 'Code of Criminal Procedure (Expanded), Article 107', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '108', 'Article 108 of this Code. The Public Prosecutor at the Court of Cassation may consult the case file and make such submissions and requests as he sees fit. The aggrieved party may bring a civil action following the public prosecution.', 'en', 'Code of Criminal Procedure (Expanded), Article 108', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '109', 'A person who is arrested pursuant to an arrest warrant issued in absentia shall be conveyed without delay to the Public Prosecutor’s Office in the department of the Investigating Judge who issued the warrant. The Public Prosecutor’s Office shall give the officer who enforced the warrant a certificate that it has received the arrested person. It shall have the latter conveyed to the place of detention and shall inform the Investigating Judge of the arrest. The Investigating Judge shall have the arrested person brought before him forthwith and shall question him in accordance with the provisions of Articles 74 et sequitur of this Code. Any law enforcement officer instructed to execute an arrest warrant shall enter the residence in which, according to the evidence, the person subject of the warrant has sought refuge. However, he may only effect such an entrance between 5 a.m. and 8 p.m. The rules set out in the previous paragraph shall be applied in enforcing a warrant to produce a person before the Judge. 1 Act No. 111 of 26 June 2010 amended article 108 of the Code of Criminal Procedure to include crimes of terrorism. English version (STL Draft Official Translation of Arabic) Version 1.0 32', 'en', 'Code of Criminal Procedure (Expanded), Article 109', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '110', 'The Investigating Judge may decide, in the course of the investigative proceedings, irrespective of the nature of the offence, to withdraw the arrest warrant issued in respect of the defendant with the consent of the Public Prosecutor provided that the defendant elects a domicile in the town or borough in which the office of the Investigating Judge is located if he has no actual domicile there, so that he may be notified of all measures pertaining to the investigation and to enforcement of the judgement.', 'en', 'Code of Criminal Procedure (Expanded), Article 110', 'Electoral', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '111', 'After consulting the Public Prosecutor’s Office, the Investigating Judge may, irrespective of the nature of the offence, release the defendant and place him under judicial supervision, with one or more of the following conditions that such supervision requires, notably: (a) To reside in a specified town, borough or village, not to leave it and to elect a domicile therein; (b) Not to frequent certain establishments or places; (c) To deposit his passport with the registry of the Investigation Department and to notify the Directorate-General of Public Security thereof; (d) To undertake not to move outside the area of supervision and to report regularly to the supervisory office; (e) Not to engage in certain occupational activities that the Investigating Judge has prohibited during the period of supervision; (f) To undergo regular examinations by physicians and experts during a period specified by the Investigating Judge; (g) To deposit surety, the amount of which shall be determined by the Investigating Judge. The Investigating Judge may vary the supervisory obligations as he sees fit. If the defendant breaches one of the supervisory obligations imposed on him, the Investigating Judge may decide, after consulting the Public Prosecutor’s Office, to issue an arrest warrant against him and to forfeit the surety to the Treasury.', 'en', 'Code of Criminal Procedure (Expanded), Article 111', 'Contracts and obligations', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '112', 'A defendant placed under judicial supervision may request that it be lifted. The Investigating Judge shall rule on his request, after consulting the Public Prosecutor’s Office, within a period not exceeding three days from the date on which it was recorded by the registry of the Investigation Department. His decision may be appealed before the Indictment Division, in accordance with the rules applicable to appeals against decisions by the Investigating Judge. Section II Release orders', 'en', 'Code of Criminal Procedure (Expanded), Article 112', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '113', 'Where an offence is a misdemeanour carrying a maximum penalty of two years’ imprisonment and the defendant is Lebanese and resident in Lebanon, he is entitled to be released five days after the date of his arrest provided that he has not previously been convicted of a heinous crime or sentenced to imprisonment for at least one year. The released defendant shall undertake to attend all proceedings pertaining to the investigation, the trial and enforcement of the judgement.', 'en', 'Code of Criminal Procedure (Expanded), Article 113', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '114', 'In the case of all other offences, if the conditions entitling the defendant to be released have not been met, the Investigating Judge may decide, after consulting the Public Prosecutor’s English version (STL Draft Official Translation of Arabic) Version 1.0 33 Office, to release him from detention, with or without surety, if he files an application and undertakes in the application to attend all proceedings pertaining to the investigation, the trial and enforcement of the judgement. – The surety shall include: (a) Attendance by the defendant at all proceedings pertaining to the investigation, the trial and enforcement of the judgement; (b) Fines, fees and judicial costs; (c) The costs advanced by the civil party; (d) A portion of the personal damages. The Investigating Judge shall specify the amount and type of surety and the sum payable for each constituent part. He may modify the amount or type if necessary.', 'en', 'Code of Criminal Procedure (Expanded), Article 114', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '115', 'The defendant or his advocate shall file the application for release with the Investigating Judge before the Investigating Judge’s order is delivered. A copy of the application shall be served on the civil party at his elected domicile so that he may make observations thereon within twenty-four hours of the date of notification. After a period of twenty-four hours has elapsed from the time of notification of the civil party, the application shall be referred to the Public Prosecutor for his opinion. The Investigating Judge shall take a decision in line with or contrary to that of the Public Prosecutor as soon as the file is returned to him.', 'en', 'Code of Criminal Procedure (Expanded), Article 115', 'Electoral', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '116', 'The civil party may file an appeal against the release order to the Indictment Division within twenty-four hours of the date on which he is notified thereof. The defendant may file an appeal against a decision to reject his release within twenty-four hours of the date on which he is notified thereof. – The Public Prosecutor’s Office may appeal the decision within twenty-four hours of the date on which it is delivered. – An appeal against the release order entails a stay of its enforcement. – The appeal shall be filed through the Investigating Judge. The released defendant is required to elect a domicile in the town or borough in which the Investigating Judge’s office is located if his actual domicile is not in that location.', 'en', 'Code of Criminal Procedure (Expanded), Article 116', 'Electoral', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '117', 'The surety may take the form of cash, state bonds, a bank or commercial guarantee, or a title to real property. – If it consists of cash or state bonds, it shall be deposited in the Palace of Justice vault and a receipt shall be issued. – If it consists of a bank guarantee, a letter of guarantee shall be issued by the insuring bank and duly incorporated in the case file. The basic record shall indicate the date and time of receipt, the name of the insuring bank, the amount indicated in the letter of guarantee and the record number of the letter. – If the surety consists of a commercial guarantee, a letter of guarantee shall be issued by the commercial body, be it an individual, an institution or a corporation. The basic record of the Investigating Judge shall record the name and address of the guarantor and the amount indicated in the English version (STL Draft Official Translation of Arabic) Version 1.0 34 letter of guarantee. In addition, a reference to the letter of guarantee shall be placed in the surety’s file in the commercial register. – If the surety consists of a title to real property, it shall be accompanied by a report compiled by a sworn expert containing the number of the property, its location and area, and a detailed estimate of its worth. A reference to this title shall be placed in the Land Registry journal. The original of the surety title and the report shall be deposited in the Palace of Justice vault. It shall be mentioned in the basic record. – The civil party and the defendant may, within the period prescribed in Article 116 of this Code, file an appeal against the part of the release decision relating to the amount of the surety.', 'en', 'Code of Criminal Procedure (Expanded), Article 117', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '118', 'If the released defendant attends the proceedings pertaining to the investigation, the trial and enforcement of the judgement, the first portion of the surety shall be reimbursed. If he fails to attend any of the investigative or trial proceedings or does not submit to enforcement of the judgement, the first portion of the surety shall be forfeited to the Treasury. – If it is decided to stay the prosecution of the defendant, the whole of the surety shall be reimbursed. – If it is decided to extinguish the public prosecution on account of his death, the first portion of the surety shall be paid to his estate. – If it is decided to drop the charge against him on the ground of a general amnesty or a pardon, the first portion of the surety shall be reimbursed. – If a dispute arises regarding the application of this article, it shall be settled in chambers by the judicial authority seized of the case or the authority that rendered the judgement, on the basis of an application from the person concerned.', 'en', 'Code of Criminal Procedure (Expanded), Article 118', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '119', 'The Public Prosecutor’s Office shall be responsible for implementing parts (a) and (b) of the surety, and parts (c) and (d) shall be implemented through the Enforcement Department after the final judgement.', 'en', 'Code of Criminal Procedure (Expanded), Article 119', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '120', 'If significant grounds for re-arresting the defendant arise after his release, the Investigating Judge may issue an arrest warrant after consulting the Public Prosecutor’s Office. If the order to release him was issued by the Indictment Division when the Investigating Judge’s decision to dismiss the application was set aside, the Investigating Judge shall submit the case file to the Indictment Division so that it may issue a ruling on the Judge''s decision to re-arrest the defendant. The enforcement of his decision shall not, however, be stayed on that account. If the Indictment Division decides to set aside his decision, it shall order that the defendant be released. Chapter VI Orders issued by the Investigating Judge on completion of the investigation', 'en', 'Code of Criminal Procedure (Expanded), Article 120', 'Termination of employment', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '121', 'On completing the investigation, the Investigating Judge shall transmit the case file to the Public Prosecutor''s Office so that it may present its final submissions. The Public Prosecutor’s Office shall present its submissions within a period not exceeding one week. If the Public Prosecutor’s Office requests further investigations, it shall specify the existing shortcomings and the investigative measures that it considers necessary. The Investigating Judge may decide to grant or reject the request. If he rejects it, he shall state the grounds for his rejection. The English version (STL Draft Official Translation of Arabic) Version 1.0 35 Public Prosecutor’s Office may appeal against the decision to reject it. If the Indictment Division sets the decision aside, it may either address the subject matter of the request, or it may refer the case file to the First Investigating Judge so that he may continue the investigation or entrust it to another Investigating Judge. If, however, it endorses the decision, it shall return the file to the Investigating Judge so that he may issue the indictment after the Public Prosecutor’s Office issues its final submissions.', 'en', 'Code of Criminal Procedure (Expanded), Article 121', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '122', 'If the Investigating Judge decides to stay the prosecution of the defendant, he shall base his decision on either a legal or factual ground. The ground shall be legal if there is no definition of the act charged under criminal law, if a new law was enacted after the charge was laid under which it is no longer characterized as an offence, if the definition of the act as an offence is no longer valid on a legally justifiable ground, or if the public prosecution in respect of the charge is extinguished on any of the legally established grounds of extinction. The ground is factual if the investigation fails to establish that the offence charged actually occurred, if there is no evidence of the existence of a causal link between the offence charged and the defendant, or if the public prosecution was brought against an unknown person and the investigation failed to detect him or to ascertain his identity. In the latter situation, the Investigating Judge shall issue a permanent wanted notice with a view to detecting the perpetrator or ascertaining his identity. If the Investigating Judge orders a stay of the prosecution in favour of the defendant, he shall order his immediate release if he is in custody. An appeal against this decision shall not stay its enforcement.', 'en', 'Code of Criminal Procedure (Expanded), Article 122', 'Family law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '123', 'If the Investigating Judge decides that the charge is a contravention or a misdemeanour that is not punishable by imprisonment, he shall immediately release the defendant if he is in custody and refer the case file to the Single Judge through the Public Prosecutor’s Office.', 'en', 'Code of Criminal Procedure (Expanded), Article 123', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '124', 'In a case involving an order regarding a misdemeanour or a contravention, the Public Prosecutor shall send the case file to the competent Single Judge within three days of the date on which it was filed with him, together with a list of the items compiled by the Investigation Department.', 'en', 'Code of Criminal Procedure (Expanded), Article 124', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '125', 'If the Investigating Judge considers that the act he has investigated amounts to a felony, he shall issue a decision setting out the facts of the case, the evidence available and the legal definition applicable thereto. He shall refer the file to the Public Prosecutor’s Office for transmission to the Indictment Division, which is the authority responsible for the indictment. If the Investigating Judge decides that the charge of a felony is not applicable to the facts of the case but that the charge of a misdemeanour is applicable, the Public Prosecutor may appeal his decision. The civil party is not entitled to appeal the decision.', 'en', 'Code of Criminal Procedure (Expanded), Article 125', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '126', 'The Investigating Judge’s order to refer the case to the Single Judge or to characterize the act as a felony shall contain the defendant’s family name and given names, his age, his place of birth, his parents’ names, his nationality, registration number, place of residence and occupation, and the date of his arrest and release, as well as a clear statement of the facts, the evidence and the legal characterization.', 'en', 'Code of Criminal Procedure (Expanded), Article 126', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '127', 'If new evidence comes to light following publication of the order to stay the prosecution of the defendant, the investigation shall be reopened if the order was based on a factual ground. English version (STL Draft Official Translation of Arabic) Version 1.0 36 New evidence shall consist of witness statements, or documents or records that were not in the possession of the Investigating Judge, but which might have affected the conclusion which he reached. The new evidence shall be submitted to the Public Prosecutor, who shall assess its usefulness and whether it is sufficient to warrant an application for the investigation to be reopened. If he considers that it serves the aforementioned purpose, he shall request the Investigating Judge to reopen the investigation. The Investigating Judge shall examine the new evidence and issue whatever orders he sees fit. He shall question the defendant without having a subsequent charge brought by the Public Prosecutor’s Office and shall abide by the applicable rules in his investigative work. If the Investigating Judge concludes, after resuming the investigation, that the order to stay prosecution should be reversed, he shall decide, after consulting the Public Prosecutor’s Office, to commit the defendant for trial or to characterize his act as a felony. If however the fresh investigation does not produce any evidence to necessitate the amendment of the first decision to stay prosecution, he shall issue an order that it should stand. If the order to stay the prosecution was issued by the Indictment Division, it shall provide for the reopening of the investigation on the basis of an application from the Public Prosecutor. The investigation shall be carried out by its President or by a Judge delegated by him in accordance with the rules applicable before the Investigating Judge. English version (STL Draft Official Translation of Arabic) Version 1.0 37 Part IV The Indictment Division', 'en', 'Code of Criminal Procedure (Expanded), Article 127', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '128', 'The Civil Division of the Appeal Court performs the functions of an Indictment Division, which include: 1. Serving as an indictment authority in the case of a felony; 2. Hearing appeals against orders of the Investigating Judge and against decisions that form part of its remit pursuant to special legislation; 3. Dealing with the right of a higher court to transfer a case pending before a lower court; 4. Ruling on applications for review. Chapter I The Indictment Division as an indictment authority', 'en', 'Code of Criminal Procedure (Expanded), Article 128', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '129', 'If the Investigating Judge considers in his final order that the act charged is a felony, he shall refer the case file to the Public Prosecutor’s Office for transmission to the Indictment Division. The Public Prosecutor’s Office shall prepare a report within five days containing its submissions. The civil party and the accused may present a submission within the same period setting out the facts of the case, the evidence, the legal definition and the grounds for their defence.', 'en', 'Code of Criminal Procedure (Expanded), Article 129', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '130', 'After the Public Prosecutor refers the case file, together with his report, to the Indictment Division, the latter shall deal with the case on the merits. If it considers that the investigation is complete and that any further investigations would serve no purpose, it shall issue one of the following orders: (a) An order to stay the prosecution of the defendant and to release him if it considers that there is insufficient evidence to charge him with the alleged felony, if the act attributed to him does not constitute an offence, if its characterization as an offence is no longer valid on a legally justifiable ground, if a new law has been enacted that amends the previous law, or if the public prosecution has been extinguished on any of the legally established grounds; (b) A decision to consider that the act constitutes a misdemeanour or a contravention entailing the referral of the defendant to the Single Criminal Judge and his release if the act is deemed to be a contravention or misdemeanour that is not punishable by more than one year’s imprisonment; (c) An order to indict the defendant if it ascertains that the facts and the evidence against him are sufficient to warrant the indictment after characterizing the act attributed to him as a felony. In its decision, the Indictment Division shall order the referral of the accused to a criminal court to be tried on the charges against him and shall issue an arrest warrant against him.', 'en', 'Code of Criminal Procedure (Expanded), Article 130', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '131', 'The indictment shall contain the names of the members of the Indictment Division, the submissions of the Public Prosecutor’s Office, a clear and detailed account of the facts of the case, an itemized list of the evidence of the link between the offence and the act charged, a reasoned legal description, a citation of the legal provisions applicable to the facts and a draft of the arrest warrant. It shall also contain the family name and first name of the accused, his date of birth, his parents’ names, his civil register number, place of residence and nationality, the date of his arrest and that of his release, where relevant. English version (STL Draft Official Translation of Arabic) Version 1.0 38 – The President of the Division and the two Judges shall sign the indictment. The arrest warrant shall contain the family name and first name of the accused, his date of birth, his parents’ names, his place of residence, occupation and nationality, the felony with which he is charged, the legal provision applicable thereto, and the order issued to the law enforcement authorities to arrest him. If the Indictment Division issues an order to refer the accused to a criminal court and no arrest warrant has yet been issued, it may still issue the warrant on the basis of a request from the Public Prosecutor’s Office.', 'en', 'Code of Criminal Procedure (Expanded), Article 131', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '132', 'If the Indictment Division ascertains that the investigation is incomplete or unclear, its President shall conduct a supplementary investigation or instruct one of the Judges to do so. The supplementary investigation shall comply with the rules governing the Investigating Judge’s work in that regard. Once the supplementary investigation has been completed, the case file shall be referred to the Public Prosecutor’s Office so that its submission may reflect the new evidence. The Indictment Division shall then issue the appropriate ruling thereon.', 'en', 'Code of Criminal Procedure (Expanded), Article 132', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '133', 'The Indictment Division shall issue a single indictment for joint offences. Even if some of the offences are misdemeanours, the entire case shall be referred to a criminal court. The following are considered joint offences: (a) Offences committed by several persons jointly at one time; (b) Offences committed by a number of persons at different times and in different places by common accord; (c) Offences committed to prepare, facilitate or execute other offences, to eliminate the traces of the offences, or to prevent the perpetrators from being prosecuted; (d) Offences where several persons are involved in concealing evidence of the crime, wholly or in part.', 'en', 'Code of Criminal Procedure (Expanded), Article 133', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '134', 'The Indictment Division may, irrespective of the decisions of the Investigating Judge referred to it, examine all the felonies as well as the misdemeanours joined thereto, of its own motion or pursuant to a request from the Public Prosecutor, and shall take an appropriate decision thereon. – It may undertake a supplementary investigation, of its own motion or pursuant to a request from the Public Prosecutor, the defendant or the civil party. Chapter II The Indictment Division as an appeals authority', 'en', 'Code of Criminal Procedure (Expanded), Article 134', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '135', 'The Indictment Division serves as the appeals authority for any appeal against the decisions of the Investigating Judge. 1. The Public Prosecutor’s Office may appeal against all decisions resulting from the investigation that are contrary to its motions, be they administrative, investigative or judicial, and against a decision by the Judge to withdraw the detention order because the requisite conditions have not been met, within twenty-four hours of the date of issue of the order. English version (STL Draft Official Translation of Arabic) Version 1.0 39 2. The defendant may appeal against the following decisions of the Investigating Judge: (a) A decision to reject the application for his release; (b) A decision to dismiss any of the objections raised under Article 73 of this Code. 3. The civil party may appeal against the following decisions: (a) A decision by the Judge to accept one or more objections raised under Article 73 of this Code if they are prejudicial to his interests; (b) A decision by the Judge to leave the defendant at liberty or to release him by right or on bail; (c) An order to stay the prosecution of the defendant; (d) A decision by the Judge to characterize the charge as a contravention; (e) A decision by the Judge to withdraw the arrest warrant in respect of the defendant on account of a breach of the rules in force. The property administrator or the surety may not appeal against the Investigating Judge’s decisions except for the final decision regarding jurisdiction. – The time limit for the appeal is twenty-four hours. It shall begin to run for the civil party, the defendant, the property administrator and the surety on the date of notification at his elected domicile within the town in which the Investigating Judge’s office is located if he has no actual residence there.', 'en', 'Code of Criminal Procedure (Expanded), Article 135', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '136', 'The appeal shall be filed directly with the Indictment Division or through the Investigating Judge. The Indictment Division shall rule on the appeal against the Investigating Judge’s decision within a period not exceeding ten days from the time of its filing.', 'en', 'Code of Criminal Procedure (Expanded), Article 136', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '137', 'An appeal filed before the Indictment Division entails a transfer of jurisdiction in respect of its substance. If the appeal is filed within the legal time limit, and specifies the legal grounds and the submission of the appellant bears the signature of counsel at the Appeal Court, the Indictment Division shall rule that the appeal is procedurally admissible and shall decide, on the merits, to uphold, set aside or amend the appealed decision. An appeal filed by the civil party against the decision to stay the prosecution of the defendant leads to the resumption of the public prosecution and its referral to the Indictment Division. If the Indictment Division decides to stay the defendant’s prosecution, he may file an application for damages in accordance with the provisions of Article 72 of this Code.', 'en', 'Code of Criminal Procedure (Expanded), Article 137', 'Narcotics', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '138', 'If the Public Prosecutor’s Office or the civil party appeals against the Judge’s decision to release the defendant, to leave him at liberty or to withdraw the arrest warrant on account of a breach of the rules, the appeal shall stay enforcement of the decision pending a ruling, which shall be made within twenty-four hours. If this period elapses without a decision by the Indictment Division, the Public Prosecutor shall automatically release him.', 'en', 'Code of Criminal Procedure (Expanded), Article 138', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '139', 'If the Indictment Division sets aside the Investigating Judge’s decision to leave the defendant at liberty, it may issue an arrest warrant against him. English version (STL Draft Official Translation of Arabic) Version 1.0 40 If the Division sets aside the Investigating Judge’s decision to dismiss the application for the defendant’s release, the released person shall elect a domicile in the town or borough in which the Indictment Division is located if his actual residence is not located there. Chapter III The right of transfer', 'en', 'Code of Criminal Procedure (Expanded), Article 139', 'Termination of employment', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '140', 'If the Investigating Judge issues a decision in which he ascertains that the charge is a felony, the Indictment Division may, without requiring a charge to be brought by the Public Prosecutor’s Office, examine all the offences disclosed during the investigation and joined to the original offence and may investigate all persons concerning whom there is evidence of involvement in the offences. In the case of offences that are not joined to the original offence, the initiation of the public prosecution shall require charges to be brought by the Public Prosecutor’s Office. If the indictment sets aside on appeal a decision whereby the Investigating Judge refused to take a step or to undertake an investigation, the Division shall take the step or undertake the work instead of the Investigating Judge and may decide the merits of the case itself. If it sets aside on appeal a decision of the Investigating Judge to stay the prosecution or to refrain from proceeding with the case on one or more of the grounds set out in Article 73 of this Code, it may decide the merits of the case itself. If the Indictment Division does not decide the merits of the case itself, it shall refer it to the First Investigating Judge so that he may continue investigating it or refer it to another Investigating Judge.', 'en', 'Code of Criminal Procedure (Expanded), Article 140', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '141', 'If the Indictment Division decides the merits of the case, it shall undertake the investigations and issue a summons or an arrest warrant, as the circumstances require, and may assign this duty to one of its members. The investigations conducted by the President of the Indictment Division or the delegated Judge shall be governed by the same rules as those applicable to the investigation by the Investigating Judge. Either of them may delegate some of the investigative work to an Investigating Judge or a Single Judge, in accordance with the provisions governing the delegation of powers issued by the Investigating Judge.', 'en', 'Code of Criminal Procedure (Expanded), Article 141', 'Taxation', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '142', 'Once the investigations conducted by the Indictment Division itself or through one of its members are completed, it shall return the case file to the Public Prosecutor’s Office so that it may revise its submissions with respect to the merits of the case. It shall then deliver its decision after examining the details of the case and the supplementary investigations.', 'en', 'Code of Criminal Procedure (Expanded), Article 142', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '143', 'Appeals against decisions of the Indictment Division before the Court of Cassation are permissible only on the grounds set forth in Articles 206 and 207 of this Code. – The time limit for an appeal against decisions of the Indictment Division is fifteen days. It shall begin to run for the Public Prosecutor’s Office on the date of its delivery and for the civil party, the defendant, the property administrator and the surety, on the date of notification pursuant to the rules laid down in Articles 147 and 148 of this Code; it shall be deemed to have been notified if it is ascertained that the person concerned obtained knowledge thereof. English version (STL Draft Official Translation of Arabic) Version 1.0 41 Chapter IV Decisions on applications for rehabilitation', 'en', 'Code of Criminal Procedure (Expanded), Article 143', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '144', 'Any person convicted of a felony or misdemeanour is eligible for rehabilitation. The relevant decision shall be issued by the Indictment Division with jurisdiction in the place of residence of the convicted person on the basis of an application from the person concerned. Applications for rehabilitation in accordance with Articles 159 and 160 of the Criminal Code shall comply with the following rules: (a) The convicted person shall file an application for rehabilitation to the Indictment Division; He shall attach thereto a copy of the judgement delivered against him and a copy of his criminal record issued not more than one month prior to the date on which the application is filed. (b) The Indictment Division shall designate one of its members to ascertain whether the application meets the legal conditions and to report thereon to the Indictment Division. The Indictment Division shall transmit the application, together with the report, to the Public Prosecutor’s Office so that it may prepare its submission.', 'en', 'Code of Criminal Procedure (Expanded), Article 144', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '145', 'If the Indictment Division decides to approve the application, it shall submit a certified copy of its decision to the Appeal Court Prosecutor, who shall communicate it to the Judicial Records Department for implementation.', 'en', 'Code of Criminal Procedure (Expanded), Article 145', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '146', 'If the Indictment Division decides to reject the application for rehabilitation, the person who filed the application may not file another application until six months have elapsed from the date on which he was notified of the rejection. English version (STL Draft Official Translation of Arabic) Version 1.0 42 Part V Rules governing the service of legal documents and decisions', 'en', 'Code of Criminal Procedure (Expanded), Article 146', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '148', 'If the person to be served with a document has no known place of residence or domicile, or if the process server does not find anyone who can be served with the document at his place of residence or domicile, he shall be notified through the posting of a copy of the document at the entrance to his last known place of residence; a second copy thereof shall be communicated to the local mayor, and a third copy shall be posted at the entrance to the judicial authority that ordered the English version (STL Draft Official Translation of Arabic) Version 1.0 43 notification. These measures shall be recorded by the process server on the original copy of the document, which shall be returned to the relevant authority. If the person to be served with a document has no known last place of residence, it shall suffice for the process server to post a copy of the document at the entrance to the judicial authority that ordered the notification.', 'en', 'Code of Criminal Procedure (Expanded), Article 148', NULL, 'Criminal Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CRIM-002-EXPANDED', '149', 'The document shall be served at least three days prior to the date on which the addressee is required to appear before the judicial authority that ordered notification, unless a contrary legal provision is applicable. If the document is to be served on a person living in a foreign country, it shall be served by means of a registered letter with acknowledgement of receipt, through the Lebanese embassy or consulate in the country concerned, or in accordance with the rules applicable under local legislation. If it proves impossible to serve the document, the court may take it that the person to be served with the document has no known place of residence and it shall be served in accordance with the provisions of Article 148 of this Code. If the notification measures, including the time limit, are not complied with, the judicial authority shall declare the document to be served null and void if the addressee fails to appear and to serve the document again in accordance with Article 148 of this Code. If he appears and requests that the hearing be deferred before raising any plea pertaining to the case, the Judge seized of the case shall order its deferral and shall inform him of the date; in the absence of such a request, he shall be deemed to have been notified. If the judicial authority declares that the service of the document is null and void on account of an act attributable to the process server, the latter may be fined a sum equivalent to the costs of serving the document and shall, if necessary, be required to pay damages to the aggrieved party. When calculating the time limit for service of the document, the time and day of service shall not be taken into account. If the time limit expires on a public holiday or outside official working hours, the time limit shall be extended until the next working day. English version (STL Draft Official Translation of Arabic) Version 1.0 44 Part VI Trial courts Chapter I The Single Criminal Judge Section I Referr', 'en', 'Code of Criminal Procedure (Expanded), Article 149', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '150', 'The Single Judge hears cases involving misdemeanours and contraventions, with the exception of offences to which special legal provisions are applicable. The Public Prosecution Service is not represented before him.', 'en', 'Code of Criminal Procedure (Expanded), Article 150', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '151', 'Cases are referred to the Single Judge in one of the following ways: (a) Charges laid by the Public Prosecutor’s Office; (b) Charges laid directly by the victim, who assumes the status of a civil party; (c) An indictment decision by the Investigating Judge or the Indictment Division; (d) An application for damages on the ground of a stay of prosecution, acquittal or discharge; (e) A decision to designate a judicial authority or to transfer the case; (f) Commission of a misdemeanour during a trial hearing; (g) Contraventions for which a penalty notice has been issued.', 'en', 'Code of Criminal Procedure (Expanded), Article 151', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '152', 'The Public Prosecutor brings charges of a misdemeanour before the Single Judge in cases involving a person whose identity has been ascertained. The statement of charges contains a description of the misdemeanour with which he is charged and the place in which it was committed and is accompanied by the record of the preliminary investigations, the complaint, and all documents supporting the prosecution. The Public Prosecutor may subsequently bring charges against a person whom he failed to charge so long as the case remains pending before the Single Judge. The latter may draw his attention to his failure to bring charges against a person against whom evidence exists, but he is not bound to do so. The Public Prosecutor may ask to examine the case file, provided that he returns it not more than three days after the date on which it is entrusted to him. The Public Prosecutor shall sign the document containing his charges and he may not withdraw it or drop the charges. He may not charge a person with an offence before the Single Judge if he has already charged the person with the same offence before the Investigating Judge.', 'en', 'Code of Criminal Procedure (Expanded), Article 152', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '153', 'If a person is caught in the act of committing a misdemeanour that is punishable with imprisonment, he shall be brought before the Public Prosecutor, who shall question him, charge him and refer him to the Single Judge, who shall deliver a ruling that day or on the following day in English version (STL Draft Official Translation of Arabic) Version 1.0 45 accordance with Article 108 of this Code. Before referring the case to the Single Judge, the Public Prosecutor may issue an arrest warrant, which shall be enforced forthwith. If the defendant requests a deferral in order to appoint an advocate, the Single Judge shall grant him a period of three days for this purpose, which is non-renewable. In the case of a misdemeanour discovered during its commission or immediately afterwards, the Public Prosecutor shall record the names of the witnesses. The Single Judge may summon them orally to a hearing through the Judicial Police force, the law enforcement authorities or the bailiffs’ office. If one of them fails to appear, the Single Judge may issue an order to have him produced before him.', 'en', 'Code of Criminal Procedure (Expanded), Article 153', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '154', 'If the Single Judge ascertains that the case pertaining to an offence discovered at the time of its commission or immediately afterwards is not ready for trial, he shall order its deferral for a period not exceeding ten days. He may release the defendant of his own motion in the absence of a civil action or in response to a petition from the defendant, with or without surety, if he finds that there is no need to remand him in custody, provided that the released defendant elects a domicile in the town or borough in which the Single Judge’s office is located. In such cases he may, if he considers it necessary, issue a travel ban for a period not exceeding two months. If the defendant files an application for release, a copy of his application shall be served on the civil party at his actual place of residence within the area of jurisdiction of the Single Judge or at his elected domicile, and he shall submit his observations thereon within twenty-four hours of the date of service. The Single Judge shall decide whether to grant or reject the application within a similar time limit. The civil party and the defendant may file an appeal against the Single Judge’s decision before the Appeal Court within twenty-four hours of the date of notification. The Public Prosecutor’s Office may file an appeal against it within twenty-four hours of the date of its delivery.', 'en', 'Code of Criminal Procedure (Expanded), Article 154', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '155', 'The victim of a misdemeanour may file a direct complaint and assume the status of a civil party before the Single Judge with jurisdiction over the area in which the offence was committed, the place of residence of the defendant, or the place in which he was arrested. The complaint shall be recorded in the registry of the Single Judge, who shall require the complainant to pay an advance in respect of legal fees and costs, which shall not exceed one per cent of the cost of the proceedings. In addition, he shall instruct the complainant, if he is a foreign national, to present surety and shall determine its nature and scale in his decision. The Judge may exempt the complainant from paying an advance if he is financially unfit to do so. He may also exempt a foreign complainant from paying surety on the same ground by a reasoned decision. Public prosecutions are initiated by a complaint filed by a complainant who acquires the status of a civil party and who makes the required payment, unless exempted therefrom. If either of these two conditions is not met, it shall be deemed to constitute a report. In such cases, the Judge shall order its referral to the Public Prosecutor for a decision on whether to initiate a public prosecution. The complainant may withdraw the civil action. If he does so within two days of the date of filing his complaint, he shall not be liable for the costs of withdrawal. His withdrawal shall not affect the course of the public prosecution, except in cases where the extinction of the civil action leads to the extinction of the public prosecution. English version (STL Draft Official Translation of Arabic) Version 1.0 46 If the public prosecution is initiated by charges brought by the Public Prosecutor’s Office, the victim may file a petition to exercise the incidental personal rights to which he is entitled. In all cases, the civil party shall elect a domicile in the town or borough in which the court is located and shall inform the cou', 'en', 'Code of Criminal Procedure (Expanded), Article 155', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '156', 'The Single Judge shall schedule a hearing and summon the civil party, the defendant, the witnesses, the property administrator and the surety to attend. – The Single Judge shall serve the defendant with a copy of the direct complaint together with its attachments at least three days before the date of the hearing.', 'en', 'Code of Criminal Procedure (Expanded), Article 156', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '157', 'The defendant, or his advocate in the absence of the defendant, may: 1. Raise one or more of the objections provided for in Article 73 of this Code prior to being questioned; The Single Judge shall serve the civil party with a copy of the submission filed by the defendant or his advocate in this regard and shall allow him a period of not more than five days to respond thereto. On expiry of this period, he shall rule on the objection raised. The Public Prosecutor may file an appeal against this ruling within twenty-four hours of the date of its delivery. The defendant and the civil party or their respective advocates may file an appeal against the ruling within twenty-four hours of the date of notification. 2. Apply for a stay of execution of the arrest warrant issued in absentia by the Investigating Judge against him until a judgement is delivered. – The Judge may decide to stay the enforcement of the arrest warrant issued in absentia, with or without surety, on condition that the defendant undertakes to attend the trial hearings. If he fails to attend any hearing without a lawful excuse, the Judge may reverse his decision to stay enforcement. – The decision to stay execution, or to reverse that decision, is not open to any kind of review.', 'en', 'Code of Criminal Procedure (Expanded), Article 157', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '158', 'If the Investigating Judge decides to charge the defendant with a misdemeanour or contravention, the Public Prosecutor’s Office shall refer the case file to the Single Judge within three days of receiving it, unless an appeal is filed against the indictment decision. An indictment decision issued by the Indictment Division shall also be referred to him within the same time limit. The Single Judge shall deal with the case on the basis of the indictment decision.', 'en', 'Code of Criminal Procedure (Expanded), Article 158', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '159', 'If the Investigating Judge decides to stay the prosecution of the defendant on a legal or factual ground, the defendant may apply for an award of damages against the civil party before the Single Criminal Judge with jurisdiction pursuant to Article 72 of this Code.', 'en', 'Code of Criminal Procedure (Expanded), Article 159', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '160', 'The Single Judge shall hear a case referred to him by a decision of a Criminal Division of the Court of Cassation pursuant to a decision designating a judicial authority or a decision to transfer the case. If the Criminal Division of the Court of Cassation decides to quash the Single Judge’s decision declaring that he lacks jurisdiction to hear the case, the case shall be returned to him or referred to another Single Judge within the same jurisdictional area. English version (STL Draft Official Translation of Arabic) Version 1.0 47', 'en', 'Code of Criminal Procedure (Expanded), Article 160', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '161', 'If a misdemeanour occurs during a court hearing before the Single Judge, he shall record it forthwith, question the perpetrator and, if applicable, hear the witnesses. He shall impose the penalty applicable to the misdemeanour at the same hearing. If he decides to impose a term of imprisonment, he may issue an arrest warrant against the convicted person to be executed forthwith. This decision is open to appeal. If the act committed during the hearing constitutes a felony, he shall order the arrest of the perpetrator and compile a report setting out the facts for transmission to the Public Prosecutor’s Office, together with a notice regarding the perpetrator’s arrest.', 'en', 'Code of Criminal Procedure (Expanded), Article 161', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '162', 'The Single Judge shall deal with contraventions in respect of which a penalty notice has been issued by officers authorized by law to issue such notices and transmit them to the court exercising jurisdiction. Section II Rules governing proceedings before the Single Criminal Judge', 'en', 'Code of Criminal Procedure (Expanded), Article 162', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '163', 'When the case file arrives at the department of the Single Judge, the clerk of the court shall register it and the Judge shall set a time for the hearing. The clerk shall prepare notices for the plaintiff, the defendant, the property administrator and the surety and arrange to have them served. Notice shall be served on each of them three days before the opening of the proceedings. The Judge may decide in urgent cases to reduce the time limit. If one of the aforementioned persons appears at the court, after being informed of the time of the hearing, he may not claim that he was not served with notice thereof or that the time limit of three days was not respected.', 'en', 'Code of Criminal Procedure (Expanded), Article 163', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '164', 'Subject to the provisions of Article 165 of this Code, a defendant who has been notified of the time of a hearing shall present himself at the court in person. If the defendant is a legal person, its legal representative or an advocate instructed as counsel shall attend the hearing.', 'en', 'Code of Criminal Procedure (Expanded), Article 164', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '165', 'The defendant shall attend himself or be represented by his advocate if the maximum penalty carried by the offence with which he is charged does not exceed one year’s imprisonment. In such cases, the trial shall be deemed to have been conducted adversarially. If he is neither present himself nor represented by an advocate, he shall be tried in absentia. If the Judge finds that the defendant should be present in person, he shall notify him through his advocate of the date of the hearing at which he is to be questioned, specifying the day and time. If the defendant fails to attend the hearing, the Judge may draw an inference from his absence as evidence of the veracity of the charge against him. If the offence with which the defendant is charged carries a penalty of more than one year’s imprisonment and he fails to appear despite having been notified of the time of the hearing, he shall be tried in absentia.', 'en', 'Code of Criminal Procedure (Expanded), Article 165', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '166', 'If a defendant who is in custody has been notified of the time of the hearing and fails to appear without a lawful excuse, he shall be tried in absentia.', 'en', 'Code of Criminal Procedure (Expanded), Article 166', 'Family law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '167', 'If the offence with which the defendant is charged is fully covered by an amnesty, he may be represented by an advocate at the trial. English version (STL Draft Official Translation of Arabic) Version 1.0 48', 'en', 'Code of Criminal Procedure (Expanded), Article 167', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '168', 'The civil party, the property administrator and the surety may be represented at the trial by an advocate. If the civil party fails to attend the trial without a reasonable excuse and is not represented by counsel although he was duly notified, the proceedings shall be conducted in his absence and the public prosecution shall proceed. He may not raise an objection to the judgement delivered at the conclusion of the proceedings, but he may appeal against it. If the civil party attends one trial hearing at which he presents his claims and fails to attend the other hearings without a reasonable excuse, the court may award him personal compensation and conduct the trial in his absence as though it were adversarial. If the property administrator or the surety fails to attend the trial, is not represented by counsel and presents no reasonable excuse although he was duly notified, the trial shall be conducted in his absence. He may not raise an objection to the judgement delivered, but he may appeal against it.', 'en', 'Code of Criminal Procedure (Expanded), Article 168', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '169', 'If the defendant attends the opening of the trial hearing and fails to attend the subsequent hearings without presenting a reasonable excuse, the trial shall be deemed to have been conducted adversarially.', 'en', 'Code of Criminal Procedure (Expanded), Article 169', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '170', 'If the defendant is unable to attend the trial on a major health ground and it is impossible for certain reasons to defer the trial, the Single Judge may proceed to the place where he currently resides twenty-four hours after notice is served on him of the decision to question him. A record shall be made of the measures taken and the Judge shall sign it on each page, together with his clerk and the defendant. If the defendant is absent from the trial after this questioning and the excuse on health grounds is still valid, he may be represented by counsel. Otherwise, his trial shall be deemed to be adversarial. The civil party or his advocate may be present during these proceedings, having been duly notified of the appointed time. Section III Objection to a judgement delivered in absentia', 'en', 'Code of Criminal Procedure (Expanded), Article 170', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '171', 'A convicted person shall be notified of a judgement delivered in absentia in accordance with the rules governing notification laid down in this Code before a summary of the judgement is sent for enforcement. The judgement delivered against the convicted person shall not be enforced until he has been notified in accordance with the rules laid down in Articles 147 et sequitur of this Code. The person convicted in absentia may file an objection to the judgement delivered in absentia, within ten days of the date on which he was notified thereof, in the form of a motion to the court that delivered the judgement. If the notice served fails to comply with the above-mentioned provisions, he may file an objection thereto during the prescription period applicable to the penalty imposed. If a convicted person is not notified of a judgement delivered in absentia, the judgement shall be deemed to constitute the final judicial procedure, and the prescription period with respect to the public prosecution shall begin to run on the date of its delivery.', 'en', 'Code of Criminal Procedure (Expanded), Article 171', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '172', 'The civil portion of the judgement delivered in absentia shall be confirmed as soon as the notification formalities have been completed in accordance with the rules laid down in the Code of Civil Procedure. The beneficiary of an award of personal damages shall receive a copy of the English version (STL Draft Official Translation of Arabic) Version 1.0 49 judgement that is enforceable pursuant to the provisions governing the enforcement of civil judgements. If, following an appeal against the judgement delivered in absentia the convicted person is acquitted or the proceedings have been declared null and void and the civil portion of the judgement has been enforced, the convicted person may file an application for return of the confiscated amounts by the executor, and for damages.', 'en', 'Code of Criminal Procedure (Expanded), Article 172', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '173', 'A person convicted in absentia may file an objection to the judgement delivered in absentia as a whole or only to the civil obligations and damages awarded. The person making the objection may attend the hearings himself or appoint an advocate to attend on his behalf if the sentence imposed does not exceed one year’s imprisonment, or if his objection only concerns the civil portion of the judgement and damages awarded. If he attends and if his objection was filed within the legal time limit and in compliance with the applicable formal requirements, the Judge shall order the annulment of the judgement delivered in absentia and shall deem it to be non-existent. There shall be a re-trial in accordance with the normal rules. If the person making the objection fails to attend the first hearing without a reasonable excuse, the Judge shall order the formal dismissal of the objection, taking into consideration the provisions of the second paragraph of this article. No objection may be raised to this ruling, but the first judgement delivered in absentia is open to appeal. The time limit for filing an appeal begins to run on the date of notification of the judgement resulting from the objection.', 'en', 'Code of Criminal Procedure (Expanded), Article 173', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '174', 'If the objection raised by the defendant is found to be justified, he shall be exempted from payment of the costs of the proceedings conducted in absentia. Otherwise he shall be liable for payment. Where the court orders the formal dismissal of the objection, it may sentence the objector to a fine of between five hundred thousand and one million Lebanese pounds. Section IV Judicial proceedings and authentication of evidence before the Single Judge', 'en', 'Code of Criminal Procedure (Expanded), Article 174', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '175', 'The Single Judge has ratione personae jurisdiction only, i.e. with respect solely to the persons charged. He may not include other persons unless charges are filed against them subsequently prior to the disposal of the case. Where there are charges against persons other than the defendants, he shall prepare a report on the matter and transmit it to the Public Prosecutor without delay.', 'en', 'Code of Criminal Procedure (Expanded), Article 175', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '176', 'The Single Judge examines the facts set out in the Public Prosecutor’s Office’s statement of charges, the direct complaint of the victim, or the indictment decision. He may raise an objection to circumstances and facts associated with the offence charged that were liable to influence its classification. The Single Judge is not bound by the legal definition of the offence charged. If he considers that the offence charged constitutes a felony, he shall declare his lack of jurisdiction to hear the case. English version (STL Draft Official Translation of Arabic) Version 1.0 50', 'en', 'Code of Criminal Procedure (Expanded), Article 176', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '177', 'If the Single Judge declares that he lacks jurisdiction on the ground that the charge laid constitutes a felony, the case file shall be referred to the Public Prosecutor’s Office. He may issue an arrest warrant against the defendant if the case was brought directly before him. If it was referred to him pursuant to a statement of charges by the Public Prosecutor’s Office or by the Investigating Judge, he shall simply declare that he lacks jurisdiction and refer the case to the Public Prosecutor’s Office.', 'en', 'Code of Criminal Procedure (Expanded), Article 177', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '178', 'The judicial proceedings shall be public and oral on pain of nullity unless the Single Judge decides to hold them in camera to preserve law and order or public morals. Minors may be barred from the courtroom in all cases.', 'en', 'Code of Criminal Procedure (Expanded), Article 178', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '179', 'The offences charged can be proved on the basis of sufficient proof if there is no legal provision to the contrary. The Judge shall base his judgement solely on the evidence in his possession, and which was discussed adversarially during the proceedings. The Judge shall assess the evidence with a view to arriving at a firm personal conviction.', 'en', 'Code of Criminal Procedure (Expanded), Article 179', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '180', 'At the opening of the proceedings, the clerk shall read out the charges laid by the Public Prosecutor’s Office, the indictment decision of the Investigating Judge or a summary of the facts contained in the direct complaint. He shall then provide an account of the evidence against the defendant. The Judge shall hear the testimony of the civil party or his counsel. He shall then question the defendant in the presence of his counsel if he has appointed an advocate to assist him during the proceedings. If the defendant refuses to answer and remains silent, the Judge and the civil party may not compel him to speak. The Judge may not make an adverse inference from his silence.', 'en', 'Code of Criminal Procedure (Expanded), Article 180', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '181', 'The parties to the case may request to call witnesses, and the Single Judge may call any witness if he considers that it would be useful to hear his testimony. Before giving evidence, the witness shall swear the following oath: “I swear by almighty God to tell the truth and nothing but the truth.” Note shall be taken of this oath in the record of the proceedings. When the Judge has finished hearing the witness, the civil party or his counsel and the defendant or his counsel may put questions to him regarding the case through the Judge. The Judge may refuse to put a question if he considers that it serves no purpose. If the party insists on raising it, he shall record the question and his decision to reject it. A summons shall be served on each witness three days before the date of the hearing. If a witness appears in court of his own accord having been made aware that he has been summoned,, he may not file a claim regarding failure to serve him with a summons or failure to comply with the three-day time limit.', 'en', 'Code of Criminal Procedure (Expanded), Article 181', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '182', 'The witness shall be heard by the Judge after he has ordered the other two witnesses to withdraw. Before having him take the oath referred to in the preceding article, the Judge shall ask him to state his family name and first name, his date of birth, his parents’ names, his nationality, civil register number, his occupation and his domicile, and whether he is linked to the defendant by ties of kinship or by enmity. As a matter of principle, testimony given by ascendants and descendants of the defendant, his brothers and sisters, persons of equivalent kinship through marriage, and his husband and wife, even after divorce, is inadmissible. The Judge may hear their testimony if the civil party or the defendant does English version (STL Draft Official Translation of Arabic) Version 1.0 51 not object, and the testimony shall not be void. However, if one of them raises an objection, this shall not preclude the Judge from hearing them as a source of information. Testimony given by a minor under 18 years of age shall be admissible only as a source of information. A minor under 7 years of age shall be heard only as a source of information and on the basis of a reasoned decision.', 'en', 'Code of Criminal Procedure (Expanded), Article 182', 'Family law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '183', 'If a witness fails to appear at the hearing in spite of being duly served with a summons and does not present a reasonable excuse, the Judge may sentence him to a fine of between 100,000 and 500,000 Lebanese pounds. A witness who has been fined may request the Judge to exempt him from payment if he presents a lawful excuse. The Judge may issue a warrant requiring a witness who fails to appear on being notified for the second time to be produced before him, even if has already ordered him to pay a fine.', 'en', 'Code of Criminal Procedure (Expanded), Article 183', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '184', 'The Judge may decide, of his own motion or in response to a petition by one of the parties to the case, to call any witness who is present in the courtroom. If the witness is not proficient in the Arabic language, or if he is deaf or mute, the Investigating Judge shall appoint an interpreter who shall take an oath to perform his duties honestly and with integrity.', 'en', 'Code of Criminal Procedure (Expanded), Article 184', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '185', 'The testimony shall consist of the facts and circumstances of the offence charged and the part played by the defendant. If a witness who is summoned to appear before the Single Judge is the person who reported the offence to the competent authority, the Judge shall draw attention to that fact before hearing his testimony. If the witness is an informant who reported the offence in return for a reward, the Judge may hear him as a source of information.', 'en', 'Code of Criminal Procedure (Expanded), Article 185', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '186', 'The witness shall deliver his testimony orally. He may not be interrupted by the plaintiff, the defendant, or counsel for either party. – The witness may ask the Judge’s permission to consult records or documents when delivering his testimony. – The Judge may ask the witness to remain outside the courtroom after hearing him so that he may summon him for a second hearing, or to confront him with other witnesses. – The Judge shall show the witness the exhibits and probative material and question him about them. He may read to him the statement he made during the preliminary investigation or interview and question him about it and if he confirms it.', 'en', 'Code of Criminal Procedure (Expanded), Article 186', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '187', 'The parties to the case may not object to the hearing of a witness who has already started his testimony after taking an oath. A statement by one defendant against the other perpetrators of the offence shall not constitute sufficient evidence of a probative nature. It is for the Judge to assess it in the light of the evidence in his possession. English version (STL Draft Official Translation of Arabic) Version 1.0 52', 'en', 'Code of Criminal Procedure (Expanded), Article 187', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '188', 'If it appears that the witness is giving false testimony, the Judge shall instruct the law enforcement authorities to detain him at the police station and shall submit a report on the matter to the Public Prosecutor, stating that the witness has been detained. The Public Prosecutor may prosecute the witness for the offence of perjury in accordance with the relevant rules.', 'en', 'Code of Criminal Procedure (Expanded), Article 188', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '189', 'The witness shall sign the record of his statement after it is read to him.', 'en', 'Code of Criminal Procedure (Expanded), Article 189', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '190', 'The records and reports contained in the case file shall have probative value only if they are formally sound and the person who compiled them did so in performance of his duties and within the bounds of his competence, setting down what he witnessed, heard or investigated himself. If the law requires that the record be deemed valid unless there is proof that it has been forged, the Judge shall take it into account. He shall not permit the presentation of contrary evidence of a personal nature. If under law the record has probative value until there is evidence of the contrary, the defendant may attempt to prove the contrary through written evidence or by means of testimony.', 'en', 'Code of Criminal Procedure (Expanded), Article 190', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '191', 'After the Judge completes the procedures he deems necessary to reach a firm conviction, he shall hear the requests of the civil party or the arguments of his counsel and then the property administrator and the surety, as appropriate, or their counsel. The defendant shall, in any event, be the last to take the floor. The defendant may present his defence himself, even in the presence of his counsel. Section V Orders issued by the Single Judge concerning detention', 'en', 'Code of Criminal Procedure (Expanded), Article 191', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '192', 'The Single Judge may order the release of the defendant from custody after consulting the Public Prosecutor’s Office. The defendant shall submit his application for release to the Single Judge in duplicate. One copy shall be served on the civil party, if there is one, at his elected domicile if he has no actual place of residence in the town or borough in which the court is located. If the civil party has not elected a domicile, notice shall be served at the registry of the court. The civil party may file an objection to the application within twenty-four hours of the date on which he is notified. On expiry of the time limit, the Single Judge shall rule on the application. If he decides to order the release of the defendant, the civil party may file an appeal against the decision with the Appeal Court to which appeals lie from the Single Judge within twenty-four hours of the date on which he is notified. If he decides to reject the application, the defendant may file an appeal against the decision within the same period from the date of his notification. The Public Prosecutor may file an appeal against the Single Judge’s decision within twenty-four hours of its delivery. An appeal by the civil party or the Public Prosecutor filed within the legal time limit shall stay enforcement of the decision. English version (STL Draft Official Translation of Arabic) Version 1.0 53 The civil party or the defendant may file an appeal, within the above-mentioned time limit, against the part of the release order setting the amount of surety to be provided. The period of detention and the length of the travel ban shall be governed by the provisions of', 'en', 'Code of Criminal Procedure (Expanded), Article 192', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '193', 'The Single Judge may issue a detention order against the defendant if, following an adversarial trial, he decides to sentence him in his presence to a term of imprisonment of more than one year, provided that the order is based on a reasoned decision. The detention order shall remain in force notwithstanding an appeal against the judgement. Section VI Judgements delivered by the Single Judge', 'en', 'Code of Criminal Procedure (Expanded), Article 193', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '194', 'At the conclusion of the trial, the Single Judge shall deliver his judgement at the final hearing or at a subsequent sitting. The judgement shall be signed by the Judge and the clerk, shall bear the date of its delivery and shall contain a clear description of the facts established by the Judge, an itemized list of the supporting evidence, and an appropriately meticulous account of the grounds and reasoning, and of the legal provisions applicable to the offence. It shall cite the legal basis upon which the Single Judge was seized of the case. The Judge shall rule on all the objections and questions raised before him by the parties to the case. He shall rule on the public prosecution and the civil action brought pursuant to the public prosecution or as a direct complaint, and shall deliver his judgement in public. He may not refer in his judgement to facts that were not invoked or persons who were not formally charged.', 'en', 'Code of Criminal Procedure (Expanded), Article 194', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '195', 'If the Single Judge ascertains that the facts that have been established constitute a felony, he shall declare that he lacks jurisdiction to hear the case and shall refer the case file to the Public Prosecutor’s Office. If he finds evidence when hearing the case of offences of which he has not been seized or of persons who have not been charged, he shall refer the case file to the Public Prosecutor’s Office so that it may bring charges concerning the facts or against the persons concerned as part of the original statement of charges or as a separate case.', 'en', 'Code of Criminal Procedure (Expanded), Article 195', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '196', 'If the Single Judge ascertains that the elements of the misdemeanour charged are complete and that there is sufficient evidence to establish a causal link between it and the act committed by the defendant, he shall uphold the charges, ascertain the applicable legal provisions, convict the defendant and sentence him to the appropriate penalty. He shall award the appropriate damages and rule on all the civil obligations to the civil party if he has filed a claim and if the requisite conditions for the award have been met. If the penalty imposed is a fine or a suspended prison sentence, he shall order the release of the convicted person if he is in detention.', 'en', 'Code of Criminal Procedure (Expanded), Article 196', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '197', 'If the Single Judge ascertains that the evidence of the defendant’s participation in the commission of the offence with which he is charged is inadequate, he shall find the defendant not guilty and order that he be released forthwith if he is in detention. When delivering the judgement of English version (STL Draft Official Translation of Arabic) Version 1.0 54 acquittal, he shall sentence the civil party to pay damages to the defendant if he files a claim on the ground that the civil party abused his right to bring an action. If the defendant does not file a claim for damages during the criminal proceedings prior to the disposal of the case, he may file a claim before the same authority in a separate action within three months of the date of notification of the judgement of acquittal or of the Judge’s decision to confirm it.', 'en', 'Code of Criminal Procedure (Expanded), Article 197', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '198', 'If the Single Judge ascertains that the act charged does not constitute a criminal offence, that it is exempt from punishment, that it is not punishable by imprisonment, that the definition of an offence has ceased to apply to it for any reason, or that the action has been extinguished due to the one of the causes of extinction, he shall discharge the defendant and release him forthwith if he is in detention. The provisions of the preceding article shall be applicable if a claim for damages is filed.', 'en', 'Code of Criminal Procedure (Expanded), Article 198', 'Penalties and sentencing', 'Criminal Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CRIM-002-EXPANDED', '199', 'If the Single Judge ascertains that the act constitutes a contravention, he shall issue a ruling thereon and award damages to the victim if he has filed a claim. He shall order the release of the defendant forthwith if he is in detention.', 'en', 'Code of Criminal Procedure (Expanded), Article 199', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '200', 'The costs of the proceedings shall be borne by the party against whom the adjudication was made. – The civil party may be exempted from all or part of the costs if the Judge ascertains that he acted in good faith, unless he initiated the public prosecution by means of a direct complaint.', 'en', 'Code of Criminal Procedure (Expanded), Article 200', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '201', 'The Single Judge may rule on applications for the restitution of impounded articles even if he has decided the merits of the case so that he is no longer seized thereof, unless an appeal has been filed against his judgement. The Judge’s ruling in favour or against the restitution of impounded articles shall be open to appeal.', 'en', 'Code of Criminal Procedure (Expanded), Article 201', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '202', 'The Single Judge may expedite enforcement of a portion of the award of damages to the civil party, even if his judgement is open to appeal. Section VII Summary rules', 'en', 'Code of Criminal Procedure (Expanded), Article 202', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '203', 'Summary rules are applicable to breaches of bylaws, public health regulations and traffic regulations. When any the above-mentioned regulations is breached, whether the breach carries a penalty applicable to a contravention or a criminal offence, the record thereof shall be sent to the Single Judge who shall rule on the legal penalty applicable to the act without summoning the defendant. The Judge shall deliver his judgement within ten days, unless a shorter legal time limit is applicable.', 'en', 'Code of Criminal Procedure (Expanded), Article 203', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '204', 'The facts as set forth in the record shall be deemed to be true unless there were irregularities in compilation of the record. The Judge shall characterize the facts and specify the legal provisions applicable thereto and shall sentence the defendant unless he ascertains that: (a) The act with which is the defendant is charged does not constitute an offence, or is completely exempt from punishment; English version (STL Draft Official Translation of Arabic) Version 1.0 55 (b) That he lacks jurisdiction to rule on the contravention; (c) That the public prosecution has been extinguished on some ground. If he decides to declare that he lacks jurisdiction, he shall refer the case file to the competent Single Judge.', 'en', 'Code of Criminal Procedure (Expanded), Article 204', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '205', 'The ruling issued by the Single Judge in respect of any of the above-mentioned contraventions shall be enforceable unless the convicted person files an objection pursuant to the normal rules within ten days of the date on which he is notified thereof. – The Public Prosecutor may file an objection to the ruling pursuant to the normal rules within ten days of the date of its delivery. – If the Single Judge decides to dismiss the objection, the penalty imposed shall be increased by a maximum of one half.', 'en', 'Code of Criminal Procedure (Expanded), Article 205', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '206', 'The summary rules set out above shall not be applicable if a civil action has been brought in respect of the case.', 'en', 'Code of Criminal Procedure (Expanded), Article 206', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '207', 'When the judgement has become final and conclusive, because the time limit for filing an objection has expired, because the objector withdraws the objection, or because the objection has been dismissed, the clerk shall send a summary of the judgement with the annotation “enforceable” to the Public Prosecutor’s Office within five days of the confirmation or the judgement. If the clerk fails to comply with the provisions of this article, he shall be sentenced by the Single Judge to a fine of between 100,000 and 500,000 Lebanese pounds. Chapter II Appeals against judgements and decisions of the Single Judge to the Appeal Court Section I Exercise of the right of appeal', 'en', 'Code of Criminal Procedure (Expanded), Article 207', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '208', 'A defendant who has been convicted may file an appeal against the first-instance judgement either in respect of the sentence imposed or in respect of the damages awarded. The defendant may file an appeal against an acquittal if he has been sentenced to pay some or all of the judicial costs and against any judgement awarding him damages where the plaintiff abused his right to bring an action.', 'en', 'Code of Criminal Procedure (Expanded), Article 208', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '209', 'The property administrator or the surety may file an appeal against a judgement requiring him, jointly with a convicted defendant, to pay damages to the civil party. They may file a separate appeal against the judgement even if the defendant acquiesces thereto. In the latter case, he alone shall benefit from his appeal.', 'en', 'Code of Criminal Procedure (Expanded), Article 209', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '210', 'The civil party may appeal against the part of the judgement concerning the civil action. If the civil action is dismissed on the ground of an acquittal, he may file an appeal against the dismissal even if the acquittal has become final because of the lack of an appeal by the Public Prosecutor’s Office. English version (STL Draft Official Translation of Arabic) Version 1.0 56 – He may file an appeal against a judgement sentencing him to pay damages to the defendant.', 'en', 'Code of Criminal Procedure (Expanded), Article 210', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '211', 'The Public Prosecutor’s Office at the Appeal Court may file an appeal against the provisions of judgements pertaining to the public prosecution. The Public Prosecutor''s Office at the Court of Cassation may file an appeal in writing to the Public Prosecutor’s Office at the Appeal Court against the initial judgement to acquit the defendant, to exempt him from punishment, to extinguish the public prosecution, or to declare that the Court lacks jurisdiction to hear the case. Section II Judgements that are open to appeal', 'en', 'Code of Criminal Procedure (Expanded), Article 211', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '212', 'Judgements pertaining to misdemeanours are open to appeal. Judgements against contraventions are open to appeal only where they involve: (a) A sentence of imprisonment or payment of a fine of more than 500,000 Lebanese pounds; (b) An additional or subsidiary penalty or an award of personal damages of more than 500,000 Lebanese pounds; (c) Dismissal of an objection provided for under Article 73 of this Code; (d) A penalty in respect of a contravention joined with a misdemeanour.', 'en', 'Code of Criminal Procedure (Expanded), Article 212', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '213', 'Rulings on the merits of a dispute that are not final may be appealed only when the final judgement has been delivered. Rulings on any objection raised under Article 73 of this Code, rulings on release, and rulings whereby the Single Judge dismisses the case without addressing the merits, shall be exempted from this principle. Section III Formal conditions governing the admissibility of an appeal 1. Time limit for appeals', 'en', 'Code of Criminal Procedure (Expanded), Article 213', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '214', 'The civil party, the defendant, the property administrator and the surety may file an appeal against an initial judgement within fifteen days of the date of its delivery if it is delivered adversarially, and from the date of his notification thereof if it is deemed to be adversarial, if it is delivered in absentia or if it involves the dismissal of an objection on formal grounds. The Public Prosecutor at the Appeal Court may file an appeal against a judgement within one month of the date of its delivery. The rules laid down in Articles 165 to 170 of this Code shall be applicable to the characterization of the judgement as being delivered adversarially or in absentia.', 'en', 'Code of Criminal Procedure (Expanded), Article 214', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '215', 'If the judgement is not delivered at the time specified at the final hearing for its delivery, any party to the case may file an appeal within fifteen days of the date of being notified thereof. English version (STL Draft Official Translation of Arabic) Version 1.0 57', 'en', 'Code of Criminal Procedure (Expanded), Article 215', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '216', 'Any party to the case who did not file an appeal against the first-instance judgement within the time limit of fifteen days may file a subsidiary appeal within five days of the date of being notified of the first sitting to hear an original appeal filed by another party to the case. – Dismissal of the original appeal on procedural grounds shall entail dismissal of the subsidiary appeal. 2. Rules governing the filing of appeals', 'en', 'Code of Criminal Procedure (Expanded), Article 216', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '217', 'The appeal is filed through an appeal lawyer with the Appeal Court in the area of jurisdiction of the Judge who delivered the judgement, subject to appeal or through the Judge. The appeal must set out the grounds invoked by the person filing it and his demands.', 'en', 'Code of Criminal Procedure (Expanded), Article 217', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '218', 'If the appeal is filed through the Single Judge who delivered the judgement subject to appeal, he shall transmit the appeal together with the case file within three days of the date on which it is filed. If the convicted person is in detention, the Public Prosecutor’s Office shall order his transfer to the detention centre at the Appeal Court. If the person has served his sentence prior to the ruling on his appeal, the Public Prosecutor’s Office shall release him forthwith. Section IV Effects of the appeal and proceedings at the Appeal Court', 'en', 'Code of Criminal Procedure (Expanded), Article 218', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '219', 'The initial judgement shall not be enforced before the expiry of the time limit for an appeal and before a ruling is delivered in the event of an appeal. The appeal stays enforcement of the judgement appealed against. However, the Judge’s provisional award of damages to the civil party shall be payable in advance, unless the Appeal Court issues a ruling to the contrary when examining the initial judgement against which the appeal was filed. An arrest warrant issued by the Single Judge pursuant to Article 193 of this Code shall remain in force unless the Appeal Court decides to release the detainee.', 'en', 'Code of Criminal Procedure (Expanded), Article 219', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '220', 'An appeal filed by the Public Prosecutor shall entail referral of the public prosecution as a whole to the Appeal Court, unless it relates to only part of it, in which case its effect is confined thereto. Where an appeal is filed by the defendant, the Appeal Court shall confine its examination to the part of the judgement appealed against. The Appeal Court may not consider new facts that might constitute offences and that were not invoked before the Single Judge who delivered the judgement appealed against.', 'en', 'Code of Criminal Procedure (Expanded), Article 220', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '221', 'If the defendant is the only party to file an appeal against the initial judgement, the Appeal Court may not impose a more severe sentence or increase the award of damages to the civil party.', 'en', 'Code of Criminal Procedure (Expanded), Article 221', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '222', 'An appeal filed only by the civil party shall entail referral of the civil part of the case to the Appeal Court. The Appeal Court may not reduce the amount of the damages awarded to him.', 'en', 'Code of Criminal Procedure (Expanded), Article 222', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '223', 'The Appeal Court shall set the date of the appeal proceedings and shall comply with the ordinary rules governing proceedings before the Single Judge. The Public Prosecution Service shall be represented before it by the Public Prosecutor or by one of his Advocates-General. English version (STL Draft Official Translation of Arabic) Version 1.0 58 It shall hear the petitions, as applicable, of the civil party or his counsel, if either of them is present, and the arguments of the representative of the Public Prosecutor’s Office. It shall then hear the arguments of counsel for the defence and the defendant himself if he so requests. If it is satisfied with all the facts and evidence contained in the case file, it shall close the proceedings and deliver its judgement at the end of the hearing, or adjourn the hearing for it to be delivered at a later date.', 'en', 'Code of Criminal Procedure (Expanded), Article 223', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '224', 'If the Court finds it necessary to obtain further information, it shall summon the witnesses and undertake any investigative measures that it considers useful at a public hearing, or shall instruct one of its members to undertake a supplementary investigation in accordance with the normal rules. When the supplementary investigation has been completed, the relevant documents shall be added to the case file, and all the parties may examine them and discuss them at a public hearing.', 'en', 'Code of Criminal Procedure (Expanded), Article 224', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '225', 'When the Appeal Court concludes its investigative measures, it shall decide to set aside, amend or uphold the outcome of the appealed judgement, replacing the reasoning on which the latter judgement was based with its own reasoning.', 'en', 'Code of Criminal Procedure (Expanded), Article 225', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '226', 'When the Court sets aside the appealed judgement and decides to acquit the defendant or to discontinue the proceedings, it shall order his immediate release if he is detained and shall dismiss the civil action. A defendant who is acquitted or exempted from punishment may seek an award of damages against the plaintiff who abused his right to bring an action, in accordance with the provisions of Article 197 of this Code.', 'en', 'Code of Criminal Procedure (Expanded), Article 226', 'Termination of employment', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '227', 'When the Public Prosecutor’s Office files an appeal against the initial judgement, the entire case shall be heard by the Appeal Court. If the Court ascertains that the facts of the case constitute a felony, it shall set aside the appealed judgement and declare that it lacks jurisdiction. It may issue a detention order against the defendant and transmit the case file to the Public Prosecutor’s Office for referral to the Investigating Judge. A dispute regarding jurisdiction when its ruling is confirmed shall be settled through the procedure for settling conflicts of jurisdiction between different courts in criminal matters.', 'en', 'Code of Criminal Procedure (Expanded), Article 227', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '228', 'When the Appeal Court ascertains that the Single Judge who delivered the appealed judgement was not competent to hear the case, it shall set aside the judgement on the ground of lack of jurisdiction and transmit the case file to the Public Prosecutor’s Office so that it may take the requisite action.', 'en', 'Code of Criminal Procedure (Expanded), Article 228', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '229', 'When the Appeal Court ascertains that the act charged is a contravention, it shall issue a ruling thereon after setting aside the appealed judgement.', 'en', 'Code of Criminal Procedure (Expanded), Article 229', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '230', 'If the Appeal Court sets aside the appealed judgement because of a failure to comply with the law or because it breaches the fundamental rules of procedure, it shall examine the merits of the case and issue a ruling.', 'en', 'Code of Criminal Procedure (Expanded), Article 230', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '231', 'An application to set aside may be filed against a judgement delivered by the Appeal Court in absentia, in accordance with the rules governing applications to set aside a judgement in absentia delivered by the Single Judge and within the same time limit.', 'en', 'Code of Criminal Procedure (Expanded), Article 231', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '232', 'The Appeal Court may decide, after consulting the Public Prosecutor’s Office, whether it is appropriate to release a detained defendant. Its decision is not open to any kind of review. English version (STL Draft Official Translation of Arabic) Version 1.0 59 Chapter III The Criminal Court Section I General provisions', 'en', 'Code of Criminal Procedure (Expanded), Article 232', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '233', 'The Criminal Court is composed of the President and two Auxiliary Judges. It shall be convened in the presence of the Public Prosecutor or Advocate-General and the clerk. It shall be seized of cases pursuant to an indictment accompanied by the statement of charges issued by the Public Prosecutor’s Office. The Court shall examine offences constituting felonies and related misdemeanours. It may not examine any offence that is not included in the indictment or prosecute a person who has not been indicted. It may amend the legal definition of the acts described in the indictment.', 'en', 'Code of Criminal Procedure (Expanded), Article 233', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '234', 'Anyone who was involved in the case at the prosecution or investigation stage, or who was a member of the Indictment Division that drew up the indictment may not be included in the composition of the Criminal Court.', 'en', 'Code of Criminal Procedure (Expanded), Article 234', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '235', 'The record of the proceedings shall note, at the beginning of each hearing, the names of the President of the Court, the two Auxiliary Judges, the representative of the Public Prosecutor’s Office and the clerk, and the time at which the hearing was opened. It shall be signed by all of the aforementioned, except the representative of the Public Prosecutor’s Office, at the end of each hearing. If any of them fails to sign, the hearing shall be null and void. The record shall contain an account of all investigative measures and proceedings. The President shall issue instructions to the clerk regarding the material to be recorded. Section II Preparations for proceedings before the Criminal Court', 'en', 'Code of Criminal Procedure (Expanded), Article 235', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '236', 'The Public Prosecutor shall prepare a list of witnesses for the prosecution and serve a copy thereof, together with a copy of the indictment, on the accused. Once the notification procedure has been completed, the Public Prosecutor’s Office shall transmit the case file to the Criminal Court after ordering the detained accused to be brought to the detention centre at the Court. Proceedings that are conducted without ensuring that the indictment and the list of witnesses for the prosecution have been served on the accused, as well as the resulting judgement, are liable to annulment.', 'en', 'Code of Criminal Procedure (Expanded), Article 236', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '237', 'The President of the Court or an Auxiliary Judge delegated by the President shall question the accused who has been produced before it prior to the court hearing. If the accused is not in detention, the President of the Court shall issue a summons requiring him to surrender within twenty-four hours of the beginning of the proceedings. If he surrenders within the stated period, he shall remain in detention until a release order is delivered. If he fails to do so without a reasonable excuse, he shall be deemed to be a fugitive from justice and an enforceable arrest warrant shall be issued against him.', 'en', 'Code of Criminal Procedure (Expanded), Article 237', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '238', 'During the preparatory questioning, the accused shall be asked whether he has been served with the indictment and the list of witnesses for the prosecution and whether he has English version (STL Draft Official Translation of Arabic) Version 1.0 60 appointed counsel to assist him during the proceedings. He shall also be questioned about his social circumstances and asked to comment on the charge against him and the investigations on which it is based. If the accused has not appointed counsel, the President or the Auxiliary judge appointed by him shall ask the President of the Bar Association to appoint a defence counsel within twenty-four hours of the time of his notification or shall appoint counsel himself. A record of the preparatory questioning shall be signed by the President or delegated the appointed Auxiliary Judge, the accused and the clerk. Section III The trial', 'en', 'Code of Criminal Procedure (Expanded), Article 238', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '239', 'All the parties are entitled to examine the case file and to have a copy thereof.', 'en', 'Code of Criminal Procedure (Expanded), Article 239', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '240', 'The civil party before the Criminal Court shall appoint a defence counsel. If more than one perpetrator was involved in the commission of a single felony or several related felonies and separate indictments were issued against them or against some but not others, the President of the Court shall order the decisions to be joined in a single case.', 'en', 'Code of Criminal Procedure (Expanded), Article 240', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '241', 'If the indictment comprises unrelated felonies, the President of the Court may decide to deal with some of the felonies at the beginning of the proceedings against the accused and to deal subsequently with the others.', 'en', 'Code of Criminal Procedure (Expanded), Article 241', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '242', 'The President of the Criminal Court shall set a date for the proceedings and summon the civil party and the witnesses. He shall issue an order requiring an accused who was at liberty during the initial investigation to surrender to the Court twenty-four hours before the commencement of the proceedings. The time limit shall begin to run on the date on which notice is served pursuant to the provisions of Articles 147, 148 and 149 of this Code. If he surrenders within the time limit, he shall be tried adversarially and the arrest warrant against him shall be enforced. If he does not, he shall be tried in absentia and the proceedings shall be held according to the rules governing the trial of a fugitive from justice.', 'en', 'Code of Criminal Procedure (Expanded), Article 242', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '243', 'Before ruling on the merits of the case, the Court shall take the following decisions: (a) A decision on an objection to jurisdiction on the ground that the accused was a minor on the date of commission of the felony with which he is charged; If the Court decides to declare that it lacks jurisdiction and if there is another accused in the case, it shall separate the proceedings and refer the minor’s file to the Public Prosecutor’s Office for transmission to the Juvenile Court. (b) A decision on one or more procedural objections filed by the parties to the case; (c) A decision on the defence arguments on the merits; (d) A decision on whether to stay enforcement of the arrest warrant pending completion of the institution of legal proceedings before the Court if the accused was released during the initial investigation; (e) A decision on whether to release the accused if he is in detention. English version (STL Draft Official Translation of Arabic) Version 1.0 61 The accused shall be released on condition that he elects a domicile in the town or borough in which the Court is located so that he may be served there with documents and writs, that he presents himself at the Court twenty-four hours before each hearing and that he pays the surety determined by the Court unless he remains in detention during the period running from the final hearing of the proceedings until delivery of the judgement. If he fails to attend a hearing without a reasonable excuse, he shall be deemed to be a fugitive from justice and the rules applicable to the trial of a fugitive shall be applied. – The Court may decide to issue a travel ban against the accused pending delivery and enforcement of the judgement. – The Court may not rule on an application for release until it has consulted the Public Prosecutor’s Office. – The Court shall comply with the provisions of Article 108 of this Code. – The ruling on an application to release the accused shall not be open to appeal.', 'en', 'Code of Criminal Procedure (Expanded), Article 243', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '244', 'The parties to the case may request to call witnesses before the initiation of the proceedings or during the trial. The Public Prosecutor and the civil party shall be notified of the list of witnesses called by the accused at least twenty-four hours before the time set to hear their testimony. The accused shall also be notified of the list of witnesses called by the civil party or the Public Prosecutor within the same time limit. The President of the Court may decide of his own motion to summon experts who performed forensic duties pertaining to the case in order to question them to seek clarification of their opinions and any other witnesses whose testimony he might consider useful. The costs of summoning the witnesses and their travel expenses shall be borne by the accused and the civil party who called them.', 'en', 'Code of Criminal Procedure (Expanded), Article 244', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '245', 'If the President of the Court ascertains before the commencement of the proceedings that the information available in the case is incomplete, he shall order a supplementary investigation to be conducted in the presence of the parties and shall either undertake it himself or delegate one of his Auxiliary Judges to do so. On completion of the supplementary investigation, the records thereof shall be added to the case file.', 'en', 'Code of Criminal Procedure (Expanded), Article 245', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '246', 'The President of the Court shall oversee the maintenance of order in the courtroom and take whatever steps are required to ensure the smooth progress of the proceedings. The members of the law enforcement authorities responsible for court security shall comply with his orders in this regard. If any of those present at the hearing cause a disturbance, the President shall order their expulsion from the courtroom. If they resists the order, the President may order that they be placed in detention for twenty- four hours. If their conduct constitutes a misdemeanour, a record of the act shall be compiled, the Court shall take up the matter immediately, prosecute them adversarially, and sentence them forthwith.', 'en', 'Code of Criminal Procedure (Expanded), Article 246', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '247', 'The President is vested with discretionary authority and may take any measures he deems necessary to shed light on the facts provided that this does not stem from a prejudiced view of the case. English version (STL Draft Official Translation of Arabic) Version 1.0 62', 'en', 'Code of Criminal Procedure (Expanded), Article 247', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '248', 'The President shall structure the hearing and the discussions in whatever manner he deems appropriate. He is entitled to reject any request that may unreasonably prolong the proceedings. Unless a party to the case raises an objection to the hearing of a witness on legal grounds, he shall hear the witnesses after they take the oath . In the event of an objection, he shall then decide to dismiss the witness or to hear him as a source of information. He may sentence a witness who has been duly summoned and fails to appear at the hearing to a fine of between 100,000 and 500,000 Lebanese pounds. A witness who has been sentenced to a fine may apply for an exemption if he presents a valid excuse. The President of the Court may order any witness who has failed to attend the Court for a second time after being summoned, even if he has already been fined by him. The President of the Court may attach to the file any papers and documents that he deems necessary to shed light on the facts, together with the other communications and documents in the case file. He may consult the initial or preliminary investigation file or the judicial file in order to deliberate on the statements contained therein and may seek expert assistance in clarifying technical points. Where he wishes to hear a witness who is resident outside his area of jurisdiction, he may appoint the Investigating Judge with jurisdiction in the area of the witness’s domicile or place of residence.', 'en', 'Code of Criminal Procedure (Expanded), Article 248', 'Penalties and sentencing', 'Criminal Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CRIM-002-EXPANDED', '249', 'Proceedings before the Criminal Court shall be held in public unless the President decides to hold them in camera to preserve law and order or public morals. The trial hearings shall be held daily until the final disposal of the case, unless the circumstances of the case require the deferral of a hearing, which shall be held at the earliest convenient time. Records of the proceedings shall be compiled. The bench and the clerk shall sign the record. If the civil party fails to attend the proceedings without a lawful excuse, the trial shall be held in his absence and the public prosecution shall proceed. If he attends some hearings and presents his claims on such an occasion, the Court may award him personal damages.', 'en', 'Code of Criminal Procedure (Expanded), Article 249', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '250', 'The proceedings shall be conducted orally. The President may decide to make an audio or visual recording thereof. All evidence to be used in deciding on the merits of the case shall be discussed by the parties in public; all criminal exhibits must be produced in court and the records of their seizure shall be read out. All of the parties may comment thereon.', 'en', 'Code of Criminal Procedure (Expanded), Article 250', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '251', 'The accused shall appear before the Court at the trial hearing without instruments of restraint. He shall be guarded by members of the law enforcement authorities to prevent him from escaping. The President shall enquire about his family name and given name, his parents’ names, his nationality, date and place of birth, civil register number, place of residence, occupation and level of education, whether he is married or single, and whether he has a criminal record and, if so, the type of offence of which he was convicted and whether he has served his sentence. He shall also ask him whether he has appointed defence counsel. The proceedings shall not be held in the absence of counsel for the accused. If he has not appointed counsel, the President of the Court may ask the President of the Bar Association to appoint defence counsel for the accused, or he may appoint counsel himself. English version (STL Draft Official Translation of Arabic) Version 1.0 63 If the accused insists that no defence counsel shall be appointed, his trial shall take place without counsel.', 'en', 'Code of Criminal Procedure (Expanded), Article 251', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '252', 'The President shall alert the accused to his obligation to pay attention to the facts set forth in the indictment. The President or the Auxiliary Judge delegated by the President shall read out the indictment clearly. The civil party, the representative of the Public Prosecutor’s Office and the accused shall not interrupt the reading by making observations. After the reading, the President shall summarize for the accused the facts with which he is charged in the indictment, the supporting evidence and the legal definition. The civil party shall then report the outcome of his civil action and present his claims or waive his rights with respect to the case. Finally, the representative of the Public Prosecutor’s Office shall state the grounds for the indictment and present the list of witnesses for the prosecution. The clerk of the court shall read out the list. Subject to the provisions of Article 244, the civil party, the representative of the Public Prosecutor’s Office and the accused may raise an objection to the hearing of a witness whose name does not appear on the list with which he was served. The Court shall rule on the objection at the same hearing or at the following one. The President of the Court may decide, exercising his discretionary authority, to hear all or some of the witnesses whose names are listed. He may also hear one or more witnesses whose names do not appear on the list of witnesses.', 'en', 'Code of Criminal Procedure (Expanded), Article 252', 'Contracts and obligations', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '253', 'Before the President of the Court questions the accused, he shall order that the witnesses be conveyed to the room reserved for them, where the law enforcement authorities shall guard them and prevent them from disclosing what they intend to say in their testimony. – After the witnesses have left the courtroom, the President shall ask the accused whether he pleads guilty to the charge against him. The President shall then proceed with the questioning after ascertaining that the accused is able to understand the questions put to him and that his statements are made entirely freely. If the accused refuses to answer and remains silent, he may not be compelled to speak. If he suffers from a physical, psychological or mental illness, or shows signs thereof during the questioning, the court may seek the assistance of a medical expert, of its own motion or in response to a petition by one of the parties, to diagnose his condition. The doctor whose assistance is sought shall provide full details in his report of the diagnosis he has been asked to provide. He may not use his assignment to coerce the accused to provide him with information regarding the offence for which he is being tried. When the President concludes his questioning of the accused, the two Auxiliary Judges, the civil party, the representative of the Public Prosecutor’s Office, and counsel for the defence may put questions to him through the President, who is entitled to reject any question if he considers that it will not be helpful or useful in shedding light on the facts. The questions and answers shall be noted with the requisite precision and clarity in the record of the proceedings.', 'en', 'Code of Criminal Procedure (Expanded), Article 253', 'Inheritance and succession', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '254', 'If the accused is mute or deaf, the President of the Court shall appoint a person who can communicate with him in sign language or in some other way after taking an oath to perform his duties honestly and with integrity. If a deaf or mute person is able to write, the questions and his answers shall be recorded in writing. English version (STL Draft Official Translation of Arabic) Version 1.0 64 If the defendant does not understand the Arabic language, the President of the Court shall appoint a qualified interpreter, who shall begin his work after taking an oath to perform his duties honestly and with integrity. After the questioning of the accused, his statement shall be read to him clearly. He shall confirm it or make observations regarding it if necessary, and this shall be noted in the record of the proceedings.', 'en', 'Code of Criminal Procedure (Expanded), Article 254', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '255', 'On completion of the questioning of the accused, the President shall call each witness to give testimony in the absence of the other witnesses. He shall ask each witness to state his name, his parents’ names, his domicile or place of residence, his age, the closeness of his acquaintance or relationship with the accused and the civil party, whether he is related to either of them and, if so, the degree of kinship. The witness shall then swear the following oath: “I swear by almighty God to tell the truth, the whole truth and nothing but the truth.” He shall then deliver his testimony orally and the clerk shall note it in the record of the proceedings. If the witness does not swear the oath in the form specified above, his testimony shall be void unless the President exempts him from taking the oath on ascertaining that he belongs to a denomination that precludes him from taking it.', 'en', 'Code of Criminal Procedure (Expanded), Article 255', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '256', 'The Court shall hear the following as a source of information: (a) The ascendants and descendants of the accused; (b) His full brothers and sisters, his half brothers and sisters, or his relatives by marriage to the same degree; (c) The spouse of the accused, even after a divorce; (d) The civil party; (e) A minor of less than 18 years of age. The Court may hear the testimony of all those witnesses after they take the legal oath unless one of the parties to the case raises an objection thereto.', 'en', 'Code of Criminal Procedure (Expanded), Article 256', 'Family law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '257', 'The testimony of an informant who reported the offence to the competent authorities without receiving a fee or reward for the information shall be admissible. In order for such evidence to be admissible, the Public Prosecutor shall reveal the status of the informant before he is heard. If the informant received any kind of fee or reward for the information he provided, his testimony shall be inadmissible if any party to the case raises an objection. The President of the Court may still hear him as a source of information. A Judicial Police officer is prohibited from mentioning the name of an informant when giving testimony.', 'en', 'Code of Criminal Procedure (Expanded), Article 257', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '258', 'A person who is pledged to professional secrecy may not be compelled to give testimony if the testimony would result in a breach of the confidential information that he is required to protect. If a witness is pledged to professional secrecy and a party objects thereto, the Court shall rule on the dispute in the light of the law governing his profession and the nature of his work. English version (STL Draft Official Translation of Arabic) Version 1.0 65', 'en', 'Code of Criminal Procedure (Expanded), Article 258', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '259', 'The Court may hear a witness who attends without a summons if his name appears on one of the lists of witnesses to be heard.', 'en', 'Code of Criminal Procedure (Expanded), Article 259', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '260', 'A witness may not be interrupted when testifying. – The civil party, the representative of the Public Prosecutor’s Office, the two Auxiliary Judges and the accused may put questions to the witness through the President. – The President of the Court may decide to reject a question that does not serve to shed light on the facts. Once the witness has testified, the President shall ask him whether his testimony concerned the accused in the dock. He shall then invite the accused to make any observations in respect of the witness’s statement. He may then arrange any confrontation that he deems necessary between the accused and the witness in order to shed light on the facts. The statement shall be read in public and the witness shall confirm it. After delivering his testimony, the witness may not leave the courtroom until permitted to do so by the President.', 'en', 'Code of Criminal Procedure (Expanded), Article 260', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '261', 'If there are discrepancies or variations between the witness’s testimony and his statements during the initial or preliminary investigation, or if he has changed his testimony, the President shall order the clerk of the court to note that fact in the record. The civil party, the representative of the Public Prosecutor’s Office and the accused may request that such discrepancies or variations be noted in the record of the proceedings. If the discrepancy or variation in the witness’s testimony contributes to the belief that the witness gave false testimony, the President of the Court may, of his own motion or in response to a petition from the aforementioned persons, order his arrest. The representative of the Public Prosecutor’s Office shall charge him with perjury. The charge shall be noted in the record of the proceedings. The President of the Court or one of his two Auxiliary Judges shall then question the witness regarding the offence of perjury with which he is charged or he shall delegate one of the other Judges to do so. The person entrusted with the investigation shall question the witness who has been charged and gather information concerning the charge without expressing his opinion regarding the investigation. After completing the investigation, he shall transmit the file to the Public Prosecutor’s Office, which shall draft its submission and forward it to the Indictment Division. The Division shall issue a ruling to indict or not to indict. If it decides to indict the witness on a felony charge of perjury, the Court shall rule thereon before or in conjunction with the original case. An appeal against the Indictment Division’s ruling may be filed with the Court of Cassation.', 'en', 'Code of Criminal Procedure (Expanded), Article 261', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '262', 'In the case of a charge of perjury as set out in the preceding article, the representative of the Public Prosecutor’s Office, the civil party and the accused may request that the hearing in the original case be deferred until a ruling is delivered in the perjury case. The Court shall rule on the petition. It is also entitled to issue such a ruling of its own motion.', 'en', 'Code of Criminal Procedure (Expanded), Article 262', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '263', 'After the witness has finished his testimony, the President of the Court may order, of his own motion or in response to a petition from the representative of the Public Prosecutor’s Office, the accused, or the civil party, the removal of specific witnesses from the courtroom and the admission of one or more of those removed to hear their testimony separately or in the presence of the others or English version (STL Draft Official Translation of Arabic) Version 1.0 66 of some of them, to arrange a confrontation between them, to show them the exhibits that have been seized and to discuss them with the accused.', 'en', 'Code of Criminal Procedure (Expanded), Article 263', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '264', 'The President of the Court may, before hearing a witness or during his testimony, have the accused temporarily removed from the courtroom in order to seek explanations from a witness separately or jointly with others. Counsel for the accused shall be present when the explanations are sought from the witness. If counsel leaves the room, his departure shall not invalidate the testimony given in his absence. However, the Court may not proceed with the trial until the accused has been returned to the courtroom and informed of the testimony given in his absence. If the accused causes a commotion or disturbance in the courtroom while a witness is being heard or during the proceedings, the President of the Court shall order him to desist. If he continues, the President shall order that he be removed from the courtroom, that he remain outside, and that the proceedings continue in his absence. On conclusion of the hearing, the President of the Court shall order that the accused be notified of the measures taken after his removal, and his notification thereof shall be noted in the record of the proceedings.', 'en', 'Code of Criminal Procedure (Expanded), Article 264', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '265', 'A witness who has been fined may raise an objection to the fine before the Court. The Court shall consider his plea and issue a ruling on the objection that may not be appealed on any ground. – The fine shall be enforced in accordance with the provisions governing the enforcement of fines.', 'en', 'Code of Criminal Procedure (Expanded), Article 265', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '266', 'If the Court decides not to further summon a witness on whom it was unable to serve the summons in due form, his statement shall be read out in public before the Investigating Judge and it shall then be discussed between the parties. – If it appears that a witness did not take the oath before giving his testimony, the President of the Court may summon him again so that he may take the oath at a public hearing and ask him whether he confirms the previous testimony. If he does, the Court may rely on it in its judgement.', 'en', 'Code of Criminal Procedure (Expanded), Article 266', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '267', 'If a witness is deaf or mute, or is not proficient in the Arabic language, the provisions of Article 254 of this Code shall be applied when hearing his testimony.', 'en', 'Code of Criminal Procedure (Expanded), Article 267', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '268', 'If the Court decides to visit the place in which the offence occurred, it shall set a date and serve notice on all parties to the case. If one of them fails to appear, the Court shall carry out its investigations in his absence. The missing party may seek the information thereon in the case file.', 'en', 'Code of Criminal Procedure (Expanded), Article 268', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '269', 'The President of the Court or the Auxiliary Judge whom he delegates may undertake a supplementary investigation pertaining to the case before the Court and compile a record of a search for clues that are liable to disappear and that might assist in uncovering the truth, or to hear a person who is close to death. The person responsible for the investigation shall keep records of what has been seized, or of the information heard, and shall send them to the Court for discussion at a public hearing.', 'en', 'Code of Criminal Procedure (Expanded), Article 269', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '270', 'When the Court finishes hearing witnesses and gathering and discussing evidence, it shall hear the claims of the civil party. The representative of the Public Prosecutor’s Office shall then present his evidence and arguments and make his submissions. Counsel for the defence shall then present his client’s arguments and shall also specify his grounds of defence. The Court shall then hear the final statement of the accused and close the proceedings. English version (STL Draft Official Translation of Arabic) Version 1.0 67', 'en', 'Code of Criminal Procedure (Expanded), Article 270', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '271', 'After the closure of the proceedings, the civil party, the representative of the Public Prosecutor’s Office and the accused may file a petition for their reopening, stating the grounds in support of the petition. The Court shall grant the petition if it appears to be reasonable and acceptable, or if it is based on significant grounds that require further discussion.', 'en', 'Code of Criminal Procedure (Expanded), Article 271', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '272', 'After the President of the Court announces the closure of the proceedings, he shall withdraw to chambers with the two Auxiliary Judges to deliberate on the case and scrutinize the indictment, the Court’s final investigation, the documents and records contained in the case file, the claims of the civil party, the arguments of the representative of the Public Prosecutor’s Office, the pleadings of counsel for the accused and the final statement of the accused. The Court shall then confer on all the material scrutinized and deliver its unanimous or majority verdict that same day or within no more than ten days. The judgement must be signed by the President, the two Auxiliary Judges and the clerk. – Where a member of the Court fails to sign the judgement, it shall be liable to annulment. – Where a member of the Court dissents from the judgement, he shall record his dissent and sign it.', 'en', 'Code of Criminal Procedure (Expanded), Article 272', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '273', 'If the Court ascertains that the act in question was committed, that the characterization of the offence is valid, and that the evidence shows that it is attributable to the accused, it shall convict him and impose the requisite penalty. It shall also rule on the damages to be awarded to the civil party if a claim for damages has been filed. It shall confiscate the seized items or return them if there is no reason to confiscate them. It may also decide on one or more preventive measures and one or more ancillary or additional penalties. The Court may decide to impose concurrent sentences pursuant to Article 205 of the Criminal Code.', 'en', 'Code of Criminal Procedure (Expanded), Article 273', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '274', 'If the Court ascertains that the evidence in the case file is insufficient to convict the accused, it shall acquit him. If it ascertains that the act attributed to the accused does not constitute an offence or does not entail a penalty, it shall discontinue the proceedings. If it ascertains that some elements of the felony attributed to the accused are incomplete and that the act constitutes a misdemeanour, it shall amend the legal characterization contained in the indictment, convict the accused of a misdemeanour, and sentence him accordingly. The judgement delivered by the Criminal Court shall contain the following elements: (a) A reference to the indictment on the basis of which the Court was seized of the case and to the charges laid before it by the Public Prosecutor’s Office pursuant to the indictment; (b) A clear summary of the civil party’s claims, the pleadings of the representative of the Public Prosecutor’s Office and counsel for the accused, and a reference to the content of the final statement by the accused; (c) A clear summary of the facts drawn from the indictment and the judicial proceedings; (d) An itemized list of the evidence and the grounds necessitating conviction or acquittal; (e) A statement of the nature of the offence, identification of the legal characterization applicable thereto and a citation of the relevant legal article; (f) Specification of the penalty on conviction; (g) A statement of the amount of personal damages; English version (STL Draft Official Translation of Arabic) Version 1.0 68 (h) An order for fees and costs. The Court shall specify in its judgement any aggravating factual circumstances, followed by grounds of excuse, aggravating personal circumstances and mitigating circumstances. If any ground exists that might justify the act committed by the accused, the Court shall ascertain its existence before deciding that the act does not constitute an offence and hence that the accused is not accountable. In all c', 'en', 'Code of Criminal Procedure (Expanded), Article 274', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '275', 'The President of the Court or an Auxiliary Judge delegated by the President shall read out the judgement at a public hearing in the presence of the representative of the Public Prosecutor’s Office, the accused, and the civil party. If the accused or the civil party does not attend, the judgement shall nevertheless be read out in his absence. The clerk of the court shall sign the judgement after the reading. He shall then compile a record of the reading of the judgement at the dictation of the President, who may include the conclusions of the judgement therein. The President, the two Auxiliary Judges and the clerk shall sign the record. If, during the reading of the judgement, a convicted accused causes a disturbance, a commotion or disorder in the courtroom, the President shall order that he be removed and the reading of the judgement shall proceed in his absence. If the conduct of the convicted accused constitutes a misdemeanour, the President shall record the fact and the Court shall examine the offence and sentence him forthwith. The accused may raise a defence during the proceedings pertaining to the misdemeanour that he committed.', 'en', 'Code of Criminal Procedure (Expanded), Article 275', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '276', 'If the Court has acquitted the accused or discontinued the proceedings against him, it shall release him forthwith unless he is detained on another ground. He may not be prosecuted subsequently for the same act, even if it is defined in different terms. If the Court ascertains in the course of the proceedings that the accused committed an offence that is not contained in the indictment, it shall remand him in custody, if the act constitutes a felony, to the Public Prosecutor’s Office so that it may initiate the prosecution and refer the matter to the appropriate judicial authority. If the act constitutes a misdemeanour, it shall prepare a report on the matter and transmit it to the Public Prosecutor’s Office. If it ascertains that the act with which the accused is charged was committed by another person, it shall, after acquitting the accused, send the case file to the Public Prosecutor’s Office so that it may prosecute the suspect and bring him before the appropriate judicial authority.', 'en', 'Code of Criminal Procedure (Expanded), Article 276', 'Family law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '277', 'The accused may, prior to the closure of the proceedings, file a claim for damages against the civil party on the ground that he acted in bad faith, abused the right to bring an action, or committed an error in exercising that right. If the Criminal Court acquits the accused or discontinues the proceedings against him, it shall award him appropriate damages to cover the damage suffered.', 'en', 'Code of Criminal Procedure (Expanded), Article 277', 'Liability and damages', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '278', 'If the judgement of acquittal of the accused is based on a lack of evidence, insufficient evidence or doubt, the civil party may file a claim before the Criminal Court for the damages he sustained, based on the facts set out in the indictment. English version (STL Draft Official Translation of Arabic) Version 1.0 69 If he filed no claim for damages during the proceedings and prior to their closure, he may still file a claim pursuant to the provisions of the preceding article.', 'en', 'Code of Criminal Procedure (Expanded), Article 278', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '279', 'If the Court ascertains that the act with which the accused is charged does not constitute a felony but a misdemeanour or a contravention, or if the relevant legal provision has been amended so as to render the act a misdemeanour or a contravention, the Court shall proceed with the case and deliver a judgement.', 'en', 'Code of Criminal Procedure (Expanded), Article 279', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '280', 'If the accused is acquitted or the proceedings discontinued, the civil party shall be ordered to pay the fees and costs of the case. He may be fully or partially exempted from payment if it is found that he acted in good faith or if it was the Public Prosecutor’s Office that initiated the public prosecution. However, if the civil party initiated the public prosecution through a direct complaint, thereby acquiring the status of a civil party, he may not be exempted. If he paid a sum of money in advance in connection with his civil action, the amount in excess of the fees and costs of the case shall be reimbursed.', 'en', 'Code of Criminal Procedure (Expanded), Article 280', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '281', 'The judgement delivered by the Criminal Court shall be recorded in a special register of judgements. The original copy of the judgement shall be kept in the case file and shall be signed by the bench that delivered the judgement and by the clerk. Section IV Rules governing the prosecution of an accused who is a fugitive from justice', 'en', 'Code of Criminal Procedure (Expanded), Article 281', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '282', 'If the Indictment Division decides to indict a person, it shall issue an arrest warrant against him. The Public Prosecutor’s Office shall serve the accused with a copy of the indictment, the list of prosecution witnesses and the arrest warrant, in accordance with the rules laid down in Articles 147, 148 and 149 of this Code, and shall refer the case file to the Criminal Court together with its statement of charges based on the indictment. No actions may be taken that are contrary to the provisions of the indictment.', 'en', 'Code of Criminal Procedure (Expanded), Article 282', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '283', 'As soon as the file is referred to the Court, the President shall convene a sitting to examine it. He shall issue a summons requiring the accused to surrender to the Court twenty-four hours before the beginning of the proceedings. If the summons is served and he fails to surrender to the Court, the Court shall try him in absentia and regard him as a fugitive from justice. It shall order the enforcement of an arrest warrant against him and deprive him of his civil rights, prevent him from disposing of his property and from bringing any case unrelated to his personal circumstances during the period of his flight, and to appoint a trustee to administer his property during that period. The trustee may not dispose of the convicted person’s property without special permission from the Criminal Court. The Public Prosecutor’s Office shall inform the property registration department of the Court’s decision in this regard so that it may be noted automatically on the pages pertaining to the property of the accused.', 'en', 'Code of Criminal Procedure (Expanded), Article 283', 'Property law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '284', 'The summons shall be served on the accused by way of publication and by posting it for a period of ten days at the entrance to his last place of residence, displaying it in the public square of his town or village, and posting it at the entrance to the courtroom. English version (STL Draft Official Translation of Arabic) Version 1.0 70 If the accused has no domicile or no known place of residence in Lebanon, he shall be notified exceptionally through publication of the decision, at the State’s expense, in two local newspapers designated by the Court and in the Official Journal. It shall also be published by posting it at the entrance to the registry of the Criminal Court.', 'en', 'Code of Criminal Procedure (Expanded), Article 284', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '285', 'A fugitive accused may not be represented by counsel at court proceedings conducted in absentia. However, a person appointed by him may present an excuse on his behalf after providing evidence of his having been appointed to represent him. If the Court accepts the excuse, after verifying its validity, it shall defer the proceedings until a later date. If the accused does not surrender to the Court twenty-four hours before the new date set, the trial in absentia shall proceed.', 'en', 'Code of Criminal Procedure (Expanded), Article 285', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '286', 'After the Court has decided to try an accused in absentia, the President shall order the reading of the indictment, the writ of summons and the record of its publication and display. It shall then hear the testimony of the civil party and the arguments of the Public Prosecutor’s Office and shall close the proceedings.', 'en', 'Code of Criminal Procedure (Expanded), Article 286', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '287', 'The Court, after reaching a firm conviction, shall deliver its judgement, either by acquitting or convicting him, and imposing a sentence and confirming that his immovable and movable property is administered by a trustee, whom it shall appoint if he was not appointed during the proceedings, and shall confirm its decision to enforce the arrest warrant issued against the accused. The accused shall remain deprived of his civil rights from the date of delivery of the judgement until the expiry of the prescription period applicable to the sentence imposed until he surrenders to justice or until his death.', 'en', 'Code of Criminal Procedure (Expanded), Article 287', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '288', 'The Public Prosecutor’s Office shall have a summary of the judgement published in the Official Journal and in a local daily newspaper within eight days of the date of its delivery. A copy thereof shall be posted at the entrance to the last place of residence of the accused; another shall be displayed in the public square of his town or village; and a third shall be posted at the entrance to the courtroom of the Criminal Court. The summary shall also be communicated to the Secretary of the Land Registry. The judgement shall enter into force on the date following its publication in the Official Journal.', 'en', 'Code of Criminal Procedure (Expanded), Article 288', 'Property law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '289', 'Throughout the entire period that the property of the fugitive convicted person is being administered by the trustee, his wife, children, parents, and anyone in respect of whom he is the legal provider, may file a petition concerning the trustee with the Summary Affairs Judge whose office is located within the area of jurisdiction of the Criminal Court that delivered the judgement, requiring the trustee to grant them monthly maintenance which shall be levied on the convicted person’s property. The Judge shall issue a decision specifying the amount of the maintenance, taking into account the circumstances and needs of each of the petitioners. The civil party may also file an application concerning the trustee with the same Summary Affairs Judge, requiring the trustee to pay him an interim advance in respect of the damages awarded to him. The decision shall be applicable to the immovable and movable property of the convicted person through the Enforcement Department.', 'en', 'Code of Criminal Procedure (Expanded), Article 289', 'Property law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '290', 'If the Court ascertains that insufficient investigations have been undertaken to convict the fugitive accused, it shall delegate one of its members to undertake a supplementary investigation in accordance with the normal rules and to add it to the case file. It shall then deliver a judgement on the case. English version (STL Draft Official Translation of Arabic) Version 1.0 71 Where it ascertains that there is insufficient evidence against him, it shall acquit him, or it shall discontinue the proceedings if it considers that the act with which he is charged does not constitute an offence or does not carry a penalty, or that he is not accountable where it ascertains that he can invoke a justifiable ground. It may also redefine the act charged if it constitutes a misdemeanour and sentence him for a misdemeanour.', 'en', 'Code of Criminal Procedure (Expanded), Article 290', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '291', 'The conviction of a fugitive accused of a felony may not be challenged or appealed before the Court of Cassation. If the Criminal Court characterized the act described in the indictment as a misdemeanour, the person convicted in absentia may challenge the judgement before it. The challenge shall be governed by the procedure applicable before the Appeal Court when ruling on misdemeanours. If the Court decides to discharge the convicted person of the count of felony and to compel him to pay damages, he may file an objection against the award of damages within fifteen days of the date of receiving notice thereof. If a civil action for a felony is extinguished as a result of the expiry of the ten-year prescription period, the accused person sentenced to pay damages to the civil party may appeal the judgement within fifteen days of the date of his notification thereof. In all cases in which an objection is filed against the amount of personal damages awarded, the Court shall examine the basis of assessment of the damages awarded in the light of Articles 133 and 134 of the Obligations and Contracts Act. The civil part of the judgement in absentia shall be confirmed, once the notification procedures have been completed, pursuant to the relevant provisions of the civil rules. The beneficiary of the adjudication shall receive enforceable personal damages pursuant to the rules governing the enforcement of civil judgements. If the person convicted in absentia is acquitted or it is ruled that the proceedings against him should be discontinued, he may sue the enforcer for unjust enrichment.', 'en', 'Code of Criminal Procedure (Expanded), Article 291', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '292', 'If the fugitive convicted person surrenders or is arrested before the extinction of the sentence on expiry of the prescription period, the Court shall declare the extinction of the judgement delivered against him in absentia and of the other procedures undertaken from the date on which it was seized of the case. It shall further prosecute the accused in accordance with the normal rules laid down in Articles 236 et sequitur of this Code. It shall deliver its judgement in accordance with those rules. If some witnesses cannot be heard before the Court, it shall suffice to read out and deliberate on the testimony that they gave during the preliminary or judicial investigation.', 'en', 'Code of Criminal Procedure (Expanded), Article 292', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '293', 'The flight of one of the co-accused may not be invoked as a ground for deferral of the trial or any delay in hearing the case against the other accused.', 'en', 'Code of Criminal Procedure (Expanded), Article 293', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '294', 'If the convicted person who is a fugitive from justice is arrested and denies his identity, the Criminal Court that delivered the judgement against him shall verify his identity. English version (STL Draft Official Translation of Arabic) Version 1.0 72 Chapter IV The Court of Cassation Section I Jurisdiction of the Court of Cassation', 'en', 'Code of Criminal Procedure (Expanded), Article 294', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '295', 'The Court of Cassation has jurisdiction in the following cases: (a) Applications to set aside judgements delivered by Criminal Courts and rulings issued by Criminal Appeal Courts and the Indictment Division; (b) Other applications to set aside falling within its jurisdiction pursuant to special laws; (c) Applications for retrial of criminal cases; (d) Applications for designation of a judicial authority; (e) Applications for transfer of a case; (f) Offences committed by Judges. Section II Grounds for setting aside judgements delivered in cases concerning felonies', 'en', 'Code of Criminal Procedure (Expanded), Article 295', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '296', 'Judgements delivered by Criminal Courts may be set aside on any of the following grounds: (a) Delivery of the judgement by a body that was not legally constituted; (b) A breach of the law or an error of interpretation or application of the law; (c) A breach of the rules of jurisdiction; (d) Non-compliance with the applicable procedures entailing nullity, or infringement of fundamental standards during the trial; (e) A judgement concerning an offence that was not mentioned in the indictment, or against a person who was not charged therein; (f) Failure to rule on a plea or ground of defence or an application filed by a party to the case, or a judgement exceeding the content of the application; (g) A non-reasoned judgement, or a discrepancy between the reasoning and the judgement clause or a discrepancy within the judgement clause itself; (h) Distortion of the facts or of the clear content of the documents presented in the case file; (i) Lack of a legal basis; (j) Judgements imposing the death penalty.', 'en', 'Code of Criminal Procedure (Expanded), Article 296', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '297', 'A party to a case may not appeal against a judgement on the ground of a breach of a legal rule established in the interests of another party.', 'en', 'Code of Criminal Procedure (Expanded), Article 297', 'Banking and credit', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '298', 'The Public Prosecutor’s Office and the convicted person may file an application to set aside a judgement on one or more of the grounds of cassation set out in Article 296 of this Code. If it English version (STL Draft Official Translation of Arabic) Version 1.0 73 is set aside on the basis of an application by either of them, the public prosecution shall be conducted before the Court of Cassation, which shall proceed on the basis of the rules applicable to a Criminal Court and shall issue a final ruling on the case. An application to set aside filed by the civil party shall be confined to the civil portion of the judgement or the appealed decision. If the appealed judgement acquitted the accused, discontinued the proceedings, or found that he was unaccountable, he shall not be tried as a detainee before the Court of Cassation unless a reasoned decision is taken to place him in detention. The provisions of Article 108 of this Code shall be applicable. If the judgement by the Public Prosecutor’s Office led to the accused being charged or convicted, the person concerned shall be kept in custody during his trial at the Court of Cassation in accordance with the provisions of Article 108 of this Code.', 'en', 'Code of Criminal Procedure (Expanded), Article 298', 'Family law', 'Criminal Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CRIM-002-EXPANDED', '299', 'An application to set aside filed by a person sentenced for a felony shall be admissible if he is in detention or if he has served his sentence. The Court of Cassation may not release a detained convicted person before setting aside the contested judgement.', 'en', 'Code of Criminal Procedure (Expanded), Article 299', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '300', 'If the penalty imposed in the contested judgement is that applicable by law to the offence, the convicted person may not file an application to set it aside on the ground of an error in citation of the legal clause applied.', 'en', 'Code of Criminal Procedure (Expanded), Article 300', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '301', 'The civil party may appeal against the judgement if the personal damages awarded are less than those claimed. Section III Grounds of cassation in cases concerning misdemeanours and contraventions', 'en', 'Code of Criminal Procedure (Expanded), Article 301', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '302', 'With the exception of judgements delivered by a body that was not legally constituted, decisions regarding jurisdiction and extinction of the public prosecution due to expiry of the prescription period, an amnesty, or failure to bring proceedings, an application to set aside may not be filed in cases concerning misdemeanours, save on the grounds set out in Article 296 of this Code, provided that there was a discrepancy in the legal definition of the act by the Judges at first and second instance.', 'en', 'Code of Criminal Procedure (Expanded), Article 302', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '303', 'Subject to the provisions of the preceding article, only the Public Prosecutor’s Office may file an application to set aside rulings made by the Appeal Court concerning contraventions on the ground of the legal characterization if it considers that the contravention should be characterized as a misdemeanour.', 'en', 'Code of Criminal Procedure (Expanded), Article 303', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '304', 'A person who challenges an appeal ruling may not invoke grounds unrelated to the content of the ruling or outside the scope of the proceedings that led to the ruling.', 'en', 'Code of Criminal Procedure (Expanded), Article 304', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '305', 'The Court of Cassation may not stay the enforcement of a sentence pertaining to a misdemeanour or a contravention unless it has set it aside. Section IV Grounds for setting aside decisions of the Indictment Division', 'en', 'Code of Criminal Procedure (Expanded), Article 305', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '306', 'With the exception of decisions rendered by a body that was not legally constituted, decisions regarding jurisdiction and extinction of the public prosecution due to expiry of the English version (STL Draft Official Translation of Arabic) Version 1.0 74 prescription period, an amnesty, or failure to bring proceedings in the case judged, an application to set aside may not be filed against final decisions of an Indictment Division except where there was a discrepancy in the legal characterization of the act by the Investigating Judge and the Indictment Division, and on one of the following grounds: 1. A breach of the law or an error of interpretation or application of the law; 2. Non-compliance with the applicable rules entailing nullity, or infringement of fundamental rules relating to an investigation; 3. Distortion of the facts or of the content of the documents contained in the case file; 4. Failure to rule on a plea or ground of defence or an application filed by a party to the case; 5. Lack of a legal basis or defective reasoning.', 'en', 'Code of Criminal Procedure (Expanded), Article 306', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '307', 'Without prejudice to the grounds for cassation set out in the preceding article: (a) The civil party may contest a final ruling that his civil action is inadmissible on the ground of failure to register as a civil party; (b) The civil party and the Public Prosecutor’s Office may contest rulings that stay any ruling by the Indictment Division discharging the accused.', 'en', 'Code of Criminal Procedure (Expanded), Article 307', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '308', 'An accused who is a fugitive from justice may not challenge the indictment before the Court of Cassation unless he surrenders.', 'en', 'Code of Criminal Procedure (Expanded), Article 308', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '309', 'If the Court of Cassation dismisses an application to set aside, it shall confiscate the sum deposited as surety, and it may sentence the person who filed the application to a fine of between 100,000 and 500,000 Lebanese pounds if it considers that he abused the right to litigate.', 'en', 'Code of Criminal Procedure (Expanded), Article 309', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '310', 'When the indictment ordering that the accused be committed for trial at the Criminal Court becomes final and conclusive, and orders that the accused be committed for trial to the Criminal Court, it shall vest that Court with jurisdiction. Section V Procedures and conditions pertaining to an application to set aside Common provisions', 'en', 'Code of Criminal Procedure (Expanded), Article 310', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '311', 'In no case may an application to set aside be filed in respect of interlocutory decisions or rulings that precede the final decision or judgement until after its delivery or concurrently therewith. Decisions or judgements concerning one or more objections raised under Article 73 of this Code are exempted from the foregoing provision. The Criminal Division of the Court of Cassation shall determine whether any aspect of the contested decision or judgement calls for a stay of the investigation or trial and shall take a decision thereon.', 'en', 'Code of Criminal Procedure (Expanded), Article 311', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '312', 'Only persons party to the case may file an application to set aside the judgement or decision rendered thereon. The person filing an application to set aside must have the requisite standing and interest on pain of inadmissibility. English version (STL Draft Official Translation of Arabic) Version 1.0 75', 'en', 'Code of Criminal Procedure (Expanded), Article 312', 'Banking and credit', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '313', 'The following are entitled to file an application to set aside: the Public Prosecutor''s Office at the Court of Cassation, the Public Prosecutor’s Office at the Appeal Court, the Financial Prosecutor’s Office, the civil party, the convicted person, the property administrator and the surety. The challenge by the Public Prosecutor’s Office shall concern the part of the judgement pertaining to the public prosecution; that of the convicted person shall concern the sentence imposed, the personal damages awarded and the costs; and that of the civil party shall be confined to the part of the judgement concerning the civil action. The property administrator and the surety may challenge any judgement or decision requiring them to pay personal damages.', 'en', 'Code of Criminal Procedure (Expanded), Article 313', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '314', 'If one of the convicted persons files an application to set aside a judgement or decision and the other parties do not, the Court of Cassation may not impose a more severe penalty on the convicted person or increase the damages awarded against him.', 'en', 'Code of Criminal Procedure (Expanded), Article 314', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '315', 'Each party to the case may confine its challenge to one aspect of the judgement or decision, which shall be independent from the others.', 'en', 'Code of Criminal Procedure (Expanded), Article 315', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '316', 'The convicted person, the civil party, the property administrator and the surety may file an application to set aside an adversarial judgement delivered by a Criminal Court and an adversarial ruling delivered by a Misdemeanours Appeal Court within fifteen days of the date of its delivery. The Financial Prosecutor’s Office or the Public Prosecutor’s Office at the Appeal Court may file an application to set aside an adversarial judgement or ruling within a month of the date of its delivery. The Public Prosecutor''s Office at the Court of Cassation may file an application to have it set aside within two months of the date of its delivery. An application to set aside may not be filed against a judgement delivered in absentia against an accused who is a fugitive from justice. Each party to the case may file an application to set aside a ruling on an objection issued by a Misdemeanours Appeal Court within the period specified in the first and second paragraphs of this article. The period begins to run with respect to the convicted person, the civil party, the property administrator and the surety on the date of notification of the judgement concerning an objection if it was not delivered adversarially. It begins to run with respect to the Public Prosecutor’s Office at an Appeal Court and the Public Prosecutor''s Office at the Court of Cassation on the date of its delivery.', 'en', 'Code of Criminal Procedure (Expanded), Article 316', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '317', 'An application to set aside shall be filed with the registry of the Court of Cassation or the registry of the Court that delivered the contested judgement. If it is filed with the latter, the Court shall transmit the case file to its Public Prosecutor’s Office within not more than five days of the date of filing so that it may be transmitted to the Public Prosecutor''s Office at the Court of Cassation for immediate referral to the Court. If an application to set aside is filed directly with the Court of Cassation, the Court shall request that the file be transmitted through the Public Prosecutor''s Office at the Court of Cassation.', 'en', 'Code of Criminal Procedure (Expanded), Article 317', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '318', 'In addition to adhering to the time period set in Article 316 of this Code, the application to set aside shall meet all of the following conditions on pain of dismissal on procedural grounds: English version (STL Draft Official Translation of Arabic) Version 1.0 76 (a) It shall contain the names of the litigants and the name of the Court that delivered the contested judgement, and shall indicate the contested judgement and the grounds of the application to set aside; (b) It shall be signed by appeal counsel and shall contain the original document authorizing him to act or a certified copy thereof, a certified copy of the contested judgement or ruling, exempt from the proportionate fee, and a receipt for the deposit with the Treasury of surety of 200,000 Lebanese pounds. The Public Prosecutor’s Office shall not be required to present a copy of the contested judgement with its application or to pay the surety and legal costs.', 'en', 'Code of Criminal Procedure (Expanded), Article 318', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '319', 'Within five days of the date of expiry of the time limit for filing an application, the applicant may present a submission setting out the grounds for the application to set aside. The submission may not include new grounds. The applicant shall be deemed to have elected a domicile at the chambers of his counsel. All notices served at those chambers shall be deemed to be valid if the procedural rules were complied with. The application to set aside shall be recorded in a special register. Each party to the case may consult it and take a true copy thereof. The surety shall be returned to the applicant if the application is admitted or if he withdraws it before a ruling is issued thereon. It shall be forfeited to the Treasury if the application to set aside is dismissed. The convicted person or the civil party shall be exempted from the surety fee in cases concerning felonies. In cases concerning misdemeanours, the exemption shall be subject to the production of a certificate of indigence. The Public Prosecutor’s Office shall be exempted from payment of all fees and costs pertaining to an application to set aside.', 'en', 'Code of Criminal Procedure (Expanded), Article 319', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '320', 'The respondent to the application to set aside shall, within three days of their submission, receive a copy of the application and its attachments and a copy of the explanatory memorandum. He may submit his observations and claims within ten days of the date of notification.', 'en', 'Code of Criminal Procedure (Expanded), Article 320', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '321', 'The Court of Cassation shall examine the application to set aside and the case file. If it ascertains that the application was submitted within the legal time limit and that the other formalities were complied with, it shall declare it formally admissible. It shall then study the grounds of the challenge it contains. If it sets aside the contested decision, it shall hold new public proceedings to examine the case and deliver a judgement on the merits. During the proceedings, it shall apply the rules applicable to the Court that delivered the contested judgement. It shall then issue its ruling on the case. If it dismisses the application to set aside, it shall uphold the contested judgement or decision, order the forfeiture of the surety fee, and sentence the applicant to a fine of between two hundred thousand and one million Lebanese pounds if it ascertains that he abused his right to litigate.', 'en', 'Code of Criminal Procedure (Expanded), Article 321', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '322', 'If the civil party is the only party submitting an application to set aside, only the civil action shall be heard before the Court. The Court of Cassation may not reduce the damages awarded.', 'en', 'Code of Criminal Procedure (Expanded), Article 322', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '323', 'If an application to set aside is submitted by one of several persons convicted of the same offence and the Court of Cassation admits the application in formal terms and on the merits, English version (STL Draft Official Translation of Arabic) Version 1.0 77 concluding that elements of the offence concerning which the contested judgement was delivered were lacking, the other convicted persons shall benefit from the setting aside of the judgement. In such cases, the Public Prosecutor''s Office at the Court of Cassation shall issue a summary of the judgement in respect of each one of them.', 'en', 'Code of Criminal Procedure (Expanded), Article 323', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '324', 'After setting aside the contested judgement or decision, the Court of Cassation shall apply the provisions of Articles 276 and 277 of this Code where the circumstances to which they are applicable exist.', 'en', 'Code of Criminal Procedure (Expanded), Article 324', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '325', 'If the Court of Cassation decides to dismiss the application to set aside on procedural grounds or on the merits, the clerk of the court shall draft a summary of the decision, to be signed by the President of the Court, and shall transmit it within three days of the date of its delivery to the Public Prosecutor''s Office at the Court of Cassation which in turn shall forward it to the Public Prosecutor’s Office at the Appeal Court that delivered the contested judgement with a view to its enforcement.', 'en', 'Code of Criminal Procedure (Expanded), Article 325', 'Termination of employment', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '326', 'Subject to the provisions governing a retrial or those set out in Articles 741 et sequitur of the Code of Civil Procedure, the decisions of the Court of Cassation shall not be open to any form of review. Section VI Application to set aside in the interests of the law', 'en', 'Code of Criminal Procedure (Expanded), Article 326', 'Banking and credit', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '327', 'Where a Criminal Court delivers a judgement or an Appeal Court issues a ruling that becomes final on expiry of the time limit for an application to set aside, the Public Prosecutor''s Office at the Court of Cassation may, of its own motion or pursuant to a request from the Minister of Justice, file an application to set aside solely in the interests of the law within one year of its delivery. If the Court of Cassation decides to annul the contested judgement or decision, the convicted person shall benefit from the annulment and shall not suffer prejudice therefrom. In all cases, the judgement shall remain in force for the benefit of the civil party. Section VII Application for a retrial', 'en', 'Code of Criminal Procedure (Expanded), Article 327', 'Banking and credit', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '328', 'The Court of Cassation has jurisdiction to consider applications for a retrial. An application for a retrial may be submitted in cases concerning felonies and misdemeanours in the following circumstances: (a) Where, after a person has been convicted of homicide, sufficient evidence comes to light that the alleged victim of the homicide is still alive; (b) Where, after a person was convicted of a felony or misdemeanour, another person is convicted of the same offence, defined in the same terms, provided that evidence ensues therefrom of the innocence of one of the convicted persons; (c) Where a person was convicted on the basis of testimony given by another person which was subsequently found to be perjury in a final judgement; (d) Where, following conviction, a new event occurs, a new fact comes to light, or new documents are discovered that were unknown to the Court during the trial and that are liable to constitute evidence of the innocence of the convicted person. English version (STL Draft Official Translation of Arabic) Version 1.0 78 The extinction of the sentence imposed due to expiry of the prescription period shall not preclude the hearing of an application for a retrial.', 'en', 'Code of Criminal Procedure (Expanded), Article 328', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '329', 'The convicted person shall submit the application to the Criminal Division of the Court of Cassation through the Public Prosecutor at the Court. The application may be submitted by his legal representative in the event of incapacity or if his absence has been confirmed by a judicial ruling, or by one of his heirs or their executors if he is deceased. The application shall be accompanied by a certified true copy, exempt from fees, of the judgement to be reviewed and of the substantiating evidence, the document authorizing counsel who signed the application to act, and a receipt for the deposit of surety amounting to 200,000 Lebanese pounds. The Public Prosecutor at the Court of Cassation shall refer the application to the competent Criminal Division of the Court, together with his submissions, within one week.', 'en', 'Code of Criminal Procedure (Expanded), Article 329', 'Guarantees and sureties', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '330', 'Where the Court of Cassation finds an application for a retrial admissible, it shall consider the merits of the case. It may conduct a supplementary investigation if necessary.', 'en', 'Code of Criminal Procedure (Expanded), Article 330', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '331', 'If the Court, on considering an application for a retrial, annuls the contested judgement delivered against one of a number of living convicted persons because the act of which he was convicted has been decriminalized or because the convicted person is exempted from punishment, this annulment shall suffice. If the annulment is based on decriminalization of the acts tried, all other convicted persons shall benefit therefrom.', 'en', 'Code of Criminal Procedure (Expanded), Article 331', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '332', 'Where an application for a retrial is submitted after the death or loss of capacity of the convicted person through one of the persons mentioned in Article 329 of this Code, the Court shall consider the application. If it decides to annul the contested judgement and to acquit the convicted person or to revoke the penalties, it shall order that its judgement be displayed on the Court’s notice board in the place where the offence occurred, in the place of residence of the convicted person, in the Official Journal, and in two local daily newspapers. The State shall bear the costs of publication.', 'en', 'Code of Criminal Procedure (Expanded), Article 332', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '333', 'Article 333 of the legislation previously in force stipulated the following: “If the Court considers that the act with which the accused is charged does not constitute a felony but a misdemeanour or a contravention, it shall remain seized of the case and shall deliver a judgement.” However, this provision did not specify whether the fugitive accused is entitled, where his act is found to be a misdemeanour or a contravention, to challenge the judgement delivered against him in absentia. The drafters of the Code remedied this flaw by stipulating that the Judge’s decision to charge the accused with a felony cannot be challenged and is not open to an application to set aside. However, if a Criminal Court classifies the act referred to in the indictment decision as a misdemeanour, the person convicted in absentia may challenge the judgement before it. The rules followed before the Misdemeanours Appeal Court are applicable to this challenge. If the convicted person is exempted from the penalty for a felony but is required to pay personal damages, he may also challenge that judgement. If the civil action is not extinguished when the public prosecution for a felony is extinguished by the expiry of the prescription period, the convicted person may appeal that judgement by taking action against the civil party. The legislation previously in force required that the accused should have a properly appointed advocate present during questioning and throughout the trial. However, it failed to provide for a situation in which the accused insisted on refusing to appoint counsel to represent him. This problem arose during the trial of Dr. Samir Geagea before the Judicial Council when he refused to accept any counsel appointed to defend him after his own counsel withdrew from the proceedings. The Draft Code remedied this flaw as follows: If the accused insists that no defence counsel shall be appointed, the proceedings shall be conducted without counsel. The impediment to the continuat', 'en', 'Code of Criminal Procedure (Expanded), Article 333', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '334', 'The applicant for a retrial shall pay an advance in respect of the costs of the case pending delivery of a decision on his application. The subsequent costs shall be paid by the State. English version (STL Draft Official Translation of Arabic) Version 1.0 79 Section VIII Application for the designation of a judicial authority', 'en', 'Code of Criminal Procedure (Expanded), Article 334', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '335', 'In the event of a jurisdictional dispute between judicial authorities, the Criminal Division of the Court of Cassation shall designate the competent judicial authority. Where an offence occurs and where two Investigating Judges seize themselves of the same offence, or two courts take up the same case after each declared that it had jurisdiction, or where each of two Investigating Judges or courts declare that they lack jurisdiction, or where a court decides that it lacks jurisdiction to try a case referred to it pursuant to an order issued by an Investigating Judge or an Indictment Division, and where the jurisdictional dispute hampers the course of justice owing to the definitive nature of two contradictory rulings in the same case, the dispute shall be settled by the designation of a judicial authority. The provisions of this Article shall be applicable if a dispute arises between an ordinary court and a special court.', 'en', 'Code of Criminal Procedure (Expanded), Article 335', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '336', 'The Public Prosecutor’s Office, the civil party, and the defendant may file an application for the designation of a judicial authority with the Court of Cassation, which shall order the Public Prosecutor’s Office to provide it with copies of the documents pertaining to the case before the two judicial authorities involved in the dispute. A copy of the application for the designation of a judicial authority shall be served on each party to the case and they may each respond to it within ten days of the date of service.', 'en', 'Code of Criminal Procedure (Expanded), Article 336', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '337', 'When the judicial authorities involved in the dispute are informed of the application for the designation of a judicial authority, they shall suspend delivery of a final decision in the case. Interlocutory measures and investigations may continue pending the designation of a judicial authority.', 'en', 'Code of Criminal Procedure (Expanded), Article 337', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '338', 'The Criminal Division of the Court of Cassation shall consider the application for the designation of an authority after the expiry of the ten-day time limit. It shall take a decision in chambers on the designation of an authority within a period not exceeding one month. It may also annul the measures and actions taken by the judicial authority that is divested of the case. Its decision shall not be open to any kind of review. The two judicial authorities involved in the dispute shall comply with the ruling.', 'en', 'Code of Criminal Procedure (Expanded), Article 338', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '339', 'Where the civil party or the defendant was not justified in filing his application for the designation of a judicial authority, he shall be sentenced to a fine of between two hundred thousand and one million Lebanese pounds and to pay damages to his adversary where a claim has been filed. Section IX Application for transfer of the case', 'en', 'Code of Criminal Procedure (Expanded), Article 339', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '340', 'A Criminal Division of the Court of Cassation shall rule on applications for the transfer of a case from one judicial authority to another. It shall relieve one authority of the case, at the English version (STL Draft Official Translation of Arabic) Version 1.0 80 investigative or trial stage, and refer it to another authority at the same level to continue the proceedings, because it proved impossible to constitute the authority with original jurisdiction or because the investigation or trial was suspended, or in order to maintain public safety, to ensure the proper administration of justice or on the ground of legitimate suspicion. Only the Public Prosecutor at the Court of Cassation may request that a case be transferred on the ground of maintenance of public safety. Where the judicial authority in respect of which an application for transfer is filed is a Criminal Division of the Court of Cassation, the full bench of the Court of Cassation shall rule on the application. The Public Prosecutor at the Court of Cassation may apply to transfer a case for one of the reasons set out in the first paragraph, of his own motion or pursuant to an application from the Appeal Court Prosecutor, the Financial Prosecutor, the civil party, the defendant or the Minister of Justice on the grounds set forth in the first paragraph. The application for a transfer shall be served on all parties to the case, who may respond to it within ten days of the date of service. The filing of the application shall not be suspensive unless the Court of Cassation decides otherwise.', 'en', 'Code of Criminal Procedure (Expanded), Article 340', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '341', 'Where two Investigating Judges attached to a single department are seized with related offences, the First Investigating Judge from the court in question may appoint one of them to proceed with the investigation. Where the two Investigating Judges are attached to separate departments, the competent Criminal Division of the Court of Cassation, acting on an application from the Public Prosecutor at the Court, shall appoint an Investigating Judge to proceed with the case.', 'en', 'Code of Criminal Procedure (Expanded), Article 341', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '342', 'Any ruling on the transfer of a case delivered by the Court of Cassation shall be served on all the parties to the case through the Public Prosecutor’s Office at the Court of Cassation. This ruling shall not be subject to any kind of appeal. If the Court of Cassation dismisses the application, its ruling shall not preclude the submission of another application, provided that it is based on facts that come to light after the date of the first application.', 'en', 'Code of Criminal Procedure (Expanded), Article 342', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '343', 'Where the civil party or the defendant files an application for transfer of the case and the application is dismissed by the Court of Cassation, it may sentence the applicant to a fine of between two hundred thousand and one million Lebanese pounds and award damages to the adversary if he has filed a claim. In all these cases, the ruling of the Court of Cassation shall not be open to any kind of review. Section X Offences committed by Judges', 'en', 'Code of Criminal Procedure (Expanded), Article 343', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '344', 'The Court of Cassation has jurisdiction to try offences committed by Judges, either outside the context of their duties or when they arise from or were committed in the course of the performance of their duties.', 'en', 'Code of Criminal Procedure (Expanded), Article 344', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '345', 'Where a Judge of a court of first instance, an Investigating Judge, an Advocate- General attached to the Public Prosecutor’s Office of an Appeal Court or a Financial or Military Court, an Advocate-General attached to an Appeal Court, an Advocate-General attached to an Administrative Court or the Audit Court, or an assistant Advocate-General attached to the Council of State commits an English version (STL Draft Official Translation of Arabic) Version 1.0 81 offence constituting a misdemeanour outside the context of the performance of his duties, he shall be prosecuted by the Public Prosecutor''s Office at the Court of Cassation of its own motion or on the basis of a complaint from the aggrieved party. The case shall be tried before a Criminal Division of the Court of Cassation.', 'en', 'Code of Criminal Procedure (Expanded), Article 345', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '346', 'Where the misdemeanour is attributable to a President of an Appeal Division, a Public Prosecutor at an Appeal Court, the Financial Prosecutor, the Government Commissioner, a Court of Cassation Judge, a member of the Public Prosecutor''s Office at the Court of Cassation or a First Investigating Judge, he shall be prosecuted by the Public Prosecutor''s Office at the Court of Cassation of its own motion or on the basis of a complaint from the aggrieved party. The case shall be tried before the full bench of the Court of Cassation.', 'en', 'Code of Criminal Procedure (Expanded), Article 346', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '347', 'If the act attributable to a Judge, irrespective of his level, constitutes a felony, the First President of the Court of Cassation shall appoint a Judge of at least the same level as the defendant Judge to hear the case. The Public Prosecutor at the Court of Cassation shall lay the charges and conduct the public prosecution.', 'en', 'Code of Criminal Procedure (Expanded), Article 347', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '348', 'If the circumstances make it necessary to detain the Judge charged with a felony, the Judge conducting the investigation shall issue an arrest warrant against him. However, its enforcement shall require the approval of the First President of the Court of Cassation. The Judge shall be detained in a special place to be determined by the Public Prosecutor at the Court of Cassation.', 'en', 'Code of Criminal Procedure (Expanded), Article 348', NULL, 'Criminal Law');
INSERT INTO chunks (law_id, article_number, chunk_text, language, citation_label, subject, category) VALUES
  ('LB-CRIM-002-EXPANDED', '349', 'The Judge entrusted with the investigation shall consult the Public Prosecutor at the Court of Cassation in all cases in which the law requires an Investigating Judge to consult the Public Prosecutor’s Office at an Appeal Court. The Judge conducting the investigation may substitute for detention of the defendant Judge supervisory measures designed to curb his mobility or freedom to travel. If he violates any of them, or if the investigator ascertains that they are ineffective, he shall issue an arrest warrant pursuant to Article 348 of this Code. The Judge entrusted with the investigation shall follow the rules applied by an Investigating Judge in criminal cases. Appeals against the rulings of the Judge entrusted with the investigation may be lodged with the panel provided for in Article 350 of this Code, in accordance with the rules applicable to appeals against the rulings of an Investigating Judge.', 'en', 'Code of Criminal Procedure (Expanded), Article 349', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '350', 'The investigation file shall be submitted to a panel composed of three Judges of at least the same level as the defendant Judge. They shall be appointed by the Higher Council of the Judiciary. The panel shall be presided over by the most senior Judge, or by a President appointed by the First President of the Court of Cassation. The panel shall perform the duties of an Indictment Division. It shall refer the accused to a Criminal Division of the Court of Cassation if he is one of the Judges mentioned in Article 345 of this Code and to the full bench of the Court of Cassation if he is one of the Judges mentioned in Article 346 of this Code. If the panel ascertains that there is insufficient evidence to indict him, or that elements of the offence are lacking, it shall stay the prosecution of the defendant Judge. English version (STL Draft Official Translation of Arabic) Version 1.0 82 The rulings delivered by the panel are not open to any kind of review.', 'en', 'Code of Criminal Procedure (Expanded), Article 350', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '351', 'Articles 344 to 350 inclusive of this Code shall be applicable to offences committed by Judges in circumstances arising from the performance of their duties. All these Articles shall be applicable to Judges of the Council of State, Judges of the Audit Court and retired Judges holding honorary office.', 'en', 'Code of Criminal Procedure (Expanded), Article 351', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '352', 'The party harmed by the offence attributed to the Judge may claim damages pursuant to the public prosecution. He may not bring a direct action initiating a public prosecution. Where the offence committed did not arise from the performance of or in connection with judicial duties, he shall claim damages against the defendant Judge. However, where it arose from or in connection with the performance of such duties, the aggrieved party may bring an action against the State, the Judge, or against both of them.', 'en', 'Code of Criminal Procedure (Expanded), Article 352', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '353', 'If a Judge charged with a misdemeanour or a felony arising from or committed outside the context of the performance of his duties had an accomplice, accessory, inciter or concealer, the prosecution, investigation and trial shall also apply to such persons. If the investigation fails to establish the identity of such persons, or if it is impossible or too late to prosecute them, this shall not affect the prosecution of the Judge and the hearing of his case.', 'en', 'Code of Criminal Procedure (Expanded), Article 353', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '354', 'If the President of the Higher Council of the Judiciary, the President of the Council of State, the Public Prosecutor at the Court of Cassation, the President of the Audit Court or the President of the Judicial Inspectorate commits an offence that constitutes either a misdemeanour or a felony outside the context of, during or in connection with the performance of his duties, he shall be tried before a panel composed of five Judges appointed by a decree of the Council of Ministers based on a proposal by the Minister of Justice. The members of the panel shall be selected from among active Judges or retired Judges holding honorary office on condition that no Judge whose level is lower than level XVII is selected. The Public Prosecutor at the Court of Cassation shall personally conduct the prosecution unless he was one of the persons who committed or participated in the commission of the offence. In that case, a Judge at a level no lower than level XVII shall be appointed by a decree of the Council of Ministers to take his place in charge of the proceedings solely in connection with the offence in question. The Minister of Justice, with the consent of the Higher Council of the Judiciary, shall appoint a Judge of at least the same level as the Judge appearing before him to investigate the offence. The rules laid down in Articles 345 et sequitur shall be applicable to the prosecution and trial of the aforementioned persons. The President of the appointed panel of Judges shall perform the duties of the First President of the Court of Cassation with regard to authorizing the detention of the defendant Judge. English version (STL Draft Official Translation of Arabic) Version 1.0 83 Chapter V The Judicial Council', 'en', 'Code of Criminal Procedure (Expanded), Article 354', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '355', 'Cases shall be referred to the Judicial Council pursuant to a decree of the Council of Ministers.', 'en', 'Code of Criminal Procedure (Expanded), Article 355', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '356', 'The Judicial Council shall try the following offences: (a) The offences defined in Articles 270 to 336 inclusive of the Criminal Code; (b) The offences defined in the Act of 11 January 1958; (c) All offences pertaining to weapons and ordnance transactions concluded or being concluded by the Ministry of National Defence, as well as related or ancillary offences, particularly those defined in Articles 351 to 366 inclusive, Articles 376, 377 and 378 and Articles 453 to 472 inclusive of the Criminal Code, and in Articles 138 and 141 of the Code of Military Justice. Cases concerning such offences before the military and ordinary courts shall be referred to the Judicial Council, which shall exercise both civil and military jurisdiction pursuant to the referral decree.', 'en', 'Code of Criminal Procedure (Expanded), Article 356', 'Nationality and citizenship', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '357', 'The Judicial Council is composed of the First President of the Court of Cassation as President and four Court of Cassation Judges appointed by a decree of the Council of Ministers based on a proposal of the Minister of Justice and the consent of the Higher Council of the Judiciary. The decree shall designate one or more additional Judges to replace the principal Judge in the event of his death, withdrawal, dismissal or end of service. The Public Prosecution Service shall be represented in the Judicial Council by the Public Prosecutor at the Court of Cassation or by one of his assistants whom he delegates.', 'en', 'Code of Criminal Procedure (Expanded), Article 357', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '358', 'If the First President of the Court of Cassation is unable to preside over the Council bench, the most senior appointed member shall preside.', 'en', 'Code of Criminal Procedure (Expanded), Article 358', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '359', 'The Judicial Council shall be convened at the Palace of Justice in Beirut, at the place in which the offence occurred, if necessary, or in any other place designated by the President if it cannot be convened at the Palace of Justice in Beirut.', 'en', 'Code of Criminal Procedure (Expanded), Article 359', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '360', 'The Public Prosecutor at the Court of Cassation or an Advocate-General delegated by him from the Public Prosecutor''s Office at the Court of Cassation shall initiate and exercise the public prosecution. The investigation shall be conducted by an Investigating Judge appointed by the Minister of Justice with the consent of the Higher Council of the Judiciary.', 'en', 'Code of Criminal Procedure (Expanded), Article 360', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '361', 'The Public Prosecutor at the Court of Cassation shall present the charges to the Judge investigating the offence and refer the investigation file to him.', 'en', 'Code of Criminal Procedure (Expanded), Article 361', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '362', 'The judicial investigator may issue all warrants required by the investigation without being requested by the Public Prosecutor''s Office. His decisions in this regard are not open to any kind of review. He shall deal with the case in an objective manner. If the investigation reveals the existence of an accomplice to the offence, he shall question him as a defendant even if his name is not among those against whom charges were brought by the Public Prosecutor''s Office. The Public Prosecutor''s Office may bring charges subsequently against any person who was not mentioned in the original statement and the investigator shall question him as a defendant. English version (STL Draft Official Translation of Arabic) Version 1.0 84', 'en', 'Code of Criminal Procedure (Expanded), Article 362', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '363', 'Subject to the provisions of the preceding article, the judicial investigator shall apply the rules followed before the Investigating Judge, except for the period of detention stipulated in', 'en', 'Code of Criminal Procedure (Expanded), Article 363', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '364', 'On completion of the investigation, the Public Prosecutor''s Office at the Court of Cassation shall present its submissions on the merits. The judicial investigator shall decide, in the light of the results of the investigation and the documents pertaining to the case, either to stay the prosecution of the defendant or to indict him and refer him to the Judicial Council. The indictment issued by the judicial investigatorcomply with the rules governing the issuance of indictments by the Indictment Division. The rules governing the drafting of the bill of indictment by an Indictment Division shall be applicable to the indictment decision issued by the judicial investigator. The judicial investigator shall issue an arrest warrant against the accused. If he failed to issue a warrant, he shall do so pursuant to a request by the Public Prosecutor at the Court of Cassation even if he is no longer seized of the case. If the judicial investigator is deceased or unable to do so, the President of the Judicial Council shall issue an arrest warrant against the accused at the beginning of his trial.', 'en', 'Code of Criminal Procedure (Expanded), Article 364', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '365', 'The Public Prosecutor''s Office at the Court of Cassation shall serve a copy of the indictment and the list of prosecution witnesses on each of the accused five days before the date of the hearing. Similarly, the accused shall notify the Public Prosecutor at the Court of Cassation of the list of defence witnesses five days before the date of the hearing. The civil party may submit a list of his witnesses within the same time limit and shall present a copy thereof to the Public Prosecutor''s Office at the Court of Cassation and the accused five days before the date of the hearing.', 'en', 'Code of Criminal Procedure (Expanded), Article 365', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '366', 'The trial shall be held, either adversarially or in absentia, before the Judicial Council in accordance with the rules governing proceedings before a Criminal Court. The Council shall deliver its judgement in accordance with the same rules. The judgements of the Judicial Council are not open to any kind of review of an ordinary or special nature.', 'en', 'Code of Criminal Procedure (Expanded), Article 366', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '368', 'The Criminal Judge seized of a public prosecution has jurisdiction to rule on any plea raised before him unless it constitutes a preliminary question or the law provides otherwise.', 'en', 'Code of Criminal Procedure (Expanded), Article 368', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '369', 'The following shall constitute suspensive interlocutory matters: (a) Matters pertaining to immovable property and other real property entitlements; (b) Matters pertaining to citizenship; (c) Matters pertaining to civil status, except for determination of age; (d) Administrative matters; (e) Civil matters, where decisions concerning them affect the determination of elements of the offence charged, provided that they were pending before the competent civil judicial authority prior to the initiation of the public prosecution; (f) Criminal matters, where the determination regarding elements of the offence depends on the decision rendered in that regard.', 'en', 'Code of Criminal Procedure (Expanded), Article 369', 'Property law', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '370', 'When an interlocutory matter is raised before him, the Criminal Judge shall ascertain, before suspending consideration of the case with which he is seized, whether it is based on serious grounds and whether a ruling thereon is necessary and relevant to a ruling in the criminal case. If the Criminal Judge decides to admit a plea concerning an interlocutory matter, he shall set a time period for consultation of the competent legal authority. If the person who raised the plea complies with the time limit, the Criminal Judge shall suspend the hearing of the case pending a ruling on the interlocutory matter. If he does not, he shall proceed with the case. The Criminal Judge who defers a decision on the case shall not be prevented from taking any investigative measures that he considers necessary or urgent. English version (STL Draft Official Translation of Arabic) Version 1.0 86 Part VIII Cases of forgery Chapter I Original cases of forgery', 'en', 'Code of Criminal Procedure (Expanded), Article 370', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '371', 'Where the Public Prosecutor learns of the existence of a document in an official depository that is alleged to be a forgery, he shall attend the scene in person or appoint a colleague with the task of carrying out all the necessary examinations and checks there. He may also order that suspected forged documents be taken to his office. The person suspected of having made the forgery and his accomplices shall be brought before the Investigating Judge.', 'en', 'Code of Criminal Procedure (Expanded), Article 371', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '372', 'When the Investigating Judge is seized of the case, he shall instruct his clerk to draft a detailed record describing the document alleged to be a forgery. The Investigating Judge and his clerk shall sign the record as well as the document, noting on it “Not to be modified”. The suspect document and the record shall be deposited with the Investigation Department.', 'en', 'Code of Criminal Procedure (Expanded), Article 372', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '373', 'If the document that is alleged to be a forgery was in an official depository, it shall be signed by the head of the responsible department before being transferred to the Investigation Department. He shall hand it over as soon as he is notified of the Investigating Judge’s decision. If he fails to do so, the Investigating Judge shall order that he be brought before him together with the document. If the Investigating Judge ascertains that there is no legal ground for his failure to hand over the document, he shall sentence him to a fine of between two hundred thousand and one million Lebanese pounds. The provisions of this article shall be applicable to any private individual with a suspected forged document in his possession.', 'en', 'Code of Criminal Procedure (Expanded), Article 373', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '374', 'When an official document is seized, a true copy thereof certified by the Investigating Judge and his clerk shall be left with the depositary. If the document was deposited with a public official, the true copy thereof shall replace the original until its return. The official may issue a reproduction of the certified copy indicating that the original is deposited with the Investigating Judge for the purposes of a forgery investigation. If the document forms part of a register from which it cannot be removed, the Investigating Judge may order that the register be transferred to his department.', 'en', 'Code of Criminal Procedure (Expanded), Article 374', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '375', 'It is possible to allege that documents are forgeries even when they have been used in judicial, administrative or other proceedings. Anyone who has made use of an allegedly forged document shall be required to sign it. The document in question shall be placed in a secure depository at the Court with the annotation “Not to be modified”. English version (STL Draft Official Translation of Arabic) Version 1.0 87', 'en', 'Code of Criminal Procedure (Expanded), Article 375', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '376', 'The Investigating Judge may request the services of technical experts to compare the handwriting and signature on the allegedly forged document with any authentic signatures or handwriting. He may require the defendant to take dictation himself or call upon the experts to do so. If the suspect refuses to write, this shall be noted in the record of his interview.', 'en', 'Code of Criminal Procedure (Expanded), Article 376', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '377', 'Ordinary documents may be used for the purpose of collation, conformity or comparison, with the consent of the plaintiff and the defendant. If the person holding the documents is not a public official, he shall be required to hand them over pursuant to the provisions of Article 373 of this Code.', 'en', 'Code of Criminal Procedure (Expanded), Article 377', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '378', 'Investigations in forgery cases shall be conducted in accordance with the rules of criminal procedure applicable to other offences. The Public Prosecutor and the Investigating Judge may enter the homes of any person suspected of counterfeiting official state seals, of forging coins, banknotes and fiscal stamps, of smuggling such counterfeited or forged items into Lebanese territory, or of being involved in their circulation, even if the home of such person is outside their area of jurisdiction. Chapter II Incidental and ancillary cases of forgery', 'en', 'Code of Criminal Procedure (Expanded), Article 378', 'Taxation', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '379', 'The Public Prosecutor’s Office and the other parties may, at any stage of the proceedings, raise an allegation of forgery with respect to any document produced in the case.', 'en', 'Code of Criminal Procedure (Expanded), Article 379', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '380', 'The incidental charge of forgery shall be filed with the registry of the Court hearing the case. The plaintiff shall identify the allegedly forged document and present the supporting evidence.', 'en', 'Code of Criminal Procedure (Expanded), Article 380', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '381', 'The Court hearing the case shall refer the incidental charge to the Public Prosecutor’s Office so that it may present its submission. It may suspend the original case until the relevant legal authority issues a ruling on the incidental forgery case, provided that the ruling in the original case depends on the outcome of the incidental case. If the original case before it relates solely to personal damages, it shall defer the proceedings until a judgement is delivered in the forgery case.', 'en', 'Code of Criminal Procedure (Expanded), Article 381', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '382', 'In the event of a final ruling that no forgery has occurred, the Court that suspended its hearing of the original case on the ground of the incidental charge of forgery shall sentence the person who filed the charge of forgery to a fine of between five hundred thousand and one million Lebanese pounds and to the payment of damages.', 'en', 'Code of Criminal Procedure (Expanded), Article 382', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '383', 'Where an ordinary document is found to be a forgery, the Court shall declare it null and void and destroy it. Where an official document is found to be a forgery, in whole or in part, the Court dealing with the forgery case shall either declare that the document is invalid or shall order that it be restored to its original state by deleting any addition or inserting any deletion. In the latter case, the document shall be attached to a summary of the Court’s judgement. Documents used for the purpose of collation or comparison shall be returned to their respective sources.', 'en', 'Code of Criminal Procedure (Expanded), Article 383', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '384', 'The rules applied in original forgery cases shall also be applicable to incidental forgery cases. English version (STL Draft Official Translation of Arabic) Version 1.0 88 Part IX Measures to be taken in the event of loss of documents pertaining to a case or the judgements delivered thereon', 'en', 'Code of Criminal Procedure (Expanded), Article 384', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '385', 'In the event of the theft, loss or destruction of the original copy of a judgement prior to its enforcement or of all or some of the documents pertaining to a case or an investigation prior to the delivery of a ruling thereon, the procedures set out in the following Articles shall be applied.', 'en', 'Code of Criminal Procedure (Expanded), Article 385', 'Theft and robbery', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '386', 'If a duplicate or a duly certified official copy of the judgement or decision exists, it shall be substituted for the original and deposited place of it. If a certified copy is in the possession of a public official or any other person, the President of the Court that delivered the judgement or decision shall order him to hand it over to the registry of the Court. If he refuses, the provisions of Article 373 of this Code shall be applied to him. The person from whom a certified copy is taken may request a copy thereof free of charge.', 'en', 'Code of Criminal Procedure (Expanded), Article 386', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '387', 'The loss of an original copy of a judgement or decision shall not entail a retrial if all channels of appeal against it have been exhausted. A summary of the decision shall suffice if it is not possible to obtain a certified official copy thereof.', 'en', 'Code of Criminal Procedure (Expanded), Article 387', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '388', 'If all or some of the documents pertaining to a case or investigation are lost before the delivery of a decision, the investigation shall be repeated in whole or in part. If the case is being heard before a court, it shall undertake whatever investigative measures it deems necessary. If the entire case file is lost, the file shall be restored in accordance with the rules in force.', 'en', 'Code of Criminal Procedure (Expanded), Article 388', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '389', 'If the original copy of the judgement or decision is lost and no certified official, summary or certified copy thereof is found, but the order to charge or to indict is found, new proceedings shall be initiated and a new judgement rendered. If there is no order to charge or to indict in the case file and no certified official copy of either document is found, the proceedings shall be repeated from the point at which the documents went missing.', 'en', 'Code of Criminal Procedure (Expanded), Article 389', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '390', 'If all or some of the documents pertaining to a case or investigation are lost, and the original copy or a certified official copy of an appeal against the judgement or decision exists, and if the case is being heard before the Court of Cassation, the trial proceedings shall not be repeated unless the appeal relates to measures taken during the trial. If the decision is set aside, the ordinary rules laid down in the preceding articles shall be applicable. English version (STL Draft Official Translation of Arabic) Version 1.0 89 Part X Applications for Pardons', 'en', 'Code of Criminal Procedure (Expanded), Article 390', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '391', 'The Higher Council of the Judiciary has jurisdiction to consider applications for pardons submitted by persons sentenced to death pursuant to a final judgement or referred to it by the competent authorities.', 'en', 'Code of Criminal Procedure (Expanded), Article 391', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '392', 'All applications for pardons in respect of a death penalty shall be submitted to the President of the Republic directly or through the Minister of Justice in the form of a petition signed by the convicted person, his advocate or a member of his family. The petition shall be exempt from stamp duty and legal charges.', 'en', 'Code of Criminal Procedure (Expanded), Article 392', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '393', 'When the death sentence is confirmed, the Minister of Justice shall refer the case file, together with the report of the Public Prosecutor at the Court of Cassation, to the Higher Council of the Judiciary, which has ten days to deliver its opinion on the enforcement or commutation of the sentence.', 'en', 'Code of Criminal Procedure (Expanded), Article 393', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '394', 'The President of the Higher Council of the Judiciary or a Council member delegated by him shall prepare a report summarizing the facts of the case, the evidence on which the judgement was based, together with the grounds for the clemency petition, and shall give his opinion on the petition.', 'en', 'Code of Criminal Procedure (Expanded), Article 394', NULL, 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '395', 'After hearing the statement by its rapporteur and examining the documents, the Higher Council of the Judiciary shall consider the charge against the convicted person, the evidence on which the judgement was based, the grounds provided in support of the petition for a pardon, and the pre-conditions for enforcement or commutation of the death sentence to another sentence; it shall deliver its opinion in camera either to reject the petition or to grant it, with a proposal to commute the death sentence, and shall submit a report to the Minister of Justice.', 'en', 'Code of Criminal Procedure (Expanded), Article 395', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '396', 'The Higher Council of the Judiciary shall set up a Commission, composed of three of its members, to consider all other petitions for a special pardon. The Commission may decide, in accordance with the above-mentioned rules, on petitions for a special pardon in respect of judgements imposing sentences other than the death penalty for felonies or imposing sentences for misdemeanours.', 'en', 'Code of Criminal Procedure (Expanded), Article 396', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '397', 'When a clemency petition is filed, enforcement of the judgement shall be stayed if the sentence consists of a fine or imprisonment for less than one year where the convicted person is not already in detention pursuant to a notice sent by the President of the Commission to the Public Prosecutor at the Court of Cassation informing him of the receipt of the clemency petition.', 'en', 'Code of Criminal Procedure (Expanded), Article 397', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '398', 'If the President of the Republic rejects the clemency petition, a person sentenced to hard labour for life or for a period of at least ten years may not file another petition until three years have elapsed in the first case and two years in the second case from the date of notification of the rejection. In other cases the convicted person may file a second clemency petition after one year has elapsed. He may not file a further clemency petition if the sentence consists of a fine or imprisonment for one year or less. However, this shall not preclude the President of the Republic from exercising his right to order the filing of a new clemency petition to the Commission. English version (STL Draft Official Translation of Arabic) Version 1.0 90', 'en', 'Code of Criminal Procedure (Expanded), Article 398', 'Penalties and sentencing', 'Criminal Law'),
  ('LB-CRIM-002-EXPANDED', '399', 'If the President of the Republic grants the clemency petition, he shall issue a decree to that effect. English version (STL Draft Official Translation of Arabic) Version 1.0 91 Part XI Judicial oversight of remand centres and prisons and protection of personal freedom from unlawful detention', 'en', 'Code of Criminal Procedure (Expanded), Article 399', NULL, 'Criminal Law');
